1	// Cyrus Config and Stats Studio: ConfigSpec v1, the ONE typed model of a mod's tunable settings (mob stats, weapon
2	// stats, ability cooldowns, shop prices, boss phases, quest rewards, arena timers...). GAME-NEUTRAL: a param is a
3	// typed value at a dotted key with limits, units and how a change takes effect; per-game exporters (./exporters.ts)
4	// say how a file is written and reloaded. The designers' params (lib/cyrus/designer) convert into this model
5	// (./designer.ts), imported mods get an inferred spec (./infer.ts), AI-built mods declare one (assets/config/schema.json).
6	// Pure + client-safe. Zod in code, `configSpecJsonSchema()` is the portable contract. Rule failures come back as
7	// structured issues { path, code, message }, never a thrown error.
8	import { z } from "zod";
9	
10	export const CONFIG_SPEC_VERSION = 1 as const;
11	
12	export const PARAM_TYPES = ["number", "int", "range", "bool", "enum", "text", "color", "duration", "sound-ref", "asset-ref", "list", "table"] as const;
13	export type ParamType = (typeof PARAM_TYPES)[number];
14	export const NUMERIC_TYPES: readonly ParamType[] = ["number", "int", "duration", "range"];
15	
16	/** How a changed value reaches a running server: re-read on its own / the mod's reload command / a server restart. */
17	export const APPLIES = ["live", "reload", "restart"] as const;
18	export type Applies = (typeof APPLIES)[number];
19	export const APPLIES_RANK: Record<Applies, number> = { live: 0, reload: 1, restart: 2 };
20	
21	/** Stat -> viewport links (./visual.ts): clip playback rate, model scale, fire cadence, colour. */
22	export const VISUAL_CHANNELS = ["clipRate", "attackRate", "scale", "fireRate", "tint"] as const;
23	export type VisualChannel = (typeof VISUAL_CHANNELS)[number];
24	
25	export const DURATION_UNITS = ["ticks", "s", "ms"] as const;
26	export type DurationUnit = (typeof DURATION_UNITS)[number];
27	export const ASSET_REF_KINDS = ["texture", "model", "sound", "item"] as const;
28	
29	export const CONFIG_LIMITS = { params: 400, groups: 32, presets: 12, options: 64, listItems: 256, tableRows: 256, columns: 12, textChars: 1024, keyChars: 160, keyDepth: 10 } as const;
30	
31	/** One dotted config path segment: letters, digits, `_` and `-` (imported mods use camelCase and kebab-case keys). */
32	export const KEY_SEGMENT_RE = /^[A-Za-z0-9_][A-Za-z0-9_-]{0,63}$/;
33	export const ID_RE = /^[a-z][a-z0-9_-]{0,31}$/;
34	export const COLOR_RE = /^#[0-9a-fA-F]{6}$/;
35	/** A namespaced sound key (minecraft:entity.zombie.ambient, nx_abcd1234:gun.fire); other games use the same shape. */
36	export const SOUND_KEY_RE = /^[a-z0-9_.-]{1,64}:[a-z0-9_.-]{1,128}(\/[a-z0-9_.-]{1,64})*$/;
37	export const UNIT_RE = /^[A-Za-z%°/ .-]{1,16}$/;
38	export const RELOAD_COMMAND_RE = /^\/?[a-z0-9_:-]{1,32}( [a-z0-9_-]{1,32}){0,3}$/;
39	export const FILE_RE = /^(?![/\\])(?!.*\.\.)[A-Za-z0-9_./-]{1,120}\.(yml|yaml|json|toml|cfg|properties)$/;
40	
41	export function isConfigKey(k: unknown): k is string {
42	  if (typeof k !== "string" || !k.length || k.length > CONFIG_LIMITS.keyChars) return false;
43	  const segs = k.split(".");
44	  return segs.length <= CONFIG_LIMITS.keyDepth && segs.every((s) => KEY_SEGMENT_RE.test(s) && s !== "__proto__" && s !== "constructor" && s !== "prototype");
45	}
46	
47	const line = (max: number) => z.string().trim().min(1).max(max);
48	const Scalar = z.union([z.number(), z.string().max(CONFIG_LIMITS.textChars), z.boolean()]);
49	export type ScalarValue = z.infer<typeof Scalar>;
50	/** A value as stored: number (number/int/duration), [lo, hi] (range), boolean, string (enum/text/color/refs), list, table rows. */
51	export const ConfigValueZ = z.union([
52	  z.number(), z.boolean(), z.string().max(CONFIG_LIMITS.textChars),
53	  z.array(Scalar).max(CONFIG_LIMITS.listItems),
54	  z.array(z.record(z.string(), Scalar)).max(CONFIG_LIMITS.tableRows),
55	]);
56	export type ConfigValue = number | boolean | string | ScalarValue[] | Record<string, ScalarValue>[];
57	export type ConfigValues = Record<string, ConfigValue>;
58	
59	const OptionZ = z.object({ value: z.union([z.string().max(64), z.number()]), label: line(60).optional() }).strict();
60	const SafeZ = z.object({ min: z.number().optional(), max: z.number().optional(), note: line(200).optional() }).strict();
61	const VisualZ = z.object({
62	  channel: z.enum(VISUAL_CHANNELS),
63	  /** clipRate / fireRate: the clip the stat drives ("walk", "attack", "fire", "reload"). */
64	  clip: z.string().regex(/^[a-z][a-z0-9_]{0,31}$/).optional(),
65	  /** The value at which the clip plays at 1x (or the model is scale 1). */
66	  ref: z.number().positive().optional(),
67	  /** true: the rate goes DOWN as the value goes up (reload time: longer reload = slower clip). */
68	  inverse: z.boolean().optional(),
69	}).strict();
70	
71	/** A list item / table column: a scalar param without groups, presets or visuals. */
72	const CellZ = z.object({
73	  type: z.enum(["number", "int", "bool", "enum", "text", "color", "sound-ref", "asset-ref"]),
74	  min: z.number().optional(), max: z.number().optional(), step: z.number().positive().optional(),
75	  unit: z.string().regex(UNIT_RE).optional(),
76	  options: z.array(OptionZ).min(1).max(CONFIG_LIMITS.options).optional(),
77	  maxLength: z.number().int().min(1).max(CONFIG_LIMITS.textChars).optional(),
78	}).strict();
79	const ColumnZ = CellZ.extend({ key: z.string().regex(KEY_SEGMENT_RE), label: line(40), default: Scalar.optional() }).strict();
80	
81	export const ConfigParamZ = z.object({
82	  key: z.string().refine(isConfigKey, "keys are dotted paths of letters, digits, _ and - (max 10 levels, 160 chars)"),
83	  group: z.string().regex(ID_RE),
84	  type: z.enum(PARAM_TYPES),
85	  label: line(60),
86	  help: line(200).optional(),
87	  default: ConfigValueZ,
88	  unit: z.string().regex(UNIT_RE).optional(),
89	  /** HARD limits: the generated loader clamps to them and the editor refuses values outside them. */
90	  min: z.number().optional(),
91	  max: z.number().optional(),
92	  step: z.number().positive().optional(),
93	  /** The BALANCE range: outside it the editor warns but saves. */
94	  safe: SafeZ.optional(),
95	  durationUnit: z.enum(DURATION_UNITS).optional(),
96	  options: z.array(OptionZ).min(1).max(CONFIG_LIMITS.options).optional(),
97	  maxLength: z.number().int().min(1).max(CONFIG_LIMITS.textChars).optional(),
98	  assetKind: z.enum(ASSET_REF_KINDS).optional(),
99	  item: CellZ.optional(),
100	  maxItems: z.number().int().min(1).max(CONFIG_LIMITS.listItems).optional(),
101	  columns: z.array(ColumnZ).min(1).max(CONFIG_LIMITS.columns).optional(),
102	  maxRows: z.number().int().min(1).max(CONFIG_LIMITS.tableRows).optional(),
103	  applies: z.enum(APPLIES).default("restart"),
104	  visual: VisualZ.optional(),
105	  tags: z.array(z.string().regex(/^[a-z][a-z0-9_-]{0,23}$/)).max(8).default([]),
106	  advanced: z.boolean().optional(),
107	  readOnly: z.boolean().optional(),
108	}).strict();
109	
110	const GroupZ = z.object({ id: z.string().regex(ID_RE), label: line(60), help: line(200).optional(), order: z.number().int().min(0).max(999).optional() }).strict();
111	const PresetZ = z.object({ id: z.string().regex(ID_RE), label: line(40), help: line(200).optional(), values: z.record(z.string(), ConfigValueZ) }).strict();
112	
113	export const ConfigSpecV1Schema = z.object({
114	  schemaVersion: z.literal(1),
115	  /** Where the values live, relative to the mod's data folder (Paper: plugins/<plugin>/config.yml). */
116	  file: z.string().regex(FILE_RE).default("config.yml"),
117	  format: z.enum(["yaml", "json", "toml", "properties"]).default("yaml"),
118	  /** The category template this spec started from (./templates.ts), if any. */
119	  category: z.string().regex(ID_RE).optional(),
120	  /** Inferred from an existing config file (imported mod): no balance claims, type checks only. */
121	  inferred: z.boolean().optional(),
122	  /** How `applies: "reload"` is done: the mod's own reload command (console). */
123	  reload: z.object({ command: z.string().regex(RELOAD_COMMAND_RE) }).strict().optional(),
124	  groups: z.array(GroupZ).min(1).max(CONFIG_LIMITS.groups),
125	  params: z.array(ConfigParamZ).min(1).max(CONFIG_LIMITS.params),
126	  presets: z.array(PresetZ).max(CONFIG_LIMITS.presets).default([]),
127	}).strict();
128	
129	export type ConfigSpec = z.output<typeof ConfigSpecV1Schema>;
130	export type ConfigSpecInput = z.input<typeof ConfigSpecV1Schema>;
131	export type ConfigParam = ConfigSpec["params"][number];
132	export type ConfigParamInput = z.input<typeof ConfigParamZ>;
133	export type ConfigGroup = ConfigSpec["groups"][number];
134	export type ConfigPreset = ConfigSpec["presets"][number];
135	export type CellSpec = z.output<typeof CellZ>;
136	export type ColumnSpec = z.output<typeof ColumnZ>;
137	export type ConfigIssue = { path: string; code: string; message: string };
138	
139	/** JSON Schema (draft 2020-12) of what a producer (the AI, an exporter, a test) writes. */
140	export function configSpecJsonSchema(): Record<string, unknown> {
141	  return z.toJSONSchema(ConfigSpecV1Schema, { io: "input" }) as Record<string, unknown>;
142	}
143	
144	// --------------------------------------------------------------------------------------------- cell / value rules
145	
146	const isNum = (v: unknown): v is number => typeof v === "number" && Number.isFinite(v);
147	const decimals = (x: number) => { const s = String(x); const i = s.indexOf("."); return i < 0 ? 0 : s.length - i - 1; };
148	
149	/** Check one scalar against a cell spec (list items, table cells). Returns an error message or null. */
150	export function cellError(c: Pick<CellSpec, "type" | "min" | "max" | "options" | "maxLength">, v: unknown): string | null {
151	  switch (c.type) {
152	    case "number": case "int":
153	      if (!isNum(v)) return "needs a number";
154	      if (c.type === "int" && !Number.isInteger(v)) return "needs a whole number";
155	      if (c.min !== undefined && v < c.min) return `is below the minimum ${c.min}`;
156	      if (c.max !== undefined && v > c.max) return `is above the maximum ${c.max}`;
157	      return null;
158	    case "bool": return typeof v === "boolean" ? null : "needs true or false";
159	    case "enum": return c.options?.some((o) => o.value === v) ? null : `must be one of ${(c.options ?? []).map((o) => o.value).join(", ")}`;
160	    case "text": return typeof v !== "string" ? "needs text" : v.length > (c.maxLength ?? 256) ? `is longer than ${c.maxLength ?? 256} characters` : /[\u0000-\u0008\u000b-\u001f]/.test(v) ? "has control characters" : null;
161	    case "color": return typeof v === "string" && COLOR_RE.test(v) ? null : "needs a colour like #ff8800";
162	    case "sound-ref": return typeof v === "string" && (v === "" || SOUND_KEY_RE.test(v)) ? null : "needs a namespaced sound key (namespace:path)";
163	    case "asset-ref": return typeof v === "string" && /^[a-z0-9_.:/-]{0,160}$/.test(v) ? null : "needs an asset id";
164	  }
165	}
166	
167	/** Is a value of the right SHAPE for a param (type only; limits are ./values.ts). */
168	export function shapeError(p: Pick<ConfigParam, "type" | "options" | "item" | "columns" | "maxLength" | "maxItems" | "maxRows">, v: unknown): string | null {
169	  switch (p.type) {
170	    case "number": case "duration": return isNum(v) ? null : "needs a number";
171	    case "int": return isNum(v) && Number.isInteger(v) ? null : "needs a whole number";
172	    case "range": return Array.isArray(v) && v.length === 2 && isNum(v[0]) && isNum(v[1]) ? (v[0] <= v[1] ? null : "the low end is above the high end") : "needs [low, high]";
173	    case "bool": case "enum": case "text": case "color": case "sound-ref": case "asset-ref":
174	      return cellError({ type: p.type, options: p.options, maxLength: p.maxLength }, v);
175	    case "list": {
176	      if (!Array.isArray(v)) return "needs a list";
177	      if (v.length > (p.maxItems ?? CONFIG_LIMITS.listItems)) return `has more than ${p.maxItems ?? CONFIG_LIMITS.listItems} items`;
178	      if (!p.item) return null;
179	      for (let i = 0; i < v.length; i++) { const e = cellError({ ...p.item, min: undefined, max: undefined }, v[i]); if (e) return `item ${i + 1} ${e}`; }
180	      return null;
181	    }
182	    case "table": {
183	      if (!Array.isArray(v)) return "needs rows";
184	      if (v.length > (p.maxRows ?? CONFIG_LIMITS.tableRows)) return `has more than ${p.maxRows ?? CONFIG_LIMITS.tableRows} rows`;
185	      for (let i = 0; i < v.length; i++) {
186	        const row = v[i];
187	        if (!row || typeof row !== "object" || Array.isArray(row)) return `row ${i + 1} is not a row`;
188	        for (const c of p.columns ?? []) {
189	          const cell = (row as Record<string, unknown>)[c.key];
190	          if (cell === undefined) { if (c.default === undefined) return `row ${i + 1} has no ${c.key}`; continue; }
191	          const e = cellError({ ...c, min: undefined, max: undefined }, cell);
192	          if (e) return `row ${i + 1} ${c.key} ${e}`;
193	        }
194	      }
195	      return null;
196	    }
197	  }
198	}
199	
200	// --------------------------------------------------------------------------------------------- validation
201	
202	export type ConfigValidateResult = { ok: true; spec: ConfigSpec; warnings: ConfigIssue[] } | { ok: false; errors: ConfigIssue[]; warnings: ConfigIssue[] };
203	const pathOf = (p: readonly PropertyKey[]) => p.map((k) => (typeof k === "number" ? `[${k}]` : `.${String(k)}`)).join("").replace(/^\./, "");
204	
205	/** Untrusted JSON -> ConfigSpec, or every problem found (schema + cross-field rules). */
206	export function validateConfigSpec(raw: unknown): ConfigValidateResult {
207	  const parsed = ConfigSpecV1Schema.safeParse(raw);
208	  if (!parsed.success) return { ok: false, warnings: [], errors: parsed.error.issues.slice(0, 50).map((i) => ({ path: pathOf(i.path), code: i.code, message: i.message })) };
209	  const spec = parsed.data;
210	  const errors: ConfigIssue[] = [];
211	  const warnings: ConfigIssue[] = [];
212	  const err = (path: string, code: string, message: string) => errors.push({ path, code, message });
213	
214	  const groups = new Set<string>();
215	  spec.groups.forEach((g, i) => { if (groups.has(g.id)) err(`groups[${i}].id`, "duplicate_group", `group ${g.id} is listed twice`); groups.add(g.id); });
216	  const keys = new Set<string>();
217	  spec.params.forEach((p, i) => { if (keys.has(p.key)) err(`params[${i}].key`, "duplicate_key", `${p.key} is listed twice`); keys.add(p.key); });
218	  // a.b and a.b.c cannot both be settings (one is a value, the other a section)
219	  const sorted = [...keys].sort();
220	  for (let i = 0; i + 1 < sorted.length; i++) if (sorted[i + 1].startsWith(sorted[i] + ".")) err("params", "key_prefix", `${sorted[i]} is a setting and also a section (${sorted[i + 1]})`);
221	
222	  spec.params.forEach((p, i) => {
223	    const at = `params[${i}]`;
224	    if (!groups.has(p.group)) err(`${at}.group`, "unknown_group", `${p.key} is in group ${p.group}, which is not listed`);
225	    const numeric = (NUMERIC_TYPES as readonly string[]).includes(p.type);
226	    if (!numeric && (p.min !== undefined || p.max !== undefined || p.safe || p.step !== undefined)) err(at, "limits_on_non_number", `${p.key}: only number, int, duration and range settings have limits`);
227	    if (p.min !== undefined && p.max !== undefined && p.min > p.max) err(at, "min_above_max", `${p.key}: min ${p.min} is above max ${p.max}`);
228	    if (p.type === "int" && [p.min, p.max, p.step].some((x) => x !== undefined && !Number.isInteger(x))) err(at, "int_limits", `${p.key}: whole-number settings need whole-number limits`);
229	    if (p.safe) {
230	      const s = p.safe;
231	      if (s.min !== undefined && s.max !== undefined && s.min > s.max) err(`${at}.safe`, "safe_inverted", `${p.key}: the balanced range is inverted`);
232	      if ((p.min !== undefined && s.min !== undefined && s.min < p.min) || (p.max !== undefined && s.max !== undefined && s.max > p.max)) err(`${at}.safe`, "safe_outside_limits", `${p.key}: the balanced range must sit inside the hard limits`);
233	    }
234	    if (p.type === "duration" && !p.durationUnit) err(at, "duration_unit", `${p.key}: a duration needs durationUnit (ticks, s or ms)`);
235	    if (p.type !== "duration" && p.durationUnit) err(at, "duration_unit", `${p.key}: durationUnit is only for durations`);
236	    if (p.type === "enum") {
237	      if (!p.options) err(at, "enum_options", `${p.key}: an enum needs options`);
238	      else if (new Set(p.options.map((o) => String(o.value))).size !== p.options.length) err(`${at}.options`, "duplicate_option", `${p.key}: an option is listed twice`);
239	    } else if (p.options) err(at, "options_on_non_enum", `${p.key}: only enums have options`);
240	    if (p.type === "list" && !p.item) err(at, "list_item", `${p.key}: a list needs item (the type of each entry)`);
241	    if (p.type !== "list" && (p.item || p.maxItems)) err(at, "item_on_non_list", `${p.key}: item/maxItems are only for lists`);
242	    if (p.type === "table") {
243	      if (!p.columns) err(at, "table_columns", `${p.key}: a table needs columns`);
244	      else if (new Set(p.columns.map((c) => c.key)).size !== p.columns.length) err(`${at}.columns`, "duplicate_column", `${p.key}: a column is listed twice`);
245	    } else if (p.columns || p.maxRows) err(at, "columns_on_non_table", `${p.key}: columns/maxRows are only for tables`);
246	    if (p.type === "asset-ref" && !p.assetKind) err(at, "asset_kind", `${p.key}: an asset reference needs assetKind`);
247	    for (const c of [p.item, ...(p.columns ?? [])]) {
248	      if (!c) continue;
249	      if (c.type === "enum" && !c.options) err(at, "enum_options", `${p.key}: an enum cell needs options`);
250	      if (c.min !== undefined && c.max !== undefined && c.min > c.max) err(at, "min_above_max", `${p.key}: a cell's min is above its max`);
251	    }
252	    if (p.applies === "reload" && !spec.reload) err(`${at}.applies`, "reload_without_command", `${p.key} applies on reload, but the spec names no reload command`);
253	    if (p.visual) {
254	      if (!["number", "int", "duration", "color"].includes(p.type)) err(`${at}.visual`, "visual_type", `${p.key}: only numbers, durations and colours drive the viewport`);
255	      if (p.visual.channel === "tint" ? p.type !== "color" : p.type === "color") err(`${at}.visual`, "visual_channel", `${p.key}: tint is the colour channel`);
256	      if (p.visual.channel !== "tint" && p.visual.ref === undefined) err(`${at}.visual`, "visual_ref", `${p.key}: a ${p.visual.channel} link needs ref (the value at 1x)`);
257	      if ((p.visual.channel === "clipRate" || p.visual.channel === "fireRate") && !p.visual.clip) err(`${at}.visual`, "visual_clip", `${p.key}: name the clip it drives`);
258	    }
259	    // the default must be valid (shape + limits)
260	    const se = shapeError(p, p.default);
261	    if (se) err(`${at}.default`, "bad_default", `${p.key}: the default ${se}`);
262	    else {
263	      const lo = p.min, hi = p.max;
264	      const vals = p.type === "range" ? (p.default as number[]) : numeric ? [p.default as number] : [];
265	      if (vals.some((v) => (lo !== undefined && v < lo) || (hi !== undefined && v > hi))) err(`${at}.default`, "default_outside_limits", `${p.key}: the default is outside ${lo ?? "-inf"}-${hi ?? "inf"}`);
266	      if (p.safe && vals.some((v) => (p.safe!.min !== undefined && v < p.safe!.min) || (p.safe!.max !== undefined && v > p.safe!.max))) warnings.push({ path: `${at}.default`, code: "default_unbalanced", message: `${p.key}: the default is outside its own balanced range` });
267	      if (p.type === "list" && p.item && (p.item.min !== undefined || p.item.max !== undefined)) for (const v of p.default as unknown[]) { const e = cellError(p.item, v); if (e) { err(`${at}.default`, "bad_default", `${p.key}: a default item ${e}`); break; } }
268	    }
269	    if (p.step !== undefined && numeric && p.type !== "range" && decimals(p.step) > 6) warnings.push({ path: `${at}.step`, code: "tiny_step", message: `${p.key}: a step below 0.000001 is not useful` });
270	  });
271	
272	  const byKey = new Map(spec.params.map((p) => [p.key, p]));
273	  const presetIds = new Set<string>();
274	  spec.presets.forEach((pr, i) => {
275	    if (presetIds.has(pr.id)) err(`presets[${i}].id`, "duplicate_preset", `preset ${pr.id} is listed twice`);
276	    presetIds.add(pr.id);
277	    for (const [k, v] of Object.entries(pr.values)) {
278	      const p = byKey.get(k);
279	      if (!p) { err(`presets[${i}].values.${k}`, "unknown_key", `preset ${pr.id} sets ${k}, which is not a setting`); continue; }
280	      if (p.readOnly) err(`presets[${i}].values.${k}`, "read_only", `preset ${pr.id} sets the read-only ${k}`);
281	      const se = shapeError(p, v);
282	      const vals = se ? [] : p.type === "range" ? (v as number[]) : numeric(p) ? [v as number] : [];
283	      if (se) err(`presets[${i}].values.${k}`, "bad_value", `preset ${pr.id}: ${k} ${se}`);
284	      else if (vals.some((x) => (p.min !== undefined && x < p.min) || (p.max !== undefined && x > p.max))) err(`presets[${i}].values.${k}`, "outside_limits", `preset ${pr.id}: ${k} is outside its limits`);
285	    }
286	  });
287	  if (spec.inferred && spec.params.some((p) => p.safe)) warnings.push({ path: "params", code: "inferred_safe", message: "an inferred spec should not claim balanced ranges" });
288	  return errors.length ? { ok: false, errors, warnings } : { ok: true, spec, warnings };
289	}
290	
291	export const numeric = (p: Pick<ConfigParam, "type">) => (NUMERIC_TYPES as readonly string[]).includes(p.type);
292	export const paramByKey = (spec: Pick<ConfigSpec, "params">) => new Map(spec.params.map((p) => [p.key, p]));
293	
294	/** Stable canonical JSON (sorted keys) for hashing specs and values. */
295	export function canonical(v: unknown): string {
296	  if (Array.isArray(v)) return `[${v.map(canonical).join(",")}]`;
297	  if (v && typeof v === "object") return `{${Object.keys(v as object).sort().map((k) => `${JSON.stringify(k)}:${canonical((v as Record<string, unknown>)[k])}`).join(",")}}`;
298	  return JSON.stringify(v);
299	}
300

1	// Cyrus Config Studio: VALUE checking. Coercion from editor/YAML input, hard-limit checks (strict: refuse; clamp: what
2	// the generated runtime loader does), balance warnings (the `safe` range), defaults, display formatting. Pure.
3	import { CONFIG_LIMITS, cellError, numeric, paramByKey, shapeError, type ConfigParam, type ConfigSpec, type ConfigValue, type ConfigValues, type ScalarValue } from "./spec";
4	
5	export type ValueMode = "strict" | "clamp";
6	export type ValueIssue = { key: string; code: string; message: string };
