17	/** Text from a form field or a YAML scalar -> the param's value type (numbers from strings, "true"/"false"). */
18	export function coerce(p: Pick<ConfigParam, "type" | "item" | "columns" | "options">, raw: unknown): unknown {
19	  const num = (v: unknown) => (typeof v === "string" && /^\s*[-+]?(\d+(\.\d*)?|\.\d+)([eE][-+]?\d+)?\s*$/.test(v) ? Number(v) : v);
20	  const bool = (v: unknown) => (typeof v === "string" && /^(true|false|yes|no|on|off)$/i.test(v.trim()) ? /^(true|yes|on)$/i.test(v.trim()) : v);
21	  const cell = (type: string, v: unknown, options?: ConfigParam["options"]) => {
22	    if (type === "number" || type === "int") return num(v);
23	    if (type === "bool") return bool(v);
24	    if (type === "enum" && options?.some((o) => typeof o.value === "number")) return num(v);
25	    if (type === "enum" || type === "text" || type === "color" || type === "sound-ref" || type === "asset-ref") return typeof v === "number" || typeof v === "boolean" ? String(v) : v === null ? "" : v;
26	    return v;
27	  };
28	  switch (p.type) {
29	    case "number": case "int": case "duration": return num(raw);
30	    case "range": {
31	      if (typeof raw === "string") { const m = /^\s*(-?[\d.]+)\s*(?:-|to|\.\.)\s*(-?[\d.]+)\s*$/.exec(raw); if (m) return [Number(m[1]), Number(m[2])]; }
32	      return Array.isArray(raw) ? raw.map(num) : raw;
33	    }
34	    case "list": return Array.isArray(raw) ? raw.map((v) => cell(p.item?.type ?? "text", v, p.item?.options)) : raw;
35	    case "table": return Array.isArray(raw) ? raw.map((row) => (row && typeof row === "object" && !Array.isArray(row) ? Object.fromEntries(Object.entries(row as Record<string, unknown>).map(([k, v]) => { const c = p.columns?.find((x) => x.key === k); return [k, c ? cell(c.type, v, c.options) : v]; })) : row)) : raw;
36	    default: return cell(p.type, raw, p.options);
37	  }
38	}
