40	/** Balance warnings: a value outside `safe` (never an error). */
41	export function balanceWarnings(p: ConfigParam, v: ConfigValue): ValueIssue[] {
42	  if (!p.safe || !numeric(p)) return [];
43	  const vals = p.type === "range" ? (v as number[]) : [v as number];
44	  const u = p.unit ? ` ${p.unit}` : "";
45	  const out: ValueIssue[] = [];
46	  const lo = p.safe.min, hi = p.safe.max;
47	  if (lo !== undefined && vals.some((x) => x < lo)) out.push({ key: p.key, code: "below_balanced", message: `${p.label} ${fmt(p, v)} is below the balanced range (${lo}${u} or more)${p.safe.note ? `: ${p.safe.note}` : ""}` });
48	  if (hi !== undefined && vals.some((x) => x > hi)) out.push({ key: p.key, code: "above_balanced", message: `${p.label} ${fmt(p, v)} is above the balanced range (${hi}${u} or less)${p.safe.note ? `: ${p.safe.note}` : ""}` });
49	  return out;
50	}
