52	/** Check one value: coerce, shape, hard limits (strict refuses, clamp clamps), step rounding, balance warnings. */
53	export function checkValue(p: ConfigParam, raw: unknown, mode: ValueMode = "strict"): CheckedValue {
54	  const bad = (code: string, message: string): CheckedValue => ({ ok: false, error: { key: p.key, code, message: `${p.label}: ${message}` } });
55	  let v = coerce(p, raw);
56	  if (p.type === "int" && isNum(v) && !Number.isInteger(v) && mode === "clamp") v = Math.round(v);
57	  const se = shapeError(p, v);
58	  if (se) return bad("bad_type", se);
59	  let clamped = false;
60	  const lim = (x: number) => {
61	    let y = x;
62	    if (p.min !== undefined && y < p.min) y = p.min;
63	    if (p.max !== undefined && y > p.max) y = p.max;
64	    if (y !== x) clamped = true;
65	    return y;
66	  };
67	  if (numeric(p)) {
68	    const vals = p.type === "range" ? [...(v as number[])] : [v as number];
69	    const out = vals.map((x) => {
70	      if (mode === "strict" && ((p.min !== undefined && x < p.min) || (p.max !== undefined && x > p.max))) return NaN;
71	      return round(lim(x), p.type === "int" ? Math.max(1, p.step ?? 1) : p.step);
72	    });
73	    if (out.some((x) => Number.isNaN(x))) return bad("outside_limits", `${fmt(p, v as ConfigValue)} is outside the allowed ${p.min ?? "-inf"}-${p.max ?? "inf"}${p.unit ? ` ${p.unit}` : ""}`);
74	    v = p.type === "range" ? out : out[0];
75	    if (p.type === "range" && (v as number[])[0] > (v as number[])[1]) return bad("bad_type", "the low end is above the high end");
76	  }
77	  if (p.type === "list" && p.item && (p.item.min !== undefined || p.item.max !== undefined)) {
78	    const it = p.item;
79	    const arr = (v as ScalarValue[]).map((x) => {
80	      if (!isNum(x)) return x;
81	      if (mode === "clamp") { const y = Math.min(it.max ?? Infinity, Math.max(it.min ?? -Infinity, x)); if (y !== x) clamped = true; return y; }
82	      return x;
83	    });
84	    for (const x of arr) { const e = cellError(it, x); if (e) return bad("outside_limits", `an item ${e}`); }
85	    v = arr;
86	  }
87	  if (p.type === "table") {
88	    const rows = (v as Record<string, ScalarValue>[]).map((row) => {
89	      const r: Record<string, ScalarValue> = {};
90	      for (const c of p.columns ?? []) {
91	        let x = row[c.key] ?? c.default;
92	        if (x === undefined) continue;
93	        if (isNum(x) && mode === "clamp") { const y = Math.min(c.max ?? Infinity, Math.max(c.min ?? -Infinity, x)); if (y !== x) clamped = true; x = y; }
94	        r[c.key] = x;
95	      }
96	      for (const [k, x] of Object.entries(row)) if (!(k in r) && !(p.columns ?? []).some((c) => c.key === k)) r[k] = x; // unknown columns are kept
97	      return r;
98	    });
99	    for (let i = 0; i < rows.length; i++) for (const c of p.columns ?? []) { if (rows[i][c.key] === undefined) continue; const e = cellError(c, rows[i][c.key]); if (e) return bad("outside_limits", `row ${i + 1} ${c.label} ${e}`); }
100	    v = rows;
101	  }
102	  return { ok: true, value: v as ConfigValue, clamped, warnings: balanceWarnings(p, v as ConfigValue) };
103	}
