109	/**
110	 * Check a full or partial value set against the spec. Missing keys take the default. Unknown keys are errors
111	 * (strict) or ignored with a warning (clamp: reading a file the server owner edited). Read-only keys may not change.
112	 */
113	export function checkValues(spec: ConfigSpec, values: Record<string, unknown>, mode: ValueMode = "strict", base: ConfigValues = defaultsOf(spec)): ValuesCheck {
114	  const byKey = paramByKey(spec);
115	  const errors: ValueIssue[] = [], warnings: ValueIssue[] = [], clamped: string[] = [];
116	  const out: ConfigValues = { ...base };
117	  const entries = Object.entries(values ?? {});
118	  if (entries.length > CONFIG_LIMITS.params) return { ok: false, values: out, errors: [{ key: "", code: "too_many", message: `at most ${CONFIG_LIMITS.params} settings` }], warnings, clamped };
119	  for (const [k, raw] of entries) {
120	    const p = byKey.get(k);
121	    if (!p) { (mode === "strict" ? errors : warnings).push({ key: k, code: "unknown_key", message: `${k} is not a setting of this mod` }); continue; }
122	    const r = checkValue(p, raw, mode);
123	    if (!r.ok) { errors.push(r.error); continue; }
124	    if (p.readOnly && !sameValue(r.value, base[k] ?? p.default)) { errors.push({ key: k, code: "read_only", message: `${p.label} cannot be changed here` }); continue; }
125	    out[k] = r.value;
126	    if (r.clamped) clamped.push(k);
127	    warnings.push(...r.warnings);
128	  }
129	  for (const p of spec.params) if (!entries.some(([k]) => k === p.key)) warnings.push(...balanceWarnings(p, out[p.key]));
130	  return { ok: errors.length === 0, values: out, errors, warnings, clamped };
131	}
