133	export function sameValue(a: unknown, b: unknown): boolean {
134	  if (a === b) return true;
135	  if (typeof a !== typeof b || a === null || b === null || typeof a !== "object") return false;
136	  if (Array.isArray(a) !== Array.isArray(b)) return false;
137	  if (Array.isArray(a)) return a.length === (b as unknown[]).length && a.every((x, i) => sameValue(x, (b as unknown[])[i]));
138	  const ka = Object.keys(a as object).sort(), kb = Object.keys(b as object).sort();
139	  return ka.length === kb.length && ka.every((k, i) => k === kb[i] && sameValue((a as Record<string, unknown>)[k], (b as Record<string, unknown>)[k]));
140	}
