144	const TICKS_PER_S = 20;
145	/** Duration value (in its storage unit) -> seconds, for display and the viewport. */
146	export function toSeconds(p: Pick<ConfigParam, "durationUnit">, v: number): number {
147	  return p.durationUnit === "ticks" ? v / TICKS_PER_S : p.durationUnit === "ms" ? v / 1000 : v;
148	}
149	/** Seconds typed in the editor -> the storage unit (ticks are whole numbers). */
150	export function fromSeconds(p: Pick<ConfigParam, "durationUnit">, s: number): number {
151	  return p.durationUnit === "ticks" ? Math.round(s * TICKS_PER_S) : p.durationUnit === "ms" ? Math.round(s * 1000) : Math.round(s * 1e4) / 1e4;
152	}
153	
154	const trim = (x: number) => String(Math.round(x * 1e4) / 1e4);
155	export function fmt(p: Pick<ConfigParam, "type" | "unit" | "durationUnit" | "options">, v: ConfigValue | undefined): string {
156	  if (v === undefined) return "-";
157	  const u = p.unit ? ` ${p.unit}` : "";
158	  switch (p.type) {
159	    case "duration": return `${trim(toSeconds(p, v as number))} s`;
160	    case "number": case "int": return `${trim(v as number)}${u}`;
161	    case "range": return `${trim((v as number[])[0])}-${trim((v as number[])[1])}${u}`;
162	    case "bool": return v ? "on" : "off";
163	    case "enum": return String(p.options?.find((o) => o.value === v)?.label ?? v);
164	    case "list": return `${(v as unknown[]).length} item${(v as unknown[]).length === 1 ? "" : "s"}`;
165	    case "table": return `${(v as unknown[]).length} row${(v as unknown[]).length === 1 ? "" : "s"}`;
166	    default: return String(v);
167	  }
168	}
