// Cyrus Config Studio: ConfigSpec <-> the mod's config file (YAML; the Paper exporter). Read the values a server's
// config.yml holds (clamped like the runtime loader), write changed values back WITHOUT touching anything else
// (comments, unknown keys, order, quoting: ./yamldoc.ts), and render a fresh, fully commented config.yml from a spec
// (every key with its label, unit, limits and help). Pure.
import type { YamlValue } from "../inventory/yaml";
import { parseYaml } from "../inventory/yaml";
import { numeric, type ConfigParam, type ConfigSpec, type ConfigValue, type ConfigValues } from "./spec";
import { checkValue, defaultsOf, sameValue, type ValueIssue } from "./values";
import { setYamlValue, type YamlOut, type YamlScalar } from "./yamldoc";

function at(root: YamlValue, key: string): { found: boolean; value: YamlValue } {
  let cur: YamlValue = root;
  for (const s of key.split(".")) {
    if (!cur || typeof cur !== "object" || Array.isArray(cur) || !Object.prototype.hasOwnProperty.call(cur, s)) return { found: false, value: null };
    cur = (cur as Record<string, YamlValue>)[s];
  }
  return { found: true, value: cur };
}

export type ReadResult = { values: ConfigValues; missing: string[]; clamped: string[]; errors: ValueIssue[]; issues: string[] };

/**
 * The values a config file holds for a spec. Missing keys take the default (listed in `missing`); an invalid value
 * takes the default (listed in `errors`); out-of-range numbers are clamped (listed in `clamped`), exactly what the
 * generated loader does on the server.
 */
export function readValues(spec: ConfigSpec, text: string): ReadResult {
  const r = parseYaml(text ?? "");
  const d = defaultsOf(spec);
  const out: ReadResult = { values: { ...d }, missing: [], clamped: [], errors: [], issues: r.issues };
  for (const p of spec.params) {
    const v = at(r.value, p.key);
    if (!v.found || v.value === null) { out.missing.push(p.key); continue; }
    const c = checkValue(p, v.value, "clamp");
    if (!c.ok) { out.errors.push(c.error); continue; }
    out.values[p.key] = c.value;
    if (c.clamped) out.clamped.push(p.key);
  }
  return out;
}

/** A value in the file's shape (durations stay in their storage unit). */
function toYaml(p: ConfigParam, v: ConfigValue): YamlOut {
  if (p.type === "range") return v as number[];
  return v as YamlOut;
}
const floatFor = (p: ConfigParam) => p.type === "number" || (p.type === "duration" && p.durationUnit === "s") || (p.type === "range" && !!p.step && !Number.isInteger(p.step));

/** The one-line comment Cyrus writes above a key it adds: label (unit, limits; balanced range). help */
export function keyComment(p: ConfigParam): string {
  const bits: string[] = [];
  if (p.type === "duration") bits.push(p.durationUnit === "ticks" ? "ticks, 20 = 1 s" : p.durationUnit === "ms" ? "milliseconds" : "seconds");
  else if (p.unit) bits.push(p.unit);
  if (numeric(p) && (p.min !== undefined || p.max !== undefined)) bits.push(`${p.min ?? "..."} to ${p.max ?? "..."}`);
  if (p.safe && (p.safe.min !== undefined || p.safe.max !== undefined)) bits.push(`balanced ${p.safe.min ?? "..."} to ${p.safe.max ?? "..."}`);
  if (p.type === "enum") bits.push(`one of: ${(p.options ?? []).map((o) => o.value).join(", ")}`);
  if (p.type === "bool") bits.push("true or false");
  if (p.applies === "restart") bits.push("needs a restart");
  return `${p.label}${bits.length ? ` (${bits.join("; ")})` : ""}.${p.help ? ` ${p.help}` : ""}`.slice(0, 300);
}

export type WriteResult = { ok: true; text: string; written: string[] } | { ok: false; errors: ValueIssue[] };

/** Write the values that differ from what the file holds now. Everything else in the file stays byte-identical. */
export function writeValues(spec: ConfigSpec, text: string, values: ConfigValues): WriteResult {
  const cur = readValues(spec, text);
  let t = text ?? "";
  const written: string[] = [];
  const errors: ValueIssue[] = [];
  for (const p of spec.params) {
    if (!(p.key in values)) continue;
    const c = checkValue(p, values[p.key], "strict");
    if (!c.ok) { errors.push(c.error); continue; }
    const present = !cur.missing.includes(p.key) && !cur.errors.some((e) => e.key === p.key) && !cur.clamped.includes(p.key);
    if (present && sameValue(cur.values[p.key], c.value)) continue;
    const r = setYamlValue(t, p.key, toYaml(p, c.value), {
      float: floatFor(p), comment: [keyComment(p)],
      floatCols: (col) => p.type === "table" ? p.columns?.find((x) => x.key === col)?.type === "number" : p.type === "list" ? p.item?.type === "number" : floatFor(p),
    });
    if (!r.ok) { errors.push({ key: p.key, code: "not_editable", message: r.error }); continue; }
    if (r.changed) written.push(p.key);
    t = r.text;
  }
  return errors.length ? { ok: false, errors } : { ok: true, text: t, written };
}

/**
 * A fresh config file for a spec: a header, then every key in spec order with its comment (the first key of each
 * group also carries the group's title). Built with the same editor, so the studio can always edit what it wrote.
 */
export function renderConfigYml(spec: ConfigSpec, values: ConfigValues = defaultsOf(spec), header: string[] = []): string {
  let t = header.map((h) => `# ${h}`.trimEnd()).join("\n") + (header.length ? "\n" : "");
  const seen = new Set<string>();
  const groups = new Map(spec.groups.map((g) => [g.id, g]));
  const ordered = [...spec.params].sort((a, b) => (groups.get(a.group)?.order ?? 0) - (groups.get(b.group)?.order ?? 0));
  for (const p of ordered) {
    const g = groups.get(p.group);
    const comment = [...(!seen.has(p.group) && g ? [`== ${g.label} ==${g.help ? ` ${g.help}` : ""}`] : []), keyComment(p)];
    seen.add(p.group);
    const v = (p.key in values ? values[p.key] : p.default) as ConfigValue;
    const r = setYamlValue(t, p.key, toYaml(p, v), {
      float: floatFor(p), comment,
      floatCols: (col) => p.type === "table" ? p.columns?.find((x) => x.key === col)?.type === "number" : p.type === "list" ? p.item?.type === "number" : floatFor(p),
    });
    if (r.ok) t = r.text;
  }
  return t.endsWith("\n") ? t : t + "\n";
}

export type { YamlScalar };
// Cyrus Config Studio: the deterministic "JUST TWEAK A SETTING" recogniser (no AI). Mirrors the designers'
// planDesignEdit grammar, against a ConfigSpec instead of designs:
//   [set|change|make|...] [the] <subject> (to|=) <value> [unit]   (clauses split by "and", ",", ";")
// Every clause must resolve to exactly ONE setting (all subject words found in its label / key / group / tags /
// synonyms) and a value that passes the strict check; anything else goes to the model. Durations take seconds by
// default, "%" on a 0-1 setting divides by 100, hearts double on hp settings. Pure. NOT wired into the build path
// (owner decision: skipping the model changes billing); the studio uses it for its command box.
import { paramByKey, type ConfigParam, type ConfigSpec, type ConfigValue, type ConfigValues } from "./spec";
import { checkValue, fmt } from "./values";
import { humanize } from "./infer";

export type ConfigEditPlan =
  | { kind: "values"; edits: { key: string; value: ConfigValue }[]; summary: string[] }
  | { kind: "model"; reason: string; candidates?: string[] };

const SYN: Record<string, string[]> = {
  hp: ["health"], health: ["hp"], dmg: ["damage"], damage: ["dmg", "attack"], cd: ["cooldown"], cooldown: ["cd", "recharge"],
  speed: ["movement", "move", "velocity"], movement: ["speed", "move"], walk: ["move", "movement", "speed"], mag: ["magazine"], magazine: ["mag", "clip"], clip: ["magazine"],
  price: ["cost", "buy"], cost: ["price"], rpm: ["fire", "rate"], firerate: ["fire", "rate"], size: ["scale"], scale: ["size"], range: ["reach", "radius", "distance"],
  reach: ["range"], radius: ["range", "area"], ammo: ["reserve", "magazine"], xp: ["experience"], experience: ["xp"], chance: ["probability", "odds"],
};
const STOP = new Set(["the", "a", "an", "of", "on", "for", "its", "my", "their", "his", "her", "please", "value", "setting", "stat"]);
const norm = (s: string) => s.toLowerCase().replace(/[_.\-]/g, " ").replace(/[^a-z0-9% ]+/g, " ").replace(/\s+/g, " ").trim();

function haystack(p: ConfigParam, groupLabel: string): Set<string> {
  const words = new Set<string>();
  const add = (s: string) => { for (const w of norm(s).split(" ")) if (w) { words.add(w); for (const x of SYN[w] ?? []) words.add(x); if (w.endsWith("s")) words.add(w.slice(0, -1)); } };
  add(p.label); add(p.key.split(".").map(humanize).join(" ")); add(groupLabel); p.tags.forEach(add);
  if (p.unit) add(p.unit);
  return words;
}

function parseValue(p: ConfigParam, raw: string): { ok: true; value: unknown } | { ok: false; reason: string } {
  const t = raw.trim().replace(/[.!?]+$/, "");
  switch (p.type) {
    case "bool": {
      if (/^(on|true|yes|enabled?)$/i.test(t)) return { ok: true, value: true };
      if (/^(off|false|no|disabled?)$/i.test(t)) return { ok: true, value: false };
      return { ok: false, reason: `"${t}" is not on or off` };
    }
    case "enum": { const o = p.options?.find((x) => String(x.value).toLowerCase() === t.toLowerCase() || String(x.label ?? "").toLowerCase() === t.toLowerCase()); return o ? { ok: true, value: o.value } : { ok: false, reason: `"${t}" is not one of ${(p.options ?? []).map((x) => x.value).join(", ")}` }; }
    case "text": return { ok: true, value: t.replace(/^["']|["']$/g, "") };
    case "color": return { ok: true, value: t };
    case "sound-ref": return { ok: true, value: t.replace(/\s+/g, "").toLowerCase() };
    case "number": case "int": case "duration": {
      const m = /^(-?\d+(?:\.\d+)?)\s*(s|sec|secs|seconds?|ticks?|ms|milliseconds?|min|minutes?|%|percent|hearts?|hp|blocks?|x|rpm|rounds?|coins?)?$/i.exec(t);
      if (!m) return { ok: false, reason: `"${t}" is not a number` };
      let x = Number(m[1]);
      const u = (m[2] ?? "").toLowerCase();
      if (p.type === "duration") {
        const secs = /^tick/.test(u) ? x / 20 : /^(ms|milli)/.test(u) ? x / 1000 : /^min/.test(u) ? x * 60 : x;
        x = p.durationUnit === "ticks" ? Math.round(secs * 20) : p.durationUnit === "ms" ? Math.round(secs * 1000) : secs;
      } else if (/^(%|percent)$/.test(u) && p.unit !== "%" && p.max !== undefined && p.max <= 1) x = x / 100;
      else if (/^heart/.test(u) && p.unit === "hp") x = x * 2;
      return { ok: true, value: x };
    }
    default: return { ok: false, reason: `${p.label} is a ${p.type}: edit it in the studio` };
  }
}

export function planConfigEdit(text: string, spec: ConfigSpec, values?: ConfigValues): ConfigEditPlan {
  if (!text || text.length > 400) return { kind: "model", reason: "empty or long request" };
  if (/\b(add|new|remove|delete|instead|also|another|when|if|whenever|make it (shoot|fire|summon|spawn)|texture|model|recipe|craft|rename|command)\b/i.test(text)) return { kind: "model", reason: "structural change" };
  const clauses = text.split(/\s*(?:\band\b|,|;)\s*/i).map((c) => c.trim()).filter(Boolean);
  if (!clauses.length || clauses.length > 8) return { kind: "model", reason: "no clauses" };
  const groups = new Map(spec.groups.map((g) => [g.id, g.label]));
  const editable = spec.params.filter((p) => !p.readOnly);
  const hays = new Map(editable.map((p) => [p.key, haystack(p, groups.get(p.group) ?? "")]));
  const byKey = paramByKey(spec);
  const edits: { key: string; value: ConfigValue }[] = [];
  const summary: string[] = [];
  let lastScope: string[] = [];
  for (const raw of clauses) {
    const m = /^(?:(?:please )?(?:set|change|make|increase|decrease|lower|raise|reduce|put|adjust|bump)\s+)?(?:the\s+)?(.+?)\s+(?:to|=|at)\s+(.+)$/i.exec(raw.trim());
    if (!m) return { kind: "model", reason: `could not read "${raw}"` };
    const words = norm(m[1].replace(/'s\b/g, "")).split(" ").filter((w) => w && !STOP.has(w));
    if (!words.length) return { kind: "model", reason: `"${raw}" names no setting` };
    let cands = editable.filter((p) => words.every((w) => hays.get(p.key)!.has(w) || hays.get(p.key)!.has(w.replace(/s$/, ""))));
    // a clause without a scope word inherits the previous clause's scope ("frost zombie health to 40 and damage to 6")
    if (cands.length > 1 && lastScope.length) { const scoped = cands.filter((p) => lastScope.some((s) => p.key.startsWith(s))); if (scoped.length) cands = scoped; }
    if (cands.length > 1) { const exact = cands.filter((p) => norm(p.label) === words.join(" ")); if (exact.length === 1) cands = exact; }
    if (cands.length !== 1) return { kind: "model", reason: cands.length ? `"${raw}" matches ${cands.length} settings` : `"${raw}" matches no setting`, candidates: cands.map((p) => p.key).slice(0, 8) };
    const p = cands[0];
    lastScope = [p.key.split(".").slice(0, -1).join(".")].filter(Boolean);
    const v = parseValue(p, m[2]);
    if (!v.ok) return { kind: "model", reason: v.reason };
    const c = checkValue(p, v.value, "strict");
    if (!c.ok) return { kind: "model", reason: c.error.message };
    edits.push({ key: p.key, value: c.value });
    summary.push(`${p.label}: ${fmt(p, values?.[p.key] ?? byKey.get(p.key)!.default)} -> ${fmt(p, c.value)}`);
  }
  return { kind: "values", edits, summary };
}
// Cyrus Config Studio: the PER-GAME EXPORTER contract. ConfigSpec is game-neutral; an exporter says where a game keeps
// a mod's settings, which file format it writes, how a change takes effect there and how far that is verified. The
// Minecraft Paper exporter writes YAML at plugins/<plugin>/<file> through the comment-preserving writer and, for mods
// Cyrus generates, emits a typed Java settings class that reads and CLAMPS every declared key (so "every key is read"
// holds by construction). Other games are listed as planned. Pure.
import type { Applies, ConfigParam, ConfigSpec, ConfigValues } from "./spec";
import { defaultsOf } from "./values";
import { readValues, renderConfigYml, writeValues, type ReadResult } from "./file";

export type ExporterMaturity = "verified" | "preview" | "planned";
export type RenderResult = { ok: true; path: string; text: string; written: string[] } | { ok: false; errors: string[] };
export interface ConfigExporter {
  id: string;
  game: string;
  formats: ConfigSpec["format"][];
  /** How changes can take effect in this game (in the order the exporter supports them). */
  applies: Applies[];
  maturity: ExporterMaturity;
  /** Versions where a real server proved write + reload (Test Flight). */
  reloadVerified: string[];
  /** The file's path relative to the server root. */
  path(spec: ConfigSpec, ctx: { pluginName: string }): string;
  /** Write values: into the existing text when there is one (only changed keys touched), else a fresh file. */
  render(spec: ConfigSpec, values: ConfigValues, ctx: { pluginName: string; previousText?: string | null; header?: string[] }): RenderResult;
  read(spec: ConfigSpec, text: string): ReadResult;
}

const PLUGIN_RE = /^[A-Za-z][A-Za-z0-9_]{1,39}$/;

export const paperExporter: ConfigExporter = {
  id: "minecraft-paper-yaml", game: "minecraft", formats: ["yaml"], applies: ["reload", "restart", "live"], maturity: "verified",
  reloadVerified: ["1.21.11", "26.2"],
  path(spec, ctx) {
    if (!PLUGIN_RE.test(ctx.pluginName)) throw new Error("bad plugin name");
    return `plugins/${ctx.pluginName}/${spec.file}`;
  },
  render(spec, values, ctx) {
    if (spec.format !== "yaml") return { ok: false, errors: [`the Paper exporter writes YAML, not ${spec.format}`] };
    if (!PLUGIN_RE.test(ctx.pluginName)) return { ok: false, errors: ["bad plugin name"] };
    const path = `plugins/${ctx.pluginName}/${spec.file}`;
    if (ctx.previousText) {
      const w = writeValues(spec, ctx.previousText, values);
      return w.ok ? { ok: true, path, text: w.text, written: w.written } : { ok: false, errors: w.errors.map((e) => e.message) };
    }
    return { ok: true, path, text: renderConfigYml(spec, { ...defaultsOf(spec), ...values }, ctx.header ?? [`${ctx.pluginName} configuration (generated by Cyrus). Change values here or in the Cyrus Config Studio.`]), written: spec.params.map((p) => p.key) };
  },
  read: (spec, text) => readValues(spec, text),
};

const planned = (id: string, game: string, format: ConfigSpec["format"], where: string): ConfigExporter => ({
  id, game, formats: [format], applies: ["restart"], maturity: "planned", reloadVerified: [],
  path: () => where,
  render: () => ({ ok: false, errors: [`${game} config export is planned, not built`] }),
  read: (spec) => ({ values: defaultsOf(spec), missing: spec.params.map((p) => p.key), clamped: [], errors: [], issues: [`${game} config read is planned`] }),
});
export const EXPORTERS: readonly ConfigExporter[] = [
  paperExporter,
  planned("fivem-lua", "fivem", "properties", "resources/<resource>/config.lua"),
  planned("hytale-json", "hytale", "json", "mods/<mod>/config.json"),
];
export const exporterFor = (game: string) => EXPORTERS.find((e) => e.game === game && e.maturity !== "planned") ?? EXPORTERS.find((e) => e.game === game) ?? null;

// --------------------------------------------------------------------------------------------- Java settings class

const jstr = (s: string) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n")}"`;
const jnum = (v: number) => (Number.isInteger(v) ? `${v}.0` : String(v));
export function javaField(key: string): string {
  const f = key.replace(/([a-z0-9])([A-Z])/g, "$1_$2").replace(/[^A-Za-z0-9]+/g, "_").replace(/^_+|_+$/g, "").toUpperCase();
  return /^[0-9]/.test(f) ? `K_${f}` : f || "K";
}
type JType = { decl: string; init: string; load: string };
function jtype(p: ConfigParam): JType | null {
  const k = jstr(p.key);
  const lo = p.min ?? -Number.MAX_VALUE, hi = p.max ?? Number.MAX_VALUE;
  const dlo = p.min === undefined ? "-Double.MAX_VALUE" : jnum(lo), dhi = p.max === undefined ? "Double.MAX_VALUE" : jnum(hi);
  switch (p.type) {
    case "number": return { decl: "double", init: jnum(p.default as number), load: `num(c, ${k}, ${jnum(p.default as number)}, ${dlo}, ${dhi}, notes)` };
    case "int": return { decl: "int", init: String(p.default), load: `(int) Math.round(num(c, ${k}, ${jnum(p.default as number)}, ${p.min === undefined ? "Integer.MIN_VALUE" : jnum(lo)}, ${p.max === undefined ? "Integer.MAX_VALUE" : jnum(hi)}, notes))` };
    case "duration": return p.durationUnit === "s"
      ? { decl: "double", init: jnum(p.default as number), load: `num(c, ${k}, ${jnum(p.default as number)}, ${dlo}, ${dhi}, notes)` }

      ? { decl: "double", init: jnum(p.default as number), load: `num(c, ${k}, ${jnum(p.default as number)}, ${dlo}, ${dhi}, notes)` }
      : { decl: "long", init: `${p.default}L`, load: `Math.round(num(c, ${k}, ${jnum(p.default as number)}, ${dlo}, ${dhi}, notes))` };
    case "bool": return { decl: "boolean", init: String(p.default), load: `bool(c, ${k}, ${p.default}, notes)` };
    case "range": { const [a, b] = p.default as number[]; return { decl: "double[]", init: `{ ${jnum(a)}, ${jnum(b)} }`, load: `range(c, ${k}, ${jnum(a)}, ${jnum(b)}, ${dlo}, ${dhi}, notes)` }; }
    case "enum": return { decl: "String", init: jstr(String(p.default)), load: `oneOf(c, ${k}, ${jstr(String(p.default))}, new String[] { ${(p.options ?? []).map((o) => jstr(String(o.value))).join(", ")} }, notes)` };
    case "text": case "asset-ref": return { decl: "String", init: jstr(String(p.default)), load: `text(c, ${k}, ${jstr(String(p.default))}, ${p.maxLength ?? 256}, null, notes)` };
    case "color": return { decl: "String", init: jstr(String(p.default)), load: `text(c, ${k}, ${jstr(String(p.default))}, 7, "^#[0-9a-fA-F]{6}$", notes)` };
    case "sound-ref": return { decl: "String", init: jstr(String(p.default)), load: `text(c, ${k}, ${jstr(String(p.default))}, 200, "^([a-z0-9_.-]+:[a-z0-9_./-]+)?$", notes)` };
    case "list": return { decl: "java.util.List<?>", init: "java.util.List.of()", load: `list(c, ${k}, ${p.maxItems ?? 256}, notes)` };
    case "table": return { decl: "java.util.List<java.util.Map<?, ?>>", init: "java.util.List.of()", load: `table(c, ${k}, ${p.maxRows ?? 256}, notes)` };
  }
}

/**
 * A typed settings class for a Paper plugin: one public static field per declared key (defaults inline), `load(c)`
 * reads every key from the plugin's config, clamps numbers to the hard limits, refuses bad enums / colours / sound keys
 * (keeps the previous value) and returns notes ("clamped mobs.x.health 5000.0 -> 1024.0"). Java 21, Bukkit API only.
 */
export function javaSettingsClass(spec: ConfigSpec, o: { pkg: string; className?: string }): { path: string; source: string; fields: Record<string, string> } {
  if (!/^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*$/.test(o.pkg)) throw new Error("bad package");
  const cls = o.className ?? "CyrusSettings";
  if (!/^[A-Z][A-Za-z0-9_]{0,63}$/.test(cls)) throw new Error("bad class name");
  const fields: Record<string, string> = {};
  const used = new Set<string>();
  for (const p of spec.params) { let f = javaField(p.key); while (used.has(f)) f += "_"; used.add(f); fields[p.key] = f; }
  const lines: string[] = [];
  lines.push(`package ${o.pkg};`, ``, `import java.util.ArrayList;`, `import java.util.List;`, `import org.bukkit.configuration.ConfigurationSection;`, ``);
  lines.push(`/** Generated by Cyrus from the ConfigSpec (do not edit): every setting of config.yml, read and clamped on load. */`);
  lines.push(`public final class ${cls} {`, `    private ${cls}() {}`, ``);
  for (const p of spec.params) { const t = jtype(p)!; lines.push(`    /** ${p.label.replace(/[\\*/]/g, "")} (${p.key}) */`, `    public static ${t.decl} ${fields[p.key]} = ${t.decl === "double[]" ? `new double[] ${t.init}` : t.init};`); }
  lines.push(``, `    /** Read every setting. Returns notes about clamped or refused values (empty when all were fine). */`, `    public static List<String> load(ConfigurationSection c) {`, `        List<String> notes = new ArrayList<>();`);
  for (const p of spec.params) lines.push(`        ${fields[p.key]} = ${jtype(p)!.load};`);
  lines.push(`        return notes;`, `    }`, ``);
  lines.push(
    `    private static double num(ConfigurationSection c, String k, double d, double lo, double hi, List<String> notes) {`,
    `        Object raw = c.get(k);`,
    `        if (raw == null) return d;`,
    `        double v;`,
    `        if (raw instanceof Number n) v = n.doubleValue();`,
    `        else { try { v = Double.parseDouble(String.valueOf(raw).trim()); } catch (NumberFormatException e) { notes.add(k + " is not a number; using " + d); return d; } }`,
    `        if (Double.isNaN(v) || Double.isInfinite(v)) { notes.add(k + " is not a finite number; using " + d); return d; }`,
    `        double r = Math.max(lo, Math.min(hi, v));`,
    `        if (r != v) notes.add("clamped " + k + " " + v + " -> " + r);`,
    `        return r;`,
    `    }`,
    `    private static boolean bool(ConfigurationSection c, String k, boolean d, List<String> notes) {`,
    `        Object raw = c.get(k);`,
    `        if (raw == null) return d;`,
    `        if (raw instanceof Boolean b) return b;`,
    `        String s = String.valueOf(raw).trim().toLowerCase(java.util.Locale.ROOT);`,
    `        if (s.equals("true") || s.equals("yes") || s.equals("on")) return true;`,
    `        if (s.equals("false") || s.equals("no") || s.equals("off")) return false;`,
    `        notes.add(k + " is not true or false; using " + d);`,
    `        return d;`,
    `    }`,
    `    private static String text(ConfigurationSection c, String k, String d, int max, String pattern, List<String> notes) {`,
    `        Object raw = c.get(k);`,
    `        if (raw == null) return d;`,
    `        String s = String.valueOf(raw);`,
    `        if (s.length() > max) { notes.add(k + " is longer than " + max + " characters; cut"); s = s.substring(0, max); }`,
    `        if (pattern != null && !s.matches(pattern)) { notes.add(k + " has a bad value; using " + d); return d; }`,
    `        return s;`,
    `    }`,
    `    private static String oneOf(ConfigurationSection c, String k, String d, String[] options, List<String> notes) {`,
    `        Object raw = c.get(k);`,
    `        if (raw == null) return d;`,
    `        String s = String.valueOf(raw);`,
    `        for (String o : options) if (o.equalsIgnoreCase(s)) return o;`,
    `        notes.add(k + " must be one of " + String.join(", ", options) + "; using " + d);`,
    `        return d;`,
    `    }`,
    `    private static double[] range(ConfigurationSection c, String k, double a, double b, double lo, double hi, List<String> notes) {`,
    `        List<?> l = c.getList(k);`,
    `        if (l == null || l.size() != 2 || !(l.get(0) instanceof Number) || !(l.get(1) instanceof Number)) { if (c.get(k) != null) notes.add(k + " needs [low, high]; using defaults"); return new double[] { a, b }; }`,
    `        double x = Math.max(lo, Math.min(hi, ((Number) l.get(0)).doubleValue())), y = Math.max(lo, Math.min(hi, ((Number) l.get(1)).doubleValue()));`,
    `        if (x > y) { notes.add(k + " low end is above the high end; using defaults"); return new double[] { a, b }; }`,
    `        return new double[] { x, y };`,
    `    }`,
    `    private static List<?> list(ConfigurationSection c, String k, int max, List<String> notes) {`,
    `        List<?> l = c.getList(k);`,
    `        if (l == null) return List.of();`,
    `        if (l.size() > max) { notes.add(k + " has more than " + max + " entries; cut"); return new ArrayList<>(l.subList(0, max)); }`,
    `        return new ArrayList<>(l);`,
    `    }`,
    `    private static List<java.util.Map<?, ?>> table(ConfigurationSection c, String k, int max, List<String> notes) {`,
    `        List<java.util.Map<?, ?>> l = c.getMapList(k);`,
    `        if (l.size() > max) { notes.add(k + " has more than " + max + " rows; cut"); return new ArrayList<>(l.subList(0, max)); }`,
    `        return new ArrayList<>(l);`,
    `    }`,
    `}`, ``,
  );
  return { path: `src/main/java/${o.pkg.replace(/\./g, "/")}/${cls}.java`, source: lines.join("\n"), fields };
}

353 components/cyrus/studios/ConfigStudio.tsx
"use client";
// Cyrus Config and Stats Studio: the Config page of the studio shell. A form GENERATED from the mod's ConfigSpec
// (lib/cyrus/config): groups rail, search, presets, per-setting reset, balance warnings, "applies" badges, a review
// drawer (the exact config.yml lines that change, from the server's preview), Save revision (values only: no model, no
// build), undo from history, and the "just type it" box (deterministic, no AI). The preview stage runs on Model
// Studio's PlaybackClock: stats with a `visual` link (walk speed, attack speed, fire rate, reload, size) set the clock
// speed through applyToClock, so the clip plays faster or slower as the number moves. Narrow screens are read only.
// Approved mockups: /root/agent-notes/cyrus-designs/v5-config/config-mob.html + config-gun.html.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { StudioShell, useToast, type StudioMod } from "./StudioShell";
import { SI } from "./icons";
import { applyToClock, visualEffects, type VisualEffects } from "@/lib/cyrus/config/visual";
import { balanceWarnings, checkValue, fmt, fromSeconds, sameValue, toSeconds } from "@/lib/cyrus/config/values";
import type { Applies, ConfigParam, ConfigSpec, ConfigValue, ConfigValues, ScalarValue } from "@/lib/cyrus/config/spec";
import { PlaybackClock } from "@/lib/cyrus/modelstudio/clock";
import "./config-studio.css";

type View = {
  project: { id: string; namespace: string } | null; pluginName: string | null; mcVersion: string; buildId: string;
  source: "declared" | "designer" | "inferred" | "none"; spec: ConfigSpec | null; notes: string[];
  values: ConfigValues; shipped: ConfigValues; defaults: ConfigValues; changedFromDefaults: string[]; preset: string;
  headRevisionId: string | null; history: { revisionId: string; seq: number; createdAt: string; message: string | null; patch: { key: string; from: unknown; to: unknown }[] }[];
  deliveryConnected: boolean;
};
type Preview = { configYml: string; patch: { key: string; from: ConfigValue; to: ConfigValue }[]; applies: Applies | "none"; errors: { key: string; message: string }[]; warnings: { key: string; message: string }[]; lines?: { sign: "-" | "+"; text: string }[] };

const API = "/api/cyrus/config/v1";
async function api<T>(init?: { method: "POST"; body: unknown }, q = ""): Promise<T> {
  const r = await fetch(`${API}${q}`, init ? { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(init.body) } : { cache: "no-store" });
  const j = await r.json().catch(() => ({}));
  if (!r.ok) throw Object.assign(new Error((j as { error?: string }).error ?? "Something went wrong."), { status: r.status, body: j });
  return j as T;
}

const SOURCE_LABEL: Record<View["source"], string> = { declared: "Declared by Cyrus", designer: "From the item designs", inferred: "Read from config.yml", none: "No settings" };
const APPLIES: Record<Applies, { label: string; cls: string; icon: string }> = {
  live: { label: "Live", cls: "ok", icon: "check" }, reload: { label: "Reload", cls: "acc", icon: "restore" }, restart: { label: "Restart", cls: "warn", icon: "server" },
};
const numericT = (p: ConfigParam) => p.type === "number" || p.type === "int" || p.type === "duration";

function useNarrow() {
  const [n, setN] = useState(false);
  useEffect(() => { const m = window.matchMedia("(max-width: 760px)"); const f = () => setN(m.matches); f(); m.addEventListener("change", f); return () => m.removeEventListener("change", f); }, []);
  return n;
}

export function ConfigStudio({ mod, showModel = false }: { mod: StudioMod; showModel?: boolean }) {
  return (
    <StudioShell mod={mod} current="Config" studio="config" showModel={showModel} showConfig>
      <ConfigBody mod={mod} />
    </StudioShell>
  );
}

function ConfigBody({ mod }: { mod: StudioMod }) {
  const toast = useToast();
  const narrow = useNarrow();
  const [view, setView] = useState<View | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [vals, setVals] = useState<ConfigValues>({});

  const [vals, setVals] = useState<ConfigValues>({});
  const [group, setGroup] = useState<string | null>(null);
  const [q, setQ] = useState("");
  const [review, setReview] = useState<Preview | null>(null);
  const [busy, setBusy] = useState(false);
  const [cmd, setCmd] = useState("");
  const [showHistory, setShowHistory] = useState(false);
  const load = useCallback(async () => {
    try { const v = await api<View>(undefined, `?root=${encodeURIComponent(mod.rootId)}`); setView(v); setVals(v.values); setErr(null); }
    catch (e) { setErr((e as Error).message); }
  }, [mod.rootId]);
  useEffect(() => { void load(); }, [load]);
  const spec = view?.spec ?? null;
  const readOnly = narrow;
  const changedKeys = useMemo(() => (spec && view ? spec.params.filter((p) => !sameValue(vals[p.key], view.values[p.key])).map((p) => p.key) : []), [spec, view, vals]);
  const fx = useMemo(() => (spec ? visualEffects(spec, vals) : null), [spec, vals]);
  const set = (k: string, v: ConfigValue) => setVals((o) => ({ ...o, [k]: v }));
  const presetOn = useMemo(() => { if (!spec) return "default"; for (const pr of spec.presets) if (Object.entries(pr.values).every(([k, v]) => sameValue(vals[k], v))) return pr.id; return spec.params.every((p) => sameValue(vals[p.key], view?.defaults[p.key])) ? "default" : "custom"; }, [spec, vals, view]);

  if (err) return <div className="cys-empty" style={{ margin: "auto" }}><SI n="warn" /><p>{err}</p></div>;
  if (!view) return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Loading this mod&apos;s settings…</div>;
  if (!spec) return (
    <main className="cfg-ws one"><section className="cys-panel cys-glass" style={{ flex: 1, display: "grid", placeItems: "center" }}>
      <div className="cys-empty" style={{ maxWidth: 460 }}><SI n="gauge" /><p><b>This mod has no settings Cyrus can edit yet.</b></p><p className="cys-hint">{view.notes[0] ?? "Ask Cyrus to make its numbers configurable in your next change."}</p></div>
    </section></main>
  );

  const groups = [...spec.groups].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
  const ql = q.trim().toLowerCase();
  const shown = spec.params.filter((p) => (!ql || `${p.label} ${p.key} ${p.help ?? ""} ${p.tags.join(" ")}`.toLowerCase().includes(ql)) && (!group || ql || p.group === group));

  const openReview = async () => {
    setBusy(true);
    try { setReview(await api<Preview>({ method: "POST", body: { root: mod.rootId, action: "preview", values: Object.fromEntries(changedKeys.map((k) => [k, vals[k]])) } })); }
    catch (e) { toast((e as Error).message, true); } finally { setBusy(false); }
  };
  const save = async () => {
    setBusy(true);
    try {
      const r = await api<{ seq: number; applies: string }>({ method: "POST", body: { root: mod.rootId, action: "save", values: Object.fromEntries(changedKeys.map((k) => [k, vals[k]])), expectedHeadId: view.headRevisionId } });
      toast(`Saved as revision ${r.seq}. ${r.applies === "reload" && spec.reload ? `Takes effect with ${spec.reload.command}.` : r.applies === "restart" ? "Takes effect after a server restart." : ""}`);
      setReview(null); await load();
    } catch (e) { toast((e as Error).message, true); } finally { setBusy(false); }
  };
  const undo = async (revisionId: string) => {
    setBusy(true);
    try { const r = await api<{ seq: number }>({ method: "POST", body: { root: mod.rootId, action: "revert", revisionId, expectedHeadId: view.headRevisionId } }); toast(`Undone as revision ${r.seq}.`); await load(); }
    catch (e) { toast((e as Error).message, true); } finally { setBusy(false); }
  };
  const runCmd = async () => {
    if (!cmd.trim()) return;
    try {
      const r = await api<{ kind: "values"; edits: { key: string; value: ConfigValue }[]; summary: string[] } | { kind: "model"; reason: string }>({ method: "POST", body: { root: mod.rootId, action: "plan", text: cmd } });
      if (r.kind === "values") { setVals((o) => ({ ...o, ...Object.fromEntries(r.edits.map((e) => [e.key, e.value])) })); toast(r.summary.join("; ")); setCmd(""); }
      else toast(`Cyrus can't do that without the AI: ${r.reason}. Change it in the form or ask in a normal change.`, true);
    } catch (e) { toast((e as Error).message, true); }
  };

  return (
    <>
      {readOnly && <div className="cfg-ro"><SI n="phone" />Read only on a phone: open this page on a bigger screen to change settings.</div>}
      <main className="cfg-ws">
        <nav className="cfg-rail cys-panel cys-glass" aria-label="Setting groups">
          <button className={`cfg-g ${!group ? "on" : ""}`} onClick={() => setGroup(null)}>All settings<span className="n">{spec.params.length}</span></button>
          {groups.map((g) => (
            <button key={g.id} className={`cfg-g ${group === g.id ? "on" : ""}`} onClick={() => setGroup(g.id)}>
              {g.label}{spec.params.some((p) => p.group === g.id && changedKeys.includes(p.key)) && <span className="ch" aria-label="changed" />}
              <span className="n">{spec.params.filter((p) => p.group === g.id).length}</span>
            </button>
          ))}
          <div className="cfg-legend">
            <span className="cys-eyebrow">How changes apply</span>
            {spec.reload && <><Badge a="reload" />  <span>{spec.reload.command}, no restart</span></>}
            <Badge a="restart" /><span>Needs a server restart</span>
          </div>
        </nav>
        <section className="cfg-form cys-panel cys-glass cys-hairline">
          <div className="cfg-fh">
            <h1>Config and stats</h1>
            <span className={`cys-tag ${view.source === "inferred" ? "dim" : "ok"}`}><SI n={view.source === "inferred" ? "info" : "check"} />{SOURCE_LABEL[view.source]}</span>
            <span className="sp" />
            <label className="cfg-search"><SI n="search" /><input className="cys-field" placeholder="Search settings" value={q} onChange={(e) => setQ(e.target.value)} aria-label="Search settings" /></label>
          </div>
          <div className="cfg-bar">
            {spec.presets.length > 0 && !readOnly && <><span className="cys-eyebrow">Preset</span>
              <div className="cys-seg sm cys-soft" role="group" aria-label="Presets">
                {spec.presets.map((pr) => <button key={pr.id} className={presetOn === pr.id ? "on" : ""} disabled={readOnly} onClick={() => setVals((o) => ({ ...o, ...pr.values }))}>{pr.label}</button>)}
                <button className={presetOn === "custom" ? "on" : ""} disabled>Custom</button>
              </div></>}
            <span className="sp" />
            {changedKeys.length > 0 && <span className="cys-tag acc">{changedKeys.length} unsaved</span>}
            {view.history.length > 0 && <button className="cys-btn sm ghost" onClick={() => setShowHistory((x) => !x)}><SI n="history" />History</button>}
            {!readOnly && <button className="cys-btn sm ghost" disabled={!changedKeys.length} onClick={() => setVals(view.values)}><SI n="undo" />Discard</button>}
            {!readOnly && <button className="cys-btn sm" disabled={busy || !changedKeys.length} onClick={openReview}><SI n="split" />Review changes</button>}
          </div>
          {view.source === "inferred" && <p className="cfg-note"><SI n="info" />Cyrus read these settings from the mod&apos;s config.yml. Types come from the file; limits only where its comments state them.</p>}
          <div className="cfg-rows">
            {groups.map((g) => {
              const rs = shown.filter((p) => p.group === g.id);
              if (!rs.length) return null;
              return (
                <div key={g.id}>
                  <div className="cfg-gh"><h2>{g.label}</h2>{g.help && <span>{g.help}</span>}</div>
                  {rs.map((p) => <Row key={p.key} p={p} v={vals[p.key]} saved={view.values[p.key]} def={view.defaults[p.key]} readOnly={readOnly || !!p.readOnly} onChange={(v) => set(p.key, v)} />)}
                </div>
              );
            })}
            {!shown.length && <p className="cys-hint" style={{ padding: 20 }}>No setting matches “{q}”.</p>}
          </div>
          {!readOnly && (
            <div className="cfg-cmd">
              <span className="ic"><SI n="sparkle" /></span>
              <input className="cys-field" value={cmd} onChange={(e) => setCmd(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") void runCmd(); }} placeholder={`Or type it: "set ${spec.params.find(numericT)?.label.toLowerCase() ?? "a setting"} to …"`} aria-label="Type a change" />
              <button className="cys-btn sm" onClick={runCmd}>Apply</button><span className="cys-hint">no AI, no tokens</span>
            </div>
          )}
          {review && (
            <div className="cfg-drawer cys-glass cys-hairline" role="dialog" aria-label="Review changes">
              <div className="dh"><SI n="split" /><h3>Review {review.patch.length} change{review.patch.length === 1 ? "" : "s"}</h3>
                {review.applies !== "none" && <Badge a={review.applies as Applies} />}
                <span className="cys-hint">{review.applies === "reload" && spec.reload ? `${spec.reload.command}: no restart, no rebuild, no tokens` : review.applies === "restart" ? "Needs a server restart; no rebuild, no tokens" : "No rebuild, no tokens"}</span>
                <span className="sp" /><button className="cys-ib" onClick={() => setReview(null)} aria-label="Close"><SI n="close" /></button></div>
              <div className="db">
                <div className="changes"><span className="cys-eyebrow">Settings</span>
                  {review.patch.map((op) => { const p = spec.params.find((x) => x.key === op.key)!; return <div key={op.key} className="ci"><span>{p.label}</span><span className="from">{fmt(p, op.from)}</span><SI n="chevR" /><span className="to">{fmt(p, op.to)}</span></div>; })}
                  {review.errors.map((e) => <div key={e.key} className="cfg-warn bad"><SI n="warn" />{e.message}</div>)}
                  {review.warnings.length > 0 && <div className="cfg-warn"><SI n="warn" />{review.warnings.length} value{review.warnings.length === 1 ? " is" : "s are"} outside the balanced range. You can still save.</div>}
                </div>
                <pre aria-label="config.yml changes"><span className="cm"># config.yml: only these lines change. Comments and other keys stay.</span>{"\n"}{(review.lines ?? []).map((l, i) => <span key={i} className={l.sign === "+" ? "add" : "del"}>{`${l.sign} ${l.text}`}{"\n"}</span>)}</pre>
              </div>
              <div className="df"><span className="cys-hint">A new revision; undo any time from History.</span><span className="sp" />
                <button className="cys-btn sm ghost" onClick={() => setReview(null)}>Keep editing</button>
                <button className="cys-btn sm" disabled title={view.deliveryConnected ? "" : "Sending settings to a server is not connected yet"}><SI n="server" />Save and send to a server</button>
                <button className="cys-btn sm primary" disabled={busy || review.errors.length > 0} onClick={save}><SI n="check" />Save revision</button></div>
            </div>
          )}
          {showHistory && (
            <div className="cfg-drawer cys-glass" role="dialog" aria-label="History">
              <div className="dh"><SI n="history" /><h3>Settings history</h3><span className="sp" /><button className="cys-ib" onClick={() => setShowHistory(false)} aria-label="Close"><SI n="close" /></button></div>
              <div className="hist">{view.history.map((h) => (
                <div key={h.revisionId} className="hi"><span className="cys-tag dim">rev {h.seq}</span><span className="m">{h.message ?? "Settings change"}</span><span className="cys-hint">{new Date(h.createdAt).toLocaleString()}</span>
                  {!readOnly && <button className="cys-btn xs" disabled={busy} onClick={() => undo(h.revisionId)}><SI n="undo" />Undo</button>}</div>
              ))}</div>
            </div>
          )}
        </section>
        <PreviewPanel spec={spec} fx={fx} />
      </main>
    </>
  );
}

function Badge({ a }: { a: Applies }) {
  const x = APPLIES[a];
  return <span className={`cys-tag ${x.cls}`} title={a === "restart" ? "Takes effect after a server restart" : a === "reload" ? "Takes effect with the mod's reload command" : "Takes effect at once"}><SI n={x.icon} />{x.label}</span>;
}

function Row({ p, v, saved, def, readOnly, onChange }: { p: ConfigParam; v: ConfigValue; saved: ConfigValue; def: ConfigValue; readOnly: boolean; onChange: (v: ConfigValue) => void }) {
  const dirty = !sameValue(v, saved);
  const warns = balanceWarnings(p, v);
  const [bad, setBad] = useState<string | null>(null);
  return (
    <div className={`cfg-row ${dirty ? "changed" : ""}`} data-key={p.key}>
      <div className="lb">
        <b>{p.label}{p.visual && <span className="cys-tag dim" title="Plays in the preview"><SI n="eye" />preview</span>}</b>
        {p.help && <small>{p.help}</small>}
        <span className="k mono">{p.key}</span>
      </div>
      <Control p={p} v={v} readOnly={readOnly} onChange={onChange} onBad={setBad} />
      <div className="right"><Badge a={p.applies} /><button className="cys-ib sm" title={`Reset to ${fmt(p, def)}`} aria-label={`Reset ${p.label}`} disabled={readOnly || sameValue(v, def)} onClick={() => onChange(def)}><SI n="restore" /></button></div>
      {bad && <div className="cfg-warn bad"><SI n="warn" />{bad}</div>}
      {!bad && warns.map((w) => <div key={w.code} className="cfg-warn"><SI n="warn" />{w.message}. It still saves.</div>)}
    </div>
  );
}

function Control({ p, v, readOnly, onChange, onBad }: { p: ConfigParam; v: ConfigValue; readOnly: boolean; onChange: (v: ConfigValue) => void; onBad: (m: string | null) => void }) {
  const [text, setText] = useState<string | null>(null);
  if (p.type === "bool") return <div className="ctl"><button role="switch" aria-checked={!!v} aria-label={p.label} className={`cfg-tog ${v ? "on" : ""}`} disabled={readOnly} onClick={() => onChange(!v)} /><span className="cys-hint">{v ? "On" : "Off"}</span></div>;
  if (p.type === "enum") {
    const opts = p.options ?? [];
    return opts.length <= 4
      ? <div className="ctl"><div className="cys-seg sm cys-soft" role="radiogroup" aria-label={p.label}>{opts.map((o) => <button key={String(o.value)} role="radio" aria-checked={o.value === v} className={o.value === v ? "on" : ""} disabled={readOnly} onClick={() => onChange(o.value)}>{o.label ?? String(o.value)}</button>)}</div></div>
      : <div className="ctl"><select className="cys-field" value={String(v)} disabled={readOnly} aria-label={p.label} onChange={(e) => onChange(opts.find((o) => String(o.value) === e.target.value)!.value)}>{opts.map((o) => <option key={String(o.value)} value={String(o.value)}>{o.label ?? String(o.value)}</option>)}</select></div>;
  }
  if (p.type === "color") return <div className="ctl"><input type="color" className="cfg-color" value={String(v)} disabled={readOnly} aria-label={p.label} onChange={(e) => onChange(e.target.value)} /><input className="cys-field mono" style={{ width: 110 }} value={String(v)} readOnly={readOnly} aria-label={`${p.label} hex`} onChange={(e) => onChange(e.target.value)} /></div>;
  if (p.type === "text" || p.type === "sound-ref" || p.type === "asset-ref") return <div className="ctl"><input className={`cys-field ${p.type !== "text" ? "mono" : ""}`} value={String(v)} readOnly={readOnly} maxLength={p.maxLength ?? 256} aria-label={p.label} onChange={(e) => { const c = checkValue(p, e.target.value); onBad(c.ok ? null : c.error.message); onChange(e.target.value); }} /></div>;
  if (p.type === "list") {
    const arr = (v as ScalarValue[]) ?? [];
    return <div className="ctl"><div className="cys-chiprow">{arr.map((x, i) => <span key={i} className="cys-fchip">{String(x)}{!readOnly && <button aria-label={`Remove ${x}`} onClick={() => onChange(arr.filter((_, j) => j !== i))}><SI n="close" /></button>}</span>)}
      {!readOnly && <input className="cys-field cfg-add" placeholder="Add…" aria-label={`Add to ${p.label}`} onKeyDown={(e) => { if (e.key === "Enter" && e.currentTarget.value.trim()) { const raw = e.currentTarget.value.trim(); const val = p.item?.type === "number" || p.item?.type === "int" ? Number(raw) : raw; onChange([...arr, val]); e.currentTarget.value = ""; } }} />}</div></div>;
  }
  if (p.type === "table") {
    const rows = (v as Record<string, ScalarValue>[]) ?? [];
    const cols = p.columns ?? [];
    return <div className="ctl"><table className="cfg-tbl"><thead><tr>{cols.map((c) => <th key={c.key}>{c.label}</th>)}<th /></tr></thead><tbody>
      {rows.map((r, i) => <tr key={i}>{cols.map((c) => <td key={c.key}><input className={`cys-field ${c.type !== "text" ? "mono" : ""}`} value={String(r[c.key] ?? "")} readOnly={readOnly} aria-label={`${c.label} row ${i + 1}`} onChange={(e) => { const x = c.type === "number" || c.type === "int" ? (e.target.value === "" ? "" : Number(e.target.value)) : e.target.value; onChange(rows.map((rr, j) => (j === i ? { ...rr, [c.key]: x as ScalarValue } : rr))); }} /></td>)}
        <td>{!readOnly && <button className="cys-ib sm" aria-label={`Remove row ${i + 1}`} onClick={() => onChange(rows.filter((_, j) => j !== i))}><SI n="close" /></button>}</td></tr>)}
      {!readOnly && <tr><td colSpan={cols.length + 1}><button className="cys-btn xs" onClick={() => onChange([...rows, Object.fromEntries(cols.map((c) => [c.key, c.default ?? (c.type === "text" ? "" : c.type === "bool" ? false : c.min ?? 0)])) as Record<string, ScalarValue>])}><SI n="plus" />Add a row</button></td></tr>}
    </tbody></table></div>;
  }
  if (p.type === "range") {
    const [a, b] = v as number[];
    return <div className="ctl"><label className="cfg-num"><input value={a} readOnly={readOnly} aria-label={`${p.label} low`} onChange={(e) => onChange([Number(e.target.value), b])} /></label><span className="cys-hint">to</span><label className="cfg-num"><input value={b} readOnly={readOnly} aria-label={`${p.label} high`} onChange={(e) => onChange([a, Number(e.target.value)])} /><span>{p.unit ?? ""}</span></label></div>;
  }
  // number / int / duration: a slider over the hard limits with the balanced band, plus a typed field with the unit
  const dur = p.type === "duration";
  const shownV = dur ? toSeconds(p, v as number) : (v as number);
  const lo = p.min !== undefined ? (dur ? toSeconds(p, p.min) : p.min) : undefined;
  const hi = p.max !== undefined ? (dur ? toSeconds(p, p.max) : p.max) : undefined;
  const step = dur ? (p.durationUnit === "ticks" ? 0.05 : 0.1) : p.step ?? (p.type === "int" ? 1 : 0.01);
  const pct = (x: number) => (lo !== undefined && hi !== undefined && hi > lo ? ((x - lo) / (hi - lo)) * 100 : 0);
  const sMin = p.safe?.min !== undefined ? (dur ? toSeconds(p, p.safe.min) : p.safe.min) : lo;
  const sMax = p.safe?.max !== undefined ? (dur ? toSeconds(p, p.safe.max) : p.safe.max) : hi;
  const commit = (raw: string) => {
    const n = Number(raw);
    if (raw.trim() === "" || !Number.isFinite(n)) { onBad(`${p.label} needs a number`); return; }
    const stored = dur ? fromSeconds(p, n) : n;
    const c = checkValue(p, stored);
    if (!c.ok) { onBad(c.error.message); return; }
    onBad(null); onChange(c.value); setText(null);
  };
  return (
    <div className="ctl">
      {lo !== undefined && hi !== undefined && (
        <div className="cfg-track">
          {p.safe && sMin !== undefined && sMax !== undefined && <span className="safe" style={{ left: `${pct(sMin)}%`, width: `${pct(sMax) - pct(sMin)}%` }} />}
          <input type="range" min={lo} max={hi} step={step} value={shownV} disabled={readOnly} aria-label={p.label} onChange={(e) => commit(e.target.value)} />
        </div>
      )}
      <label className="cfg-num"><input inputMode="decimal" value={text ?? String(Math.round(shownV * 1e4) / 1e4)} readOnly={readOnly} aria-label={`${p.label} value`} onChange={(e) => setText(e.target.value)} onBlur={(e) => commit(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") commit((e.target as HTMLInputElement).value); }} /><span>{dur ? "s" : p.unit ?? ""}</span></label>
    </div>
  );
}

/** The preview stage: a stand-in creature or weapon whose clip phase comes from a PlaybackClock driven by the stats. */
function PreviewPanel({ spec, fx }: { spec: ConfigSpec; fx: VisualEffects | null }) {
  const kind = spec.params.some((p) => p.visual?.channel === "fireRate") ? "gun" : spec.params.some((p) => p.visual?.channel === "clipRate" && p.visual.clip === "walk") ? "mob" : spec.params.some((p) => p.visual?.channel === "attackRate") ? "melee" : null;
  const clips = kind === "gun" ? ["fire", "reload"] : kind === "melee" ? ["swing"] : ["walk", "attack"];
  const [clip, setClip] = useState(clips[0]);
  const [playing, setPlaying] = useState(true);
  const clock = useRef<PlaybackClock | null>(null);
  const [t, setT] = useState(0);
  useEffect(() => { clock.current = new PlaybackClock({ end: 1, loop: true }); clock.current.play(); return () => { clock.current = null; }; }, []);
  useEffect(() => { if (clock.current && fx) applyToClock(clock.current, fx, clip); }, [fx, clip]);
  useEffect(() => { const c = clock.current; if (!c) return; if (playing) c.play(); else c.pause(); }, [playing]);
  useEffect(() => {
    let raf = 0, last = performance.now();
    const loop = (now: number) => { const c = clock.current; if (c) { c.tick(Math.min(0.1, (now - last) / 1000)); setT(c.time); } last = now; raf = requestAnimationFrame(loop); };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);
  if (!kind || !fx) return (
    <aside className="cfg-pv cys-panel cys-glass"><div className="cys-ph"><span className="cys-eyebrow">Preview</span></div>
      <div className="cys-empty" style={{ padding: 24 }}><SI n="eye" /><p className="cys-hint">None of these settings has a visual. Speed, attack speed, size and fire rate stats play here when a mod has them.</p></div></aside>
  );
  const phase = Math.sin(t * Math.PI * 2);
  const rate = fx.clipRates[clip] ?? 1;
  return (
    <aside className="cfg-pv cys-panel cys-glass">
      <div className="cys-ph"><span className="cys-eyebrow">Preview</span>
        <div className="cys-seg sm cys-soft" role="group" aria-label="Clip">{clips.map((c) => <button key={c} className={clip === c ? "on" : ""} onClick={() => setClip(c)}>{c[0].toUpperCase() + c.slice(1)}</button>)}</div></div>
      <div className="cfg-stage">
        <span className="livetag cys-tag"><span className="cys-dot live" />live preview</span>
        <span className="ground" />
        {kind === "gun" ? (
          <div className="gunv" style={{ transform: `translateX(${clip === "fire" ? -Math.max(0, phase) * 6 : 0}px)` }}>
            <span className="stk" /><span className="rcv" /><span className="brl" />
            <span className="mag" style={{ transform: `translateY(${clip === "reload" ? Math.max(0, phase) * 40 : 0}px)`, opacity: clip === "reload" && phase > 0.5 ? 0.3 : 1 }} />
            <span className="flash" style={{ opacity: clip === "fire" && phase > 0.6 ? 1 : 0 }} />
          </div>
        ) : (
          <div className="mob" style={{ transform: `scale(${Math.min(3, fx.scale)})` }}>
            <div className="head" />
            <div className="body">
              <span className="arm l" style={{ transform: `rotate(${clip === "attack" || clip === "swing" ? -70 - phase * 25 : phase * 18}deg)` }} />
              <span className="arm r" style={{ transform: `rotate(${clip === "attack" || clip === "swing" ? -70 + phase * 25 : -phase * 18}deg)` }} />
              <span className="leg l" style={{ transform: `rotate(${clip === "walk" ? phase * 24 : 0}deg)` }} />
              <span className="leg r" style={{ transform: `rotate(${clip === "walk" ? -phase * 24 : 0}deg)` }} />
            </div>
          </div>
        )}
      </div>
      <div className="cfg-readout">
        <span className="cys-eyebrow">What the stats do to the model</span>
        {Object.entries(fx.clipRates).map(([c, r]) => <div key={c} className="r"><SI n="play" />{c[0].toUpperCase() + c.slice(1)} clip<span className="meter"><i style={{ width: `${Math.min(100, r * 50)}%` }} /></span><b className="mono">{r.toFixed(2)}x</b></div>)}
        {fx.fireIntervalS !== null && <div className="r"><SI n="history" />Time between shots<b className="mono">{fx.fireIntervalS.toFixed(3)} s</b></div>}
        {fx.scale !== 1 && <div className="r"><SI n="zoomin" />Size<span className="meter"><i style={{ width: `${Math.min(100, fx.scale * 33)}%` }} /></span><b className="mono">{fx.scale.toFixed(2)}x</b></div>}
        <p className="cys-hint">An approximation for feel, played at {rate.toFixed(2)}x. The server is the truth: Cyrus checks every value against its limits again when it saves.</p>
      </div>
      <div className="cfg-clock"><button className={`cys-ib ${playing ? "on" : ""}`} aria-label={playing ? "Pause" : "Play"} onClick={() => setPlaying((x) => !x)}><SI n={playing ? "pause" : "play"} /></button><span className="cys-hint">Clock speed follows the stats</span></div>
    </aside>
  );
}

// Cyrus Config Studio <-> gameplay designers: ONE param model. The designers (lib/cyrus/designer) already turn every
// number, text and sound of a design into a config.yml parameter (`Param`: path, kind num|ticks|int|text|sound, caps);
// `fromDesignerParams` maps those into ConfigSpec params so the studio edits designer mods with the same form,
// validator and writer as every other mod. The designers' own compile output stays byte-identical (nothing here is
// imported by them). `toDesignerEdits` turns a studio patch back into designer ParamEdits (exact config paths), so the
// designs can be updated with the designers' own `applyParameterEdits` when the mod is rebuilt. Pure.
import type { Param } from "../designer/compile";
import { CONFIG_LIMITS, SOUND_KEY_RE, isConfigKey, validateConfigSpec, type ConfigParamInput, type ConfigSpec, type ConfigSpecInput } from "./spec";
import type { Patch } from "./diff";
import { humanize } from "./infer";

const ROLE_UNIT: Record<string, string> = { damage: "hp", heal: "hp", range: "blocks", radius: "blocks" };

export type FromDesignerResult = { ok: true; spec: ConfigSpec; skipped: string[] } | { ok: false; errors: string[] };

/** Designer params (designParams / modParams output) -> a ConfigSpec. `command` = the plugin's command (/<command> reload). */
export function fromDesignerParams(params: readonly Param[], o: { command: string; groupLabels?: Record<string, string> }): FromDesignerResult {
  const groups = new Map<string, string>();
  const skipped: string[] = [];
  const out: ConfigParamInput[] = [];
  for (const p of params) {
    if (!isConfigKey(p.path)) { skipped.push(p.path); continue; }
    const owner = p.owner ?? "item";
    let gid = `${owner === "item" ? "" : `${owner}_`}${p.item}`.toLowerCase().replace(/[^a-z0-9_-]/g, "_").replace(/^[^a-z]+/, "").slice(0, 32) || "general";
    if (!groups.has(gid) && groups.size >= CONFIG_LIMITS.groups) gid = [...groups.keys()][groups.size - 1];
    if (!groups.has(gid)) groups.set(gid, o.groupLabels?.[p.item] ?? `${owner === "menu" ? "Menu " : owner === "quest" ? "Quest " : ""}${humanize(p.item)}`.slice(0, 60));
    const label = p.label.length <= 60 ? p.label : `${p.label.slice(0, 57)}...`;
    const base = { key: p.path, group: gid, label, ...(p.label.length > 60 ? { help: p.label.slice(0, 200) } : {}), applies: "reload" as const, tags: [p.role].filter((r) => /^[a-z][a-z0-9_-]{0,23}$/.test(r)) };
    switch (p.kind) {
      case "num": out.push({ ...base, type: "number", default: Number(p.value), min: p.min, max: p.max, ...(ROLE_UNIT[p.role] ? { unit: ROLE_UNIT[p.role] } : {}) }); break;
      case "int": out.push({ ...base, type: "int", default: Math.round(Number(p.value)), min: Math.ceil(p.min), max: Math.floor(p.max) }); break;
      case "ticks": out.push({ ...base, type: "duration", durationUnit: "ticks", default: Math.round(Number(p.value)), min: p.min, max: p.max }); break;
      case "text": out.push({ ...base, type: "text", default: String(p.value), maxLength: Math.max(1, Math.min(CONFIG_LIMITS.textChars, p.max)) }); break;
      case "sound": if (SOUND_KEY_RE.test(String(p.value))) out.push({ ...base, type: "sound-ref", default: String(p.value) }); else skipped.push(p.path); break;
    }
  }
  if (!out.length) return { ok: false, errors: ["the designs have no settings"] };
  const input: ConfigSpecInput = {
    schemaVersion: 1, file: "config.yml", format: "yaml", category: "designer", reload: { command: `/${o.command} reload` },
    groups: [...groups.entries()].map(([id, label], i) => ({ id, label, order: i })), params: out,
  };
  const v = validateConfigSpec(input);
  return v.ok ? { ok: true, spec: v.spec, skipped } : { ok: false, errors: v.errors.slice(0, 10).map((e) => `${e.path}: ${e.message}`) };
}

/** A studio patch -> designer ParamEdits (same paths; values as the designers expect them). */
export function toDesignerEdits(patch: Patch): { path: string; value: number | string }[] {
  return patch.filter((op) => typeof op.to === "number" || typeof op.to === "string").map((op) => ({ path: op.key, value: op.to as number | string }));
}

type ValuesRow = { row: AssetRow; values: ConfigValues; configYml: string; patch: Patch; specSha256: string };
function valuesRows(rows: readonly AssetRow[]): ValuesRow[] {
  return rows.filter((r) => r.kind === "config" && r.assetKey === "values" && r.mime === CONFIG_VALUES_MIME)
    .map((r) => { const p = obj(r.provenance); return { row: r, values: obj(p.values) as ConfigValues, configYml: typeof p.configYml === "string" ? p.configYml : "", patch: Array.isArray(p.patch) ? (p.patch as Patch) : [], specSha256: String(p.specSha256 ?? "") }; })
    .sort((a, b) => ts(a.row.createdAt) - ts(b.row.createdAt) || (a.row.id < b.row.id ? -1 : 1));
}

async function context(deps: ConfigServiceDeps, userId: string, rootBuildId: string) {
  const src = await deps.source(userId, rootBuildId);
  if (!src) throw new ConfigError(404, "not_found", "Mod not found.");
  const project = await deps.store.projectForRoot(rootBuildId);
  if (project && project.userId !== userId) throw new ConfigError(404, "not_found", "Mod not found.");
  const rows = project ? await deps.store.assets(project.id) : [];
  const schema = resolveSchema(src, rows, project?.namespace ?? "nx_00000000");
  const vrows = valuesRows(rows);
  return { src, project, rows, schema, vrows };
}

export async function configView(deps: ConfigServiceDeps, userId: string, rootBuildId: string): Promise<ConfigView> {
  const { src, project, schema, vrows } = await context(deps, userId, rootBuildId);
  const revs: RevRow[] = project ? await deps.store.revisions(project.id) : [];
  const spec = schema.spec;
  const defaults = spec ? defaultsOf(spec) : {};
  const shipped = spec && src.configYml ? readValues(spec, src.configYml).values : defaults;
  const last = vrows[vrows.length - 1];
  const values = spec ? (last ? checkValues(spec, last.values, "clamp", shipped).values : shipped) : {};
  const seqOf = new Map(revs.map((r) => [r.id, r]));
  return {
    project: project ? { id: project.id, namespace: project.namespace } : null,
    pluginName: src.pluginName, mcVersion: src.mcVersion, buildId: src.buildId,
    source: schema.source, spec, notes: schema.notes, values, shipped, defaults,
    changedFromDefaults: spec ? changedFromDefaults(spec, values) : [], preset: spec ? matchingPreset(spec, values) : "default",
    headRevisionId: project?.headRevisionId ?? null,
    history: vrows.slice(-30).reverse().map((v) => ({ revisionId: v.row.revisionId, seq: seqOf.get(v.row.revisionId)?.seq ?? 0, createdAt: iso(v.row.createdAt), message: seqOf.get(v.row.revisionId)?.message ?? null, patch: v.patch.slice(0, 40) })),
    visual: spec ? visualEffects(spec, values) : null,
    deliveryConnected: !!deps.deliver,
  };
}

export type PreviewResult = { configYml: string; patch: Patch; applies: string; errors: ValueIssue[]; warnings: ValueIssue[]; written: string[]; values?: ConfigValues; /** config.yml lines removed (-) / added (+), in file order */ lines?: { sign: "-" | "+"; text: string }[] };

/** What a save WOULD write (the diff drawer): no write. */
export async function previewConfig(deps: ConfigServiceDeps, userId: string, rootBuildId: string, values: Record<string, unknown>): Promise<PreviewResult> {
  const { src, schema, vrows } = await context(deps, userId, rootBuildId);
  return computeSave(schema.spec, src, vrows, values);
}

function computeSave(spec: ConfigSpec | null, src: ConfigSource, vrows: ValuesRow[], values: Record<string, unknown>): PreviewResult {
  if (!spec) throw new ConfigError(409, "no_settings", "This mod has no settings Cyrus can edit.");
  const shipped = src.configYml ? readValues(spec, src.configYml).values : defaultsOf(spec);
  const last = vrows[vrows.length - 1];
  const current = last ? checkValues(spec, last.values, "clamp", shipped).values : shipped;
  const chk = checkValues(spec, values, "strict", current);
  if (!chk.ok) return { configYml: "", patch: [], applies: "none", errors: chk.errors, warnings: chk.warnings, written: [] };
  const patch = diffValues(spec, current, chk.values);
  const baseText = last?.configYml || src.configYml || "";
  let text: string;
  let written: string[] = [];
  if (baseText) {
    const w = writeValues(spec, baseText, Object.fromEntries(patch.map((p) => [p.key, p.to])));
    if (!w.ok) return { configYml: "", patch, applies: "none", errors: w.errors, warnings: chk.warnings, written: [] };
    text = w.text; written = w.written;
  } else { text = renderConfigYml(spec, chk.values, [`${src.pluginName ?? "Mod"} configuration (written by the Cyrus Config Studio).`]); written = patch.map((p) => p.key); }
  return { configYml: text, patch, applies: appliesFor(spec, patch.map((p) => p.key)).applies, errors: [], warnings: chk.warnings, written, values: chk.values, lines: lineChanges(baseText, text) };
}

/** The lines a values-only write changed (it replaces value spans or inserts lines; nothing moves). */
export function lineChanges(before: string, after: string): { sign: "-" | "+"; text: string }[] {
  const a = before.split("\n"), b = after.split("\n");
  const out: { sign: "-" | "+"; text: string }[] = [];
  let i = 0, j = 0;
  while (i < a.length || j < b.length) {
    if (i < a.length && j < b.length && a[i] === b[j]) { i++; j++; continue; }
    // an inserted run: b[j..] until a[i] reappears
    const k = i < a.length ? b.indexOf(a[i], j) : -1;
    if (k > j && b.slice(j, k).every((l) => !a.slice(i).includes(l))) { for (; j < k; j++) out.push({ sign: "+", text: b[j] }); continue; }
    if (i < a.length) out.push({ sign: "-", text: a[i++] });
    if (j < b.length) out.push({ sign: "+", text: b[j++] });
    if (out.length > 200) break;
  }
  return out;
}

export type SaveInput = { userId: string; rootBuildId: string; values: Record<string, unknown>; expectedHeadId: string | null; message?: string };
export type SaveResult = { revisionId: string; seq: number; patch: Patch; applies: string; configYml: string; warnings: ValueIssue[] };

/** Save new values as a revision (values only). A stale editor (expectedHeadId) is a 409, never an overwrite. */
export async function saveConfigValues(deps: ConfigServiceDeps, i: SaveInput): Promise<SaveResult> {
  const ctx = await context(deps, i.userId, i.rootBuildId);
  const { src, schema, vrows } = ctx;
  const project = ctx.project ?? (deps.ensureProject ? await deps.ensureProject(i.userId, i.rootBuildId).catch(() => null) : null);
  if (!project) throw new ConfigError(409, "no_project", "This mod has no Cyrus project yet, so its settings cannot be saved as a revision.");
  if (project.userId !== i.userId) throw new ConfigError(404, "not_found", "Mod not found.");
  const p = computeSave(schema.spec, src, vrows, i.values);
  if (p.errors.length) throw new ConfigError(422, "invalid_values", p.errors[0].message, { errors: p.errors.slice(0, 20) });
  if (!p.patch.length) throw new ConfigError(409, "no_change", "Nothing changed.");
  const revs = await deps.store.revisions(project.id);
  const head = revs[revs.length - 1] ?? null;
  if ((head?.id ?? null) !== (i.expectedHeadId ?? null)) throw new ConfigError(409, "stale_head", "This mod changed since you opened it. Reload to see the newest settings.", { headRevisionId: head?.id ?? null });
  const spec = schema.spec!;
  const values = p.values!;
  const ymlSha = sha256(p.configYml);
  const manifest: ManifestEntry[] = [...(head?.manifest ?? []).filter((e) => e.path !== "src/main/resources/config.yml"), { path: "src/main/resources/config.yml", sha256: ymlSha, role: "config" }];
  const byKey = new Map(spec.params.map((x) => [x.key, x]));
  const summary = p.patch.slice(0, 3).map((op) => byKey.get(op.key)?.label ?? op.key).join(", ");
  const message = (i.message?.trim() || `Changed ${p.patch.length} setting${p.patch.length > 1 ? "s" : ""}: ${summary}${p.patch.length > 3 ? ", ..." : ""}`).slice(0, 200);
  const rev = await deps.store.addRevision(project.id, { kind: "config", manifest, status: "passed", expectedHeadId: head?.id ?? null, engine: { toolchain: CONFIG_TOOLCHAIN }, message });
  const specSha256 = sha256(canonical(spec));
  const payload = canonical({ values, patch: p.patch, revisionId: rev.id });
  await deps.store.recordAsset(project.id, {
    revisionId: rev.id, assetKey: "values", kind: "config", sha256: sha256(payload), size: Buffer.byteLength(payload), origin: "edited", mime: CONFIG_VALUES_MIME, path: "src/main/resources/config.yml",
    provenance: { generator: CONFIG_TOOLCHAIN, values, patch: p.patch, configYml: p.configYml, configYmlSha256: ymlSha, specSha256, schemaSource: schema.source, buildId: src.buildId, applies: p.applies },
  });
  return { revisionId: rev.id, seq: rev.seq, patch: p.patch, applies: p.applies, configYml: p.configYml, warnings: p.warnings };
}

/** Undo: a NEW revision with the values before `revisionId` (history is never edited). */
export async function revertConfig(deps: ConfigServiceDeps, i: { userId: string; rootBuildId: string; revisionId: string; expectedHeadId: string | null }): Promise<SaveResult> {
  const { src, schema, vrows } = await context(deps, i.userId, i.rootBuildId);
  const idx = vrows.findIndex((v) => v.row.revisionId === i.revisionId);
  if (idx < 0 || !schema.spec) throw new ConfigError(404, "not_found", "That settings revision is not in this mod.");
  const before = idx > 0 ? vrows[idx - 1].values : src.configYml ? readValues(schema.spec, src.configYml).values : defaultsOf(schema.spec);
  return saveConfigValues(deps, { userId: i.userId, rootBuildId: i.rootBuildId, values: before, expectedHeadId: i.expectedHeadId, message: `Undid revision ${i.revisionId.slice(0, 8)}` });
}

/** Deliver the current values to one of the owner's servers (needs the host's delivery wiring). */
export async function deliverConfigValues(deps: ConfigServiceDeps, i: { userId: string; rootBuildId: string; serverId: string }) {
  if (!deps.deliver) throw new ConfigError(501, "delivery_not_connected", "Sending settings to a server is not connected here yet. Your settings are saved; they go out with the next install or update.");
  const v = await configView(deps, i.userId, i.rootBuildId);
  if (!v.spec || !v.project || !v.pluginName) throw new ConfigError(409, "no_settings", "This mod has no settings Cyrus can deliver.");
  const changed = v.spec.params.filter((p) => !sameValue(v.values[p.key], v.shipped[p.key])).map((p) => p.key);
  const head = v.history[0];
  return deps.deliver({ userId: i.userId, serverId: i.serverId, projectId: v.project.id, revisionId: head?.revisionId ?? v.headRevisionId ?? "none", pluginName: v.pluginName, spec: v.spec, values: v.values, changed: changed.length ? changed : v.spec.params.map((p) => p.key) });
}

/** The command box: "set the walk speed to 0.3 and health to 40" -> edits (no model), or why it needs the model. */
export async function planConfig(deps: ConfigServiceDeps, userId: string, rootBuildId: string, text: string): Promise<ConfigEditPlan> {
  const v = await configView(deps, userId, rootBuildId);
  if (!v.spec) return { kind: "model", reason: "this mod has no settings" };
  return planConfigEdit(text, v.spec, v.values);
}

