// Cyrus R3 gameplay designers: EDIT WITHOUT REGENERATING. A parameter edit (cooldown, range, strength, sound, damage,
// durations, chances, texts...) changes values in the design and recompiles; because every graph value is a config.yml
// parameter, the recompile touches only config.yml (values + designer-values hash + config_version) and the README,
// never a Java file. `diffCompiled` shows exactly which files changed. `planDesignEdit` is the deterministic (no AI)
// recogniser for change requests that only tweak parameters ("set the void pull cooldown to 5 seconds and the pull
// strength to 2"); anything it cannot parse completely goes to the normal model path. Pure: no I/O, no model call.
import { compileDesigns, designParams, type CompileContext, type CompileOk, type Param } from "./compile";
import { ItemDesignSchema, type ItemDesign } from "./spec";

export type ParamEdit = { path: string; value: number | string };
export type AppliedEdit = { path: string; label: string; from: number | string; to: number | string };
export type EditResult = { ok: true; designs: ItemDesign[]; applied: AppliedEdit[] } | { ok: false; errors: string[] };

export const describeParameters = (designs: ItemDesign[]): Param[] => designParams(designs);

const camelKey = (s: string) => s.replace(/_([a-z])/g, (_, c: string) => c.toUpperCase());

/** Navigate a relative ability path ("a0.n1", "a2.then0", "c1", "a3.if0") to its node. */
function nodeAt(ab: Record<string, unknown>, rel: string[]): Record<string, unknown> | null {
  let cur: Record<string, unknown> | null = null;
  for (let i = 0; i < rel.length; i++) {
    const seg = rel[i];
    const m = /^(a|n|then|else|c|if)(\d+)$/.exec(seg);
    if (!m) return null;
    const idx = Number(m[2]);
    const list = (m[1] === "a" ? ab.actions : m[1] === "c" ? ab.conditions : m[1] === "n" ? cur?.actions : m[1] === "then" ? cur?.then : m[1] === "else" ? cur?.else : cur?.if) as unknown[] | undefined;
    if ((m[1] === "a" || m[1] === "c") && i !== 0) return null;
    if (!Array.isArray(list) || !list[idx] || typeof list[idx] !== "object") return null;
    cur = list[idx] as Record<string, unknown>;
  }
  return cur;
}

/** Set one parameter in a (cloned) design. Returns an error string or null. */
function setInDesign(d: ItemDesign, path: string, value: number | string): string | null {
  const parts = path.split(".");
  if (parts[0] !== "items" || parts[1] !== d.id) return `${path} is not in ${d.id}`;
  const rest = parts.slice(2);
  const obj = d as unknown as Record<string, unknown>;
  if (rest[0] === "abilities") {
    const ab = (d.abilities as unknown as Record<string, unknown>[]).find((a) => a.id === rest[1]);
    if (!ab) return `no ability ${rest[1]}`;
    const tail = rest.slice(2);
    if (tail.length === 1 && tail[0] === "cooldown_ticks") { ab.cooldownTicks = value; return null; }
    if (tail[0] === "charges" && tail.length === 2) { const c = ab.charges as Record<string, unknown> | undefined; if (!c) return "no charges"; c[camelKey(tail[1])] = value; return null; }
    if (tail[0] === "trigger" && tail.length === 2) { (ab.trigger as Record<string, unknown>)[camelKey(tail[1])] = value; return null; }
    const node = nodeAt(ab, tail.slice(0, -1).flatMap((s) => s.split("."))) ;
    if (!node) return `no node at ${tail.slice(0, -1).join(".")}`;
    node[camelKey(tail[tail.length - 1])] = value;
    return null;
  }
  if (rest[0] === "marks" && rest.length === 3) { const m = (d.marks as unknown as Record<string, unknown>[] | undefined)?.find((x) => x.name === rest[1]); if (!m) return `no mark ${rest[1]}`; m[camelKey(rest[2])] = value; return null; }
  if (rest[0] === "passives" && rest.length === 3) { const i = Number(rest[1].slice(1)); const p = (d.passives as unknown as Record<string, unknown>[] | undefined)?.[i]; if (!p) return `no passive ${rest[1]}`; p[camelKey(rest[2])] = value; return null; }
  if ((rest[0] === "loot" || rest[0] === "drops") && rest.length === 3) { const i = Number(rest[1].slice(1)); const acq = obj.acquisition as Record<string, unknown[]> | undefined; const l = acq?.[rest[0]]?.[i] as Record<string, unknown> | undefined; if (!l) return `no ${rest[0]} ${rest[1]}`; l[camelKey(rest[2])] = value; return null; }
  return `${path} is not a designer parameter`;
}

/** Apply parameter edits (exact config paths) to designs. Every value is checked against the parameter's caps. */
export function applyParameterEdits(designs: ItemDesign[], edits: ParamEdit[]): EditResult {
  const params = new Map(designParams(designs).map((p) => [p.path, p]));
  const out = designs.map((d) => structuredClone(d));
  const errors: string[] = [];
  const applied: AppliedEdit[] = [];
  for (const e of edits.slice(0, 32)) {
    const p = params.get(e.path);
    if (!p) { errors.push(`${e.path} is not a parameter of this mod (structural changes need a normal build)`); continue; }
    let v: number | string = e.value;
    if (p.kind === "text" || p.kind === "sound") {
      if (typeof v !== "string") { errors.push(`${e.path} needs text`); continue; }
      if (p.kind === "sound" && !/^[a-z0-9_.-]+:[a-z0-9_.-]+(\/[a-z0-9_.-]+)*$/.test(v)) { errors.push(`${e.path}: "${v}" is not a namespaced sound key`); continue; }
      if (v.length < (p.kind === "text" ? 1 : 3) || v.length > p.max) { errors.push(`${e.path}: text must be 1-${p.max} characters`); continue; }
    } else {
      if (typeof v !== "number" || !Number.isFinite(v)) { errors.push(`${e.path} needs a number`); continue; }
      if (p.kind !== "num") v = Math.round(v);
      if (v < p.min || v > p.max) { errors.push(`${e.path}: ${v} is outside ${p.min}-${p.max}`); continue; }
    }
    const d = out.find((x) => x.id === p.item)!;
    const err = setInDesign(d, e.path, v);
    if (err) { errors.push(err); continue; }
    applied.push({ path: e.path, label: p.label, from: p.value, to: v });
  }
  if (errors.length) return { ok: false, errors };
  for (const d of out) { const r = ItemDesignSchema.safeParse(d); if (!r.success) return { ok: false, errors: r.error.issues.slice(0, 5).map((i) => `${d.id}: ${i.path.join(".")}: ${i.message}`) }; }
  return { ok: true, designs: out, applied };
}

export type FileDiff = { path: string; status: "changed" | "added" | "removed"; before?: string; after?: string };
export type CompiledDiff = { changed: FileDiff[]; unchanged: number; javaChanged: string[]; readmeChanged: boolean };

export function diffCompiled(a: Pick<CompileOk, "files" | "readmeSha256">, b: Pick<CompileOk, "files" | "readmeSha256">): CompiledDiff {
  const am = new Map(a.files.map((f) => [f.path, f.sha256])), bm = new Map(b.files.map((f) => [f.path, f.sha256]));
  const changed: FileDiff[] = [];
  let unchanged = 0;
  for (const [p, h] of am) { if (!bm.has(p)) changed.push({ path: p, status: "removed", before: h }); else if (bm.get(p) !== h) changed.push({ path: p, status: "changed", before: h, after: bm.get(p) }); else unchanged++; }
  for (const [p, h] of bm) if (!am.has(p)) changed.push({ path: p, status: "added", after: h });
  changed.sort((x, y) => (x.path < y.path ? -1 : 1));
  return { changed, unchanged, javaChanged: changed.filter((c) => c.path.endsWith(".java")).map((c) => c.path), readmeChanged: a.readmeSha256 !== b.readmeSha256 };
}

/** Edit + recompile against the previous compile (its config.yml drives config_version). Only the affected files differ. */
export function recompileWithEdits(previous: CompileOk, edits: ParamEdit[], ctx: Omit<CompileContext, "previousConfig">): { ok: true; result: CompileOk; diff: CompiledDiff; applied: AppliedEdit[] } | { ok: false; errors: string[] } {
  const e = applyParameterEdits(previous.designs, edits);
  if (!e.ok) return e;
  const prevCfg = previous.files.find((f) => f.path === "src/main/resources/config.yml")?.content;
  const r = compileDesigns(e.designs, { ...ctx, previousConfig: prevCfg });
  if (!r.ok) return { ok: false, errors: r.errors.map((x) => `${x.path}: ${x.message}`) };
  return { ok: true, result: r, diff: diffCompiled(previous, r), applied: e.applied };
}

// --------------------------------------------------------------------------------------------- change-request parser
const ROLE_WORDS: [RegExp, string[]][] = [
  [/^(cooldown|cool ?down|recharge time)$/, ["cooldown"]],
  [/^(range|radius|reach|distance)$/, ["range"]],
  [/^(strength|power|force|pull strength|push strength|knockback|pull|push)$/, ["strength"]],
  [/^(damage|dmg)$/, ["damage"]],
  [/^(heal|healing|heal amount)$/, ["heal"]],
  [/^(duration|length)$/, ["duration"]],
  [/^(chance|probability|odds)$/, ["chance"]],
  [/^(sound|sfx|sound effect)$/, ["sound"]],
  [/^(charges?)$/, ["charges"]],
  [/^(speed|projectile speed|velocity)$/, ["speed"]],
  [/^(message|text)$/, ["text"]],
];
export type EditPlan =
  | { kind: "parameters"; edits: ParamEdit[]; summary: string[] }
  | { kind: "model"; reason: string; candidates?: string[] };

const norm = (s: string) => s.toLowerCase().replace(/[_-]/g, " ").replace(/\s+/g, " ").trim();

/**
 * Recognise a change request that ONLY tweaks parameters. Grammar per clause (clauses split by "and", ",", ";"):
 *   [set|change|make|increase|decrease|lower|raise|reduce] [the] [<item or ability name>] <role word> (to|=) <value> [s|sec|seconds|ticks|blocks|%]
 * Seconds are the default unit for cooldowns and durations (x20 ticks). Every clause must parse and resolve to exactly
 * one parameter (narrowed by the item/ability names in the clause), else the request goes to the model.
 */
export function planDesignEdit(text: string, designs: ItemDesign[]): EditPlan {
  const params = designParams(designs);
  if (!text || text.length > 400) return { kind: "model", reason: "empty or long request" };
  if (/\b(add|new|remove|delete|instead|also|another|when|if|make it (shoot|fire|summon)|texture|model|recipe|craft|rename)\b/i.test(text)) return { kind: "model", reason: "structural change" };
  const clauses = text.split(/\s*(?:\band\b|,|;)\s*/i).map((c) => c.trim()).filter(Boolean);
  if (!clauses.length || clauses.length > 6) return { kind: "model", reason: "no clauses" };
  const edits: ParamEdit[] = [];
  const summary: string[] = [];
  const names = designs.flatMap((d) => [{ item: d.id, ability: undefined as string | undefined, words: [norm(d.id), norm(d.name.text)] }, ...d.abilities.map((a) => ({ item: d.id, ability: a.id, words: [norm(a.id), norm(a.name)] }))]);
  let lastScope: typeof names = [];
  for (const raw of clauses) {
    const c = norm(raw).replace(/[.!?]+$/, "");
    const m = /^(?:(?:please )?(?:set|change|make|increase|decrease|lower|raise|reduce|put|adjust)\s+)?(?:the\s+)?(.+)\s+(?:to|=)\s+(.+)$/.exec(c);
    if (!m) return { kind: "model", reason: `could not read "${raw}"` };
    let subject = m[1].replace(/'s\b/g, "").trim();
    // the value comes from the RAW clause (sound keys and texts keep their case and underscores)
    const rawValue = (/^.*\s(?:to|=)\s+(.+?)[.!?]*$/i.exec(raw.trim())?.[1] ?? m[2]).trim();
    const valueText = m[2].trim();
    // scope words: item / ability names in the subject (longest first); a clause without one inherits the previous clause's
    let scope = names.filter((n) => n.words.some((w) => w && subject.includes(w)));
    for (const w of scope.flatMap((x) => x.words).filter(Boolean).sort((a, b) => b.length - a.length)) subject = subject.replace(w, " ");
    if (!scope.length) scope = lastScope; else lastScope = scope;
    subject = subject.replace(/\b(the|of|on|for|its|my)\b/g, " ").replace(/\s+/g, " ").trim();
    const role = ROLE_WORDS.find(([re]) => re.test(subject))?.[1];
    if (!role) return { kind: "model", reason: `"${raw}" is not a known parameter (${subject || "nothing"})` };
    let cands = params.filter((p) => role.includes(p.role) || (role.includes("charges") && p.path.endsWith(".charges.max")));
    const abScope = scope.filter((s) => s.ability);
    const itScope = scope.filter((s) => !s.ability);
    if (abScope.length) cands = cands.filter((p) => abScope.some((s) => s.item === p.item && s.ability === p.ability));
    else if (itScope.length) cands = cands.filter((p) => itScope.some((s) => s.item === p.item));
    // an ability's own cooldown beats set_cooldown params; one strength per pull/push node
    if (role.includes("cooldown") && cands.some((p) => p.path.endsWith(".cooldown_ticks"))) cands = cands.filter((p) => p.path.endsWith(".cooldown_ticks"));
    if (cands.length !== 1) return { kind: "model", reason: cands.length ? `"${raw}" matches ${cands.length} settings` : `"${raw}" matches no setting`, candidates: cands.map((p) => p.path).slice(0, 8) };
    const p = cands[0];
    let value: number | string;
    if (p.kind === "sound" || p.kind === "text") {
      value = p.kind === "sound" ? rawValue.replace(/\s+/g, "").toLowerCase() : rawValue.replace(/^["']|["']$/g, "");
    } else {
      const n = /^(-?\d+(?:\.\d+)?)\s*(s|sec|secs|seconds?|ticks?|blocks?|%|percent|hearts?)?$/.exec(valueText);
      if (!n) return { kind: "model", reason: `"${valueText}" is not a number` };
      let x = Number(n[1]);
      const unit = n[2] ?? "";
      if (p.kind === "ticks") x = /^tick/.test(unit) ? x : x * 20; // seconds by default
      else if (/^(%|percent)$/.test(unit)) x = x / 100;
      else if (/^heart/.test(unit)) x = x * 2;
      value = p.kind === "num" ? x : Math.round(x);
    }
    edits.push({ path: p.path, value });
    summary.push(`${p.label}: ${p.value} -> ${value}`);
  }
  return { kind: "parameters", edits, summary };
}

