  role: string;
  /** R3 menus/quests/bosses/encounters/HUDs: the parameter belongs to that design (`item` then holds its id); absent = an item parameter. */
  owner?: "menu" | "quest" | "boss" | "encounter" | "hud";
  /** Bosses / encounters / HUDs: where the value lives in the design (edit without regenerating sets it there). */
  ptr?: (string | number)[];
};

export type CompileContext = {
