      lowNoted = true;
    } else if (lastTps >= S.tpsFloor) {
      lowNoted = false;
    }
    if (seconds % 5 == 0) wrapListeners();
    if (seconds % 30 == 0) readSettings();
    int every = System.currentTimeMillis() - enabledAtMs < 15 * 60_000L ? 30 : S.statusLogSeconds;
    if (++secondsSinceStatus >= every) {
      secondsSinceStatus = 0;
      plugin.getLogger().info("[NxPerf] status v=" + NxPerfCore.VERSION + " plugin=" + plugin.getName() + " tps=" + NxPerfCore.fmt(lastTps)
          + " paper_tps=" + NxPerfCore.fmt(paperTps()) + " mspt=" + NxPerfCore.fmt(paperMspt()) + " own_ms=" + NxPerfCore.fmt(lastOwnMs) + " spawns_denied=" + deniedSpawnsTotal + " paused=" + paused);
    }
  }

  private static double paperTps() {
    try { return Math.min(20.0, Bukkit.getTPS()[0]); } catch (RuntimeException e) { return lastTps; }
  }

  private static double paperMspt() {
    try { return Bukkit.getAverageTickTime(); } catch (RuntimeException e) { return -1; }
  }

  // ------------------------------------------------------------------ listener timing ----

  /** A listener of this plugin with its main-thread time measured; the original keeps doing the work. */
  private static final class Timed extends RegisteredListener {
    final RegisteredListener inner;
    final HandlerList list;
    String event = "?";
    long nanosSecond, calls;
    double recentMs;

    Timed(RegisteredListener in, HandlerList list) {
      super(in.getListener(), (l, e) -> { }, in.getPriority(), in.getPlugin(), in.isIgnoringCancelled());
      this.inner = in;
      this.list = list;
    }

    @Override
    public void callEvent(Event e) throws EventException {
      if (!Bukkit.isPrimaryThread()) {
        inner.callEvent(e);
        return;
      }
      long t = System.nanoTime();
      ownDepth++;
      try {
        inner.callEvent(e);
      } finally {
        ownDepth--;
        long d = System.nanoTime() - t;
        nanosSecond += d;
        calls++;
        ownNanosTick += d;
        ownNanosSecond += d;
        if (event.equals("?")) event = e.getEventName();
      }
    }

    void roll() {
      recentMs = recentMs * 0.8 + nanosSecond / 1e6;
      nanosSecond = 0;
    }

    String label() { return inner.getListener().getClass().getSimpleName() + "/" + event; }
  }

  private static void wrapListeners() {
    if (plugin == null) return;
    for (HandlerList hl : new ArrayList<>(HandlerList.getHandlerLists())) {
      for (RegisteredListener rl : hl.getRegisteredListeners()) {
        if (rl.getPlugin() != plugin || rl instanceof Timed || rl.getListener() instanceof SpawnGuard) continue;
        Timed t = new Timed(rl, hl);
        hl.unregister(rl);
        hl.register(t);
        TIMED.add(t);
      }
    }
  }

  /** Caps the entities this plugin's own code spawns (perf.max-spawns-per-second); never touches other plugins' or vanilla spawns. */
  public static final class SpawnGuard implements Listener {
    @EventHandler(priority = EventPriority.HIGHEST, ignoreCancelled = true)
    public void onSpawn(EntitySpawnEvent e) {
      if (ownDepth <= 0 || !Bukkit.isPrimaryThread() || e.getEntity() instanceof Player) return;
      if (paused || ownSpawnsSecond >= S.maxSpawnsPerSecond) {
        e.setCancelled(true);
        deniedSpawnsSecond++;
        deniedSpawnsTotal++;
        return;
      }
      ownSpawnsSecond++;
    }
  }

  // ------------------------------------------------------------------ pause / resume ----

  /** Pause the plugin's heavy features (never the server, never another plugin). */
  public static synchronized void pause(String reason, String detail) {
    if (paused || plugin == null) return;
    paused = true;
    pauseReason = reason;
    List<Timed> byCost = new ArrayList<>(TIMED);
    byCost.sort(Comparator.comparingDouble((Timed t) -> -t.recentMs));
    double total = 0;
    for (Timed t : byCost) total += t.recentMs;
    double acc = 0;
    List<String> names = new ArrayList<>();
    for (Timed t : byCost) {
      if (total <= 0 || t.recentMs <= 0) break;
      t.list.unregister(t);
      PAUSED_LISTENERS.add(t);
      names.add(t.label());
      acc += t.recentMs;
      if (acc >= total * 0.9) break;
    }
    for (Timer t : TIMERS) t.stop();
    for (Queue<?> q : QUEUES) q.clear();
    for (Runnable r : ON_PAUSE) {
      try { r.run(); } catch (RuntimeException e) { plugin.getLogger().warning("[NxPerf] a pause hook failed: " + e); }
    }
    String line = "[NxPerf] PAUSED plugin=" + plugin.getName() + " reason=" + reason + " tps=" + NxPerfCore.fmt(lastTps) + " own_ms=" + NxPerfCore.fmt(lastOwnMs)
        + " listeners=" + (names.isEmpty() ? "none" : String.join(",", names)) + " timers=" + TIMERS.size() + " detail=" + detail;
    plugin.getLogger().warning(line);
    tellOps("Performance safety paused this mod's heavy features (" + detail + "). The server keeps running. Check with /" + label() + " perf status, resume with /" + label() + " perf resume.");
  }

  public static synchronized void resume(String by) {
    if (!paused || plugin == null) return;
    for (Timed t : PAUSED_LISTENERS) t.list.register(t);
    PAUSED_LISTENERS.clear();
    for (Timer t : TIMERS) t.start();
    for (Runnable r : ON_RESUME) {
      try { r.run(); } catch (RuntimeException e) { plugin.getLogger().warning("[NxPerf] a resume hook failed: " + e); }
    }
    paused = false;
    pauseReason = null;
    JUDGE.reset();
    plugin.getLogger().warning("[NxPerf] RESUMED plugin=" + plugin.getName() + " by=" + by);
  }

  private static void tellOps(String text) {
    Component m = Component.text("[" + plugin.getName() + "] " + text, NamedTextColor.GOLD);
    String perm = plugin.getName().toLowerCase(Locale.ROOT) + ".perf";
    for (Player p : Bukkit.getOnlinePlayers()) if (p.isOp() || p.hasPermission(perm)) p.sendMessage(m);
  }

  // ------------------------------------------------------------------ API for the plugin ----

  /** false while the heavy features are paused: check it before starting heavy work. */
  public static boolean active() { return !paused; }

  public static boolean paused() { return paused; }

  /** Take n work units from this tick's budget `name` (perf.max-work-per-tick). false = stop for this tick. */
  public static boolean take(String name, int n) {
    if (paused) return false;
    NxPerfCore.Budget b = BUDGETS.computeIfAbsent(name, k -> new NxPerfCore.Budget(k, S.maxWorkPerTick));
    return b.take(Bukkit.getCurrentTick(), n);
  }

  public static boolean take(String name) { return take(name, 1); }

  /** Work units left this tick for budget `name`. */
  public static int remaining(String name) {
    NxPerfCore.Budget b = BUDGETS.computeIfAbsent(name, k -> new NxPerfCore.Budget(k, S.maxWorkPerTick));
    return paused ? 0 : b.remaining(Bukkit.getCurrentTick());
  }

  /** May the plugin spawn one more entity for `name` now? perf.max-entities-per-second and perf.max-entities-per-chunk. */
  public static boolean spawnAllowed(String name, Chunk chunk) {
    if (paused) return false;
    if (chunk != null) {
      int living = 0;
      for (Entity e : chunk.getEntities()) if (e instanceof LivingEntity && !(e instanceof Player)) living++;
      if (living >= S.maxEntitiesPerChunk) return false;
    }
    NxPerfCore.Rate r = RATES.computeIfAbsent("spawn:" + name, k -> new NxPerfCore.Rate(S.maxEntitiesPerSecond));
    return r.take(System.nanoTime());
  }

  /** A per-second rate limit (e.g. explosions, effects). */
  public static boolean rate(String name, double perSecond) {
    if (paused) return false;
    return RATES.computeIfAbsent("rate:" + name, k -> new NxPerfCore.Rate(perSecond)).take(System.nanoTime());
  }

  /** Recursion guard: false when `key` is already running on this call stack (e.g. a change made by this plugin's own handler). */
  public static boolean enter(String key) {
    int d = DEPTH.getOrDefault(key, 0);
    if (d > 0) return false;
    DEPTH.put(key, d + 1);
    return true;
  }

  public static void exit(String key) {
    int d = DEPTH.getOrDefault(key, 0);
    if (d <= 1) DEPTH.remove(key); else DEPTH.put(key, d - 1);
  }

  /** A radius clamped to 1..perf.max-radius blocks. */
  public static int radius(int wanted) { return NxPerfCore.clampInt(wanted, 1, S.maxRadius); }

  /** perf.max-work-per-tick. */
  public static int perTick() { return S.maxWorkPerTick; }

  /** perf.max-queue. */
  public static int maxQueue() { return S.maxQueue; }

  public static void onPause(Runnable r) { ON_PAUSE.add(r); }

  public static void onResume(Runnable r) { ON_RESUME.add(r); }

  /** A bounded work queue drained every tick within the budget `name`. offer() is false when full or paused. */
  public static <T> Queue<T> queue(String name, Consumer<T> worker) {
    Queue<T> q = new Queue<>(name, worker);
    QUEUES.add(q);
    return q;
  }

  public static final class Queue<T> {
    private final String name;
    private final Consumer<T> worker;
    private final ArrayDeque<T> items = new ArrayDeque<>();
    private long dropped;
    private boolean warned;

    Queue(String name, Consumer<T> worker) {
      this.name = name;
      this.worker = worker;
    }

    public boolean offer(T item) {
      if (paused || items.size() >= S.maxQueue) {
        dropped++;
        if (!warned && !paused) {
          warned = true;
          plugin.getLogger().warning("[NxPerf] queue " + name + " is full (" + S.maxQueue + "); extra work is dropped");
        }
        return false;
      }
      items.add(item);
      return true;
    }

    public int size() { return items.size(); }

    public long dropped() { return dropped; }

    void clear() { dropped += items.size(); items.clear(); }

    void drain() {
      if (paused || items.isEmpty()) return;
      long t = System.nanoTime();
      ownDepth++;
      try {
        while (!items.isEmpty() && take(name, 1)) {
          T x = items.poll();
          try {
            worker.accept(x);
          } catch (RuntimeException e) {
            plugin.getLogger().warning("[NxPerf] queue " + name + " task failed: " + e);
          }
        }
      } finally {
        ownDepth--;
      }
      long d = System.nanoTime() - t;
      ownNanosTick += d;
      ownNanosSecond += d;
    }
  }

  /** A repeating task that is measured and paused with the heavy features. period is clamped to at least 1 tick. */
  public static Timer timer(String name, long delayTicks, long periodTicks, Runnable work) {
    Timer t = new Timer(name, Math.max(0, delayTicks), Math.max(1, periodTicks), work);
    TIMERS.add(t);
    if (!paused) t.start();
    return t;
  }

  public static final class Timer {
    private final String name;
    private final long delay, period;
    private final Runnable work;
    private BukkitTask task;

    Timer(String name, long delay, long period, Runnable work) {
      this.name = name;
      this.delay = delay;
      this.period = period;
      this.work = work;
    }

    void start() {
      if (task != null || plugin == null) return;
      task = Bukkit.getScheduler().runTaskTimer(plugin, () -> {
        if (paused) return;
        long t = System.nanoTime();
        ownDepth++;
        try {
          work.run();
        } finally {
          ownDepth--;
          long d = System.nanoTime() - t;
          ownNanosTick += d;
          ownNanosSecond += d;
        }
      }, delay, period);
    }

    void stop() {
      if (task != null) task.cancel();
      task = null;
    }

    public void cancel() {
      stop();
      TIMERS.remove(this);
    }

    public String name() { return name; }
  }

  // ------------------------------------------------------------------ command ----

  private static String label() {
    return commandLabel != null ? commandLabel : plugin.getName().toLowerCase(Locale.ROOT) + "perf";
  }

  private static void hookCommand() {
    if (plugin == null) return;
    PluginCommand own = null;
    String want = plugin.getName().toLowerCase(Locale.ROOT);
    for (Map.Entry<String, Command> e : Bukkit.getCommandMap().getKnownCommands().entrySet()) {
      if (!(e.getValue() instanceof PluginCommand pc) || pc.getPlugin() != plugin || e.getKey().contains(":")) continue;
      if (own == null || pc.getName().equals(want) || (!own.getName().equals(want) && pc.getName().compareTo(own.getName()) < 0)) own = pc;
    }
    if (own != null) {
      final CommandExecutor inner = own.getExecutor();
      own.setExecutor((sender, cmd, lbl, args) -> {
        if (args.length > 0 && args[0].equalsIgnoreCase("perf")) return perfCommand(sender, args);
        return inner.onCommand(sender, cmd, lbl, args);
      });
      commandLabel = own.getName();
      return;
    }
    String name = want + "perf";
    Bukkit.getCommandMap().register(want, new Command(name, "Performance safety status for " + plugin.getName(), "/" + name + " [status|pause|resume]", new ArrayList<>()) {
      @Override
      public boolean execute(CommandSender sender, String lbl, String[] args) {
        String[] a = new String[args.length + 1];
        a[0] = "perf";
        System.arraycopy(args, 0, a, 1, args.length);
        return perfCommand(sender, a);
      }
    });
    commandLabel = name;
  }

  private static boolean perfCommand(CommandSender sender, String[] args) {
    String perm = plugin.getName().toLowerCase(Locale.ROOT) + ".perf";
    if (!(sender instanceof ConsoleCommandSender) && !sender.isOp() && !sender.hasPermission(perm)) {
      sender.sendMessage(Component.text("You need " + perm + " (or operator) for this.", NamedTextColor.RED));
      return true;
    }
    String sub = args.length > 1 ? args[1].toLowerCase(Locale.ROOT) : "status";
    switch (sub) {
      case "pause", "off" -> {
        pause("manual", "paused by " + sender.getName());
        sender.sendMessage(Component.text("Heavy features paused.", NamedTextColor.YELLOW));
      }
      case "resume", "on" -> {
        resume(sender.getName());
        sender.sendMessage(Component.text("Heavy features resumed.", NamedTextColor.GREEN));
      }
      default -> {
        sender.sendMessage(Component.text("NxPerf " + plugin.getName() + ": TPS " + NxPerfCore.fmt(lastTps) + " (Paper " + NxPerfCore.fmt(paperTps()) + "), MSPT "
            + NxPerfCore.fmt(paperMspt()) + ", this plugin " + NxPerfCore.fmt(lastOwnMs) + " ms/tick, " + (paused ? "PAUSED (" + pauseReason + ")" : "running"), NamedTextColor.AQUA));
        List<Timed> byCost = new ArrayList<>(TIMED);
        byCost.sort(Comparator.comparingDouble((Timed t) -> -t.recentMs));
        for (int i = 0; i < Math.min(3, byCost.size()); i++) {
          Timed t = byCost.get(i);
          sender.sendMessage(Component.text("  " + t.label() + ": " + NxPerfCore.fmt(t.recentMs / 5.0) + " ms/s, " + t.calls + " calls", NamedTextColor.GRAY));
        }
        for (NxPerfCore.Budget b : BUDGETS.values()) sender.sendMessage(Component.text("  budget " + b.name + ": " + b.perTick() + "/tick, denied " + b.denied(), NamedTextColor.GRAY));
        sender.sendMessage(Component.text("  floor " + NxPerfCore.fmt(S.tpsFloor) + " TPS for " + S.windowSeconds + " s, auto-disable " + S.autoDisable
            + ", max work/tick " + S.maxWorkPerTick + ", spawns/s " + S.maxSpawnsPerSecond + " (denied " + deniedSpawnsTotal + "). /" + label() + " perf pause|resume", NamedTextColor.GRAY));
      }
    }
    return true;
  }
}

"use strict";
// Cyrus perf safety (2026-10-11, after the ChunkMirror incident): the WATCHDOG injection and the PERF pre-check.
//
// inject(ws, rec): before every javac of a generated (not imported) plugin, place the audited watchdog sources
//   (perf/src/NxPerf*.java) into <main package>.nxperf, call NxPerf.init(this) first thing in onEnable (added when
//   missing), point any NxPerf import at that package, and append the perf: section to config.yml. The files are
//   overwritten on every round, so the model can never ship a modified watchdog. Pure file edits, deterministic.
// perfcheck(files): source heuristics for unbounded work (world-wide iteration, spawns/explosions in loops, raw
//   repeating tasks, recursion through the plugin's own events, huge radius/per-tick literals) without the NxPerf
//   bounds. Hits go back to the model like pre-check problems (each once); they never block a build on their own.
// MB_PERF_SAFETY=0 turns both off (default on).

const fs = require("fs");
const path = require("path");

const PERF_VERSION = "nxperf-1";
const SRC_DIR = path.join(__dirname, "perf", "src");
const FILES = ["NxPerfCore.java", "NxPerf.java"];
const enabled = (env = process.env) => !/^(0|false|off)$/i.test(String(env.MB_PERF_SAFETY ?? "").trim());

const CONFIG_SECTION = `
# Performance safety (added by Nxeon). If the server stays under tps-floor for window-seconds while this mod
# causes the lag, its heavy features pause (the server keeps running). /<command> perf status shows the numbers.
perf:
  auto-disable: true
  tps-floor: 15.0
  window-seconds: 10
  max-work-per-tick: 64
  max-ms-per-tick: 25.0
  max-entities-per-second: 5
  max-entities-per-chunk: 20
  max-queue: 2000
  max-radius: 48
  max-spawns-per-second: 50
`;

function readPluginYml(ws) {
  const p = path.join(ws, "src/main/resources/plugin.yml");
  try { return fs.readFileSync(p, "utf8"); } catch { return null; }
}
function mainClassOf(yml) {
  const m = /^main:\s*['"]?([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)+)['"]?\s*$/m.exec(yml || "");
  return m ? m[1] : null;
}
const sourceOf = (ws, fqn) => path.join(ws, "src/main/java", ...fqn.split(".")) + ".java";

/** The watchdog sources for a package (exported for tests and fixtures). */
function watchdogSources(pkg) {
  if (!/^[a-z_][a-z0-9_]*(\.[a-z_][a-z0-9_]*)*$/.test(pkg)) throw new Error(`bad package ${pkg}`);
  return FILES.map((f) => ({ name: f, content: fs.readFileSync(path.join(SRC_DIR, f), "utf8").replace(/@PKG@/g, pkg) }));
}

/** Insert NxPerf.init(this) as the first statement of onEnable (or add an onEnable). Returns the new text or null if unchanged. */
function patchMain(src, perfPkg, className) {
  if (/\bNxPerf\s*\.\s*init\s*\(\s*this\s*\)/.test(src)) return null;
  const call = `${perfPkg}.NxPerf.init(this); // Nxeon performance safety (added by the build service)`;
  const m = /\bvoid\s+onEnable\s*\(\s*\)\s*(?:throws\s+[\w.,\s]+)?\{/.exec(src);
  if (m) return src.slice(0, m.index + m[0].length) + `\n    ${call}` + src.slice(m.index + m[0].length);
  // no onEnable: add one before the class's closing brace
  const cls = new RegExp(`\\bclass\\s+${className}\\b`).exec(src);
  const end = src.lastIndexOf("}");
  if (!cls || end < cls.index) return null;
  return `${src.slice(0, end)}\n  @Override\n  public void onEnable() {\n    ${call}\n  }\n${src.slice(end)}`;
}

/**
 * Place the watchdog into a generated workspace. Returns { injected, reason?, pkg?, mainPatched?, configSection? }.
 * Never throws for a workspace it cannot handle (validate()/javac report those); imported plugins are left alone.
 */
function inject(ws, rec = {}, env = process.env) {
  if (!enabled(env)) return { injected: false, reason: "MB_PERF_SAFETY is off" };
  if (rec.imported) return { injected: false, reason: "imported plugin (the owner's own code is not changed)" };
  const main = mainClassOf(readPluginYml(ws));
  if (!main) return { injected: false, reason: "no main class in plugin.yml" };
  const mainFile = sourceOf(ws, main);
  if (!fs.existsSync(mainFile)) return { injected: false, reason: `main class source ${main} not found` };
  const pkg = main.slice(0, main.lastIndexOf("."));
  const perfPkg = `${pkg}.nxperf`;
  const dir = path.join(ws, "src/main/java", ...perfPkg.split("."));
  fs.mkdirSync(dir, { recursive: true });
  for (const f of watchdogSources(perfPkg)) fs.writeFileSync(path.join(dir, f.name), f.content);
  // any NxPerf import the model wrote points at the injected package
  const javaRoot = path.join(ws, "src/main/java");
  const walk = (d) => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(path.join(d, e.name)) : e.name.endsWith(".java") ? [path.join(d, e.name)] : []));
  for (const f of walk(javaRoot)) {
    if (path.dirname(f) === dir) continue;
    const s = fs.readFileSync(f, "utf8");
    const t = s.replace(/^import\s+(?:static\s+)?[\w.]*\bnxperf\.(NxPerf(?:Core)?)\s*;/gm, (_m, cls) => `import ${perfPkg}.${cls};`)
      .replace(/^import\s+dev\.nxeon\.cyrus\.perf\.(NxPerf(?:Core)?)\s*;/gm, (_m, cls) => `import ${perfPkg}.${cls};`);
    if (t !== s) fs.writeFileSync(f, t);
  }
  const src = fs.readFileSync(mainFile, "utf8");
  const patched = patchMain(src, perfPkg, main.slice(main.lastIndexOf(".") + 1));
  if (patched) fs.writeFileSync(mainFile, patched);
  const cfg = path.join(ws, "src/main/resources/config.yml");
  let configSection = false;
  if (fs.existsSync(cfg)) {
    const y = fs.readFileSync(cfg, "utf8");
    if (!/^perf\s*:/m.test(y)) { fs.writeFileSync(cfg, y.replace(/\s*$/, "\n") + CONFIG_SECTION); configSection = true; }
  }
  const r = { injected: true, version: PERF_VERSION, pkg: perfPkg, mainPatched: !!patched, configSection };
  rec.perf = r;
  return r;
}

// ------------------------------------------------------------------ PERF pre-check ----
const stripComments = (s) => s.replace(/\/\*[\s\S]*?\*\//g, (m) => m.replace(/[^\n]/g, " ")).replace(/\/\/[^\n]*/g, "").replace(/"(?:[^"\\\n]|\\.)*"/g, '""');

/** Line ranges of loop bodies (for/while/do + forEach), by brace matching on comment- and string-free text. */
function loopRanges(src) {
  const out = [];
  const re = /\b(for|while)\s*\(|\bdo\s*\{|\.forEach\s*\(/g;
  let m;
  while ((m = re.exec(src))) {
    let i = src.indexOf("{", m.index);
    if (i < 0) continue;
    // for/while: skip the header parens first
    if (!m[1] && /;/.test(src.slice(m.index, i))) continue; // forEach(this::x); has no body
    if (m[1]) { let d = 0, j = src.indexOf("(", m.index); for (; j < src.length; j++) { if (src[j] === "(") d++; else if (src[j] === ")" && --d === 0) break; } i = src.indexOf("{", j); if (i < 0 || /[;]/.test(src.slice(j + 1, i))) continue; }
    let d = 0, k = i;
    for (; k < src.length; k++) { if (src[k] === "{") d++; else if (src[k] === "}" && --d === 0) break; }
    out.push([lineAt(src, m.index), lineAt(src, k)]);
  }
  return out;
}
const lineAt = (s, i) => s.slice(0, i).split("\n").length;

/** Handler method ranges (@EventHandler ... { ... }). */
function handlerRanges(src) {
  const out = [];
  const re = /@EventHandler\b[^{;]*?\(\s*(?:final\s+)?(\w+)\s+\w+\s*\)\s*(?:throws[^{]*)?\{/g;
  let m;
  while ((m = re.exec(src))) {
    let d = 0, k = m.index + m[0].length - 1;
    for (; k < src.length; k++) { if (src[k] === "{") d++; else if (src[k] === "}" && --d === 0) break; }
    out.push({ event: m[1], from: lineAt(src, m.index), to: lineAt(src, k) });
  }
  return out;
}

const PERF_RULES = [
  { id: "perf-world-iteration", re: /\.(getLoadedChunks|getEntities|getLivingEntities|getEntitiesByClass|getEntitiesByClasses)\s*\(\s*\)/, ctx: "any", bounded: /NxPerf\s*\.\s*(take|queue|remaining)\b/,
    fix: "Iterating every loaded chunk or entity of a world ($1) has no upper bound. Use getNearbyEntities(radius) around a player with NxPerf.radius(...), or put the work into an NxPerf.queue(...) / check NxPerf.take(...) so at most perf.max-work-per-tick items run per tick." },
  { id: "perf-spawn-in-loop", re: /\.(spawnEntity|spawn|spawnFallingBlock|dropItem|dropItemNaturally)\s*\(/, ctx: "loop", bounded: /NxPerf\s*\.\s*(spawnAllowed|take|queue)\b/,
    fix: "Spawning inside a loop ($1) multiplies entities. Check NxPerf.spawnAllowed(\"<feature>\", chunk) before each spawn (perf.max-entities-per-second, perf.max-entities-per-chunk)." },
  { id: "perf-explosion-in-loop", re: /\.(createExplosion)\s*\(/, ctx: "loop", bounded: /NxPerf\s*\.\s*(rate|take)\b/,
    fix: "Explosions inside a loop chain into each other. Rate-limit them with NxPerf.rate(\"explosions\", 5) and cap the power at 4." },
  { id: "perf-chunk-load-in-loop", re: /\.(getChunkAt|loadChunk|getChunkAtAsync|setChunkForceLoaded|addPluginChunkTicket)\s*\(/, ctx: "loop", bounded: /NxPerf\s*\.\s*(take|queue)\b|isChunkLoaded/,
    fix: "Loading chunks in a loop ($1) loads or generates terrain without limit. Only touch chunks that are already loaded (isChunkLoaded) near players, through NxPerf.queue(...)." },
  { id: "perf-block-loop", re: /\.(setType|setBlockData|breakNaturally)\s*\(/, ctx: "loop", bounded: /NxPerf\s*\.\s*(take|queue|remaining)\b/,
    fix: "Changing blocks inside a loop ($1) has no per-tick limit. Queue the changes with NxPerf.queue(...) (or check NxPerf.take(\"blocks\")) so at most perf.max-work-per-tick run per tick." },
  { id: "perf-raw-timer", re: /\.(runTaskTimer|runTaskTimerAsynchronously|scheduleSyncRepeatingTask)\s*\(/, ctx: "any", bounded: /NxPerf\s*\.\s*timer\b/,
    fix: "Repeating work must use NxPerf.timer(\"<feature>\", delayTicks, periodTicks, () -> ...) so the watchdog can measure and pause it ($1 cannot be paused)." },
  { id: "perf-call-event", re: /\.callEvent\s*\(/, ctx: "handler", bounded: /NxPerf\s*\.\s*enter\b/,
    fix: "Firing an event from inside an event handler can loop through the plugin's own handler. Guard it with if (!NxPerf.enter(\"<key>\")) return; ... finally NxPerf.exit(\"<key>\")." },
  { id: "perf-infinite-loop", re: /\bwhile\s*\(\s*true\s*\)|\bfor\s*\(\s*;\s*;\s*\)/, ctx: "any", bounded: null,
    fix: "An endless loop on the server thread freezes the server. Use a bounded loop or an NxPerf.timer that does a little work per tick." },
  { id: "perf-huge-literal", re: /\b(?:getNearbyEntities|getNearbyLivingEntities|getNearbyPlayers)\s*\(\s*(?:[\w.]+\s*,\s*)?(\d{3,})(?:\.\d+)?/, ctx: "any", bounded: null,
    fix: "A search radius of $1 blocks is far too large (work grows with the cube of the radius). Use NxPerf.radius(<configured radius>) (at most perf.max-radius)." },
];

/** files: [{rel, abs}] of .java sources. Returns [{rule, where, message, evidence}] (one per rule and file). */
function perfcheck(files, env = process.env) {
  if (!enabled(env)) return [];
  const out = [];
  for (const f of files) {
    if (/\/nxperf\/NxPerf(Core)?\.java$/.test(f.rel)) continue;
    const raw = fs.readFileSync(f.abs, "utf8");
    const src = stripComments(raw);
    const lines = src.split("\n");
    const loops = loopRanges(src), handlers = handlerRanges(src);
    const inLoop = (n) => loops.some(([a, b]) => n > a && n <= b) || loops.some(([a, b]) => n === a && a === b);
    const inHandler = (n) => handlers.some((h) => n > h.from && n <= h.to);
    for (const r of PERF_RULES) {
      if (r.bounded && r.bounded.test(src)) continue;
      for (let i = 0; i < lines.length; i++) {
        const m = lines[i].match(r.re);
        if (!m) continue;
        const n = i + 1;
        if (r.ctx === "loop" && !inLoop(n)) continue;
        if (r.ctx === "handler" && !inHandler(n)) continue;
        out.push({ rule: r.id, where: `${f.rel}:${n}`, message: r.fix.replace(/\$(\d)/g, (_, k) => m[+k] || ""), evidence: raw.split("\n")[i].trim().slice(0, 160) });
        break;
      }
    }
  }
  return out;
}

/** config.yml values that break the hard limits (per-tick > 256, radius > 64 blocks, mob mirroring on). */
function configCheck(ws, env = process.env) {
  if (!enabled(env)) return [];
  let y;
  try { y = fs.readFileSync(path.join(ws, "src/main/resources/config.yml"), "utf8"); } catch { return []; }
  const out = [];
  y.split("\n").forEach((l, i) => {
    const m = /^\s*([A-Za-z0-9_.-]+)\s*:\s*(-?\d+(?:\.\d+)?|true|false)\s*(?:#.*)?$/.exec(l);
    if (!m || /^\s*(auto-disable|tps-floor|window-seconds|max-work-per-tick|max-ms-per-tick|max-entities-per-second|max-entities-per-chunk|max-queue|max-radius|max-spawns-per-second|share|status-log-seconds)\s*:/.test(l)) return;
    const [k, v] = [m[1].toLowerCase(), m[2]];
    const n = Number(v);
    if (/(per-?tick|batch|per-?cycle)/.test(k) && n > 256) out.push({ rule: "perf-config-per-tick", where: `src/main/resources/config.yml:${i + 1}`, message: `${m[1]}: ${v} is above the hard maximum of 256 work items per tick. Default it to 64 or less and clamp the value when you read it (Math.min(value, 256)).`, evidence: l.trim() });
    if (/(radius|range|distance)/.test(k) && n > 64 && !/(view|chat|message|teleport|tp|spawn-?radius|border)/.test(k)) out.push({ rule: "perf-config-radius", where: `src/main/resources/config.yml:${i + 1}`, message: `${m[1]}: ${v} blocks is too large for repeated work. Default it to 16 or less and clamp with NxPerf.radius(...).`, evidence: l.trim() });
    if (/(mirror|copy|clone|duplicate|replicate)-?(mobs?|entit|spawns?)/.test(k) && v === "true") out.push({ rule: "perf-config-mob-copy", where: `src/main/resources/config.yml:${i + 1}`, message: `${m[1]}: copying mobs must default to false (an operator can enable it; then use NxPerf.spawnAllowed).`, evidence: l.trim() });
  });
  return out;
}

module.exports = { PERF_VERSION, CONFIG_SECTION, enabled, inject, patchMain, watchdogSources, mainClassOf, perfcheck, configCheck, PERF_RULES };
NxPerfCoreTest.java

function knowledgeVersion() {
  return `${SHEETS_ON ? "sheets" : "nosheets"}+${RULES_ON ? RULES.version : "norules"}${PERF.enabled() ? `+${PERF.PERF_VERSION}` : ""}`;
}

// Cyrus perf safety (2026-10-11, ChunkMirror incident): the PERFORMANCE section + the NxPerf API sheet. Appended to every
// generated build's system prompt while MB_PERF_SAFETY is on (default); fixed text, so it caches per version. The
// watchdog itself is injected by perf.js before javac, whatever the model writes.
const PERF_SECTION = `

PERFORMANCE (hard rule 10; the build service checks it and every build is load-tested on a real server):
10. Every piece of work must be BOUNDED. A Minecraft server has 50 ms per tick for everything; a plugin that loops over the whole world, copies changes into every chunk or spawns without a limit drops a real server to 1 TPS. So:
- Never iterate all loaded chunks, all entities or all blocks of a world (getLoadedChunks(), world.getEntities(), getLivingEntities()) in an event handler or a repeating task. Work near players instead: player.getNearbyEntities(r, r, r) / location.getNearbyEntities with r = NxPerf.radius(<configured radius>) (at most 48 blocks), only in loaded chunks (world.isChunkLoaded(x, z)); never load or generate chunks to do your work.
- Per tick: at most perf.max-work-per-tick block changes / entity updates / chunk operations (default 64). Put batches into a queue: Queue<T> q = NxPerf.queue("<feature>", item -> { ... }); q.offer(item) (false when full: drop it). Or check if (!NxPerf.take("<feature>")) break; inside a loop.
- Spawning: before every spawn call if (!NxPerf.spawnAllowed("<feature>", location.getChunk())) skip it (at most 5 per second, 20 living mobs per chunk by default). Copies/clones of mobs never spawn more copies (track a generation counter, at most 3).
- Explosions: if (!NxPerf.rate("explosions", 5)) skip; power at most 4; no explosion that triggers another without a generation limit.
- Repeating work only through NxPerf.timer("<feature>", delayTicks, periodTicks, () -> { ... }) (not runTaskTimer), period 10 ticks or more unless the request needs a smoother effect (then very little work per run). Nothing heavy every tick.
- Never react to a change your own code made (no feedback loops through your own events): wrap re-entrant work in if (!NxPerf.enter("<key>")) return; try { ... } finally { NxPerf.exit("<key>"); }. No recursion through events, no while(true).
- Remembered data is bounded: lists/maps that grow with play (logs, queues, remembered changes) have a configured maximum (drop the oldest), stored per chunk/player key so one lookup never scans everything.
- Every limit is a config.yml setting with a SAFE default (radius 16, per-tick 64 or less, mob copying off) and is clamped when read (Math.min(value, hard max)). If the request asks for unbounded work ("every chunk", "infinite", "all entities every tick"), build the bounded version with these limits and say so in modbuilder.json "limitations".
