// Cyrus limits POLICY (owner rule 2026-10-12, D-56 "warn, don't block"): what may stay a hard boundary and what must
// become a warning. Every limit Cyrus enforces is classified in ./inventory.ts against this list; a new hard limit
// needs a HARD_KEEP reason or it is a soft (recommended) range with a consequence line. Pure data, client-safe.

export type HardKeepReason = "security" | "legal" | "money" | "crash" | "api-ceiling" | "service-capacity";

export const HARD_KEEP: readonly { reason: HardKeepReason; title: string; covers: string; examples: string[] }[] = [
  {
    reason: "security", title: "Security and sandbox",
    covers: "malware, sandbox escape, injection, obfuscation, the scanner rules, the network policy, identifier formats that end up in code or commands",
    examples: ["scanner and import rules", "data pack command allow-list and denied commands", "mod networking host allow-list, secrets and egress caps", "key / id / sound-key / package regexes", "text with control characters or section signs"],
  },
  {
    reason: "legal", title: "Legal, licence and safety rules",
    covers: "asset licences, the sound-library clearance switch, game-derived material, abuse intent (\"lag machine\", \"crash the server\")",
    examples: ["CYRUS_SOUND_LIBRARY_CLEARED gate", "CC0-only community library", "perf-risk lag-intent refusal"],
  },
  {
    reason: "money", title: "Money and credit integrity",
    covers: "tokens, plan gates, spend caps, prices that would go free or negative",
    examples: ["insufficient tokens / daily cap / model lock", "plan tier gates for studios and assets", "platform and user spend caps", "shop prices: at least 1 item, 1 XP level or 0.01 money"],
  },
  {
    reason: "crash", title: "Values that crash or corrupt",
    covers: "type overflow, negative counts or sizes, division by zero, a zero period, malformed identifiers, structure the game refuses to load",
    examples: ["int settings stay inside Java int", "counts, sizes, radii and durations are never negative", "periods and regen times are at least 1 tick", "worldgen height / noise / spacing rules", "config_version 1..1,000,000"],
  },
  {
    reason: "api-ceiling", title: "Real game or third-party API ceilings",
    covers: "limits the game or an upstream API enforces itself; going past them does nothing or breaks",
    examples: ["sound pitch 0.5-2", "potion amplifier 0-255", "stack size 1-99", "max health attribute 1024, armor 30", "inventory rows 1-6 and slots 0-53", "time of day 0-23999", "probabilities and fractions 0-1", "player velocity 4 blocks per tick", "resource-pack formats per version"],
  },
  {
    reason: "service-capacity", title: "Our service's own capacity (not the user's server)",
    covers: "request and upload sizes, zip-bomb guards, parser limits, build rate limits and concurrency, array counts in untrusted JSON",
    examples: ["prompt 4,000 characters", "upload / body / glTF / zip size caps", "3 builds a minute, 2 in flight", "spec byte sizes", "edits per call"],
  },
];

/** The one-paragraph policy shown in docs and reused by the Prompt Coach. */
export const LIMIT_POLICY = [
  "Cyrus does not hard-cap what users choose. Every gameplay, balance, size or performance number has a RECOMMENDED range;",
  "outside it Cyrus shows a warning with the likely consequence (lag, memory, TPS, balance) and lets the user apply it.",
  "Far outside it (the danger tier) the editor asks for one confirm. Generated plugins honour saved values: they log a",
  "warning once per key and clamp only to crash-safe bounds. The performance safety net (NxPerf) stays, with every cap",
  "a configurable default; perf.auto-disable: false turns the automatic pause off for that server.",
].join(" ");

export type LimitTierInfo = { tier: "info" | "warn" | "danger"; look: string; action: string };
export const TIER_UI: readonly LimitTierInfo[] = [
  { tier: "info", look: "a plain note under the setting", action: "nothing to confirm" },
  { tier: "warn", look: "an amber banner with the consequence line", action: "Apply / Save work as usual" },
  { tier: "danger", look: "a red outline and banner", action: "one confirm before Apply / Save" },
];

