rep("""// Cyrus Config Studio: VALUE checking. Coercion from editor/YAML input, hard-limit checks (strict: refuse; clamp: what
// the generated runtime loader does), balance warnings (the `safe` range), defaults, display formatting. Pure.
import { CONFIG_LIMITS, cellError, numeric, paramByKey, shapeError, type ConfigParam, type ConfigSpec, type ConfigValue, type ConfigValues, type ScalarValue } from "./spec";

export type ValueMode = "strict" | "clamp";
export type ValueIssue = { key: string; code: string; message: string };""","""// Cyrus Config Studio: VALUE checking. Coercion from editor/YAML input, limit checks, defaults, display formatting.
// Owner rule 2026-10-12 (D-56, "warn, don't block"): a number outside its RECOMMENDED range (min/max) is a WARNING
// (tier warn, or danger past warnMin/warnMax) with a consequence line, never an error; only the crash-safe bounds
// (softRangeOf: hardMin/hardMax, Java int, no negative counts) are refused (strict) or clamped (clamp = what the
// generated runtime loader does). Balance notes (the `safe` band) are tier info. Pure.
import { CONFIG_LIMITS, cellError, numeric, paramByKey, shapeError, softRangeOf, type CellSpec, type ConfigParam, type ConfigSpec, type ConfigValue, type ConfigValues, type ScalarValue } from "./spec";
import { classify, clampHard, TIER_RANK, type LimitTier } from "../limits/range";
import { inferImpact } from "../limits/consequence";

export type ValueMode = "strict" | "clamp";
/** tier/consequence are set on limit warnings (info: balance note, warn: outside recommended, danger: confirm first). */
export type ValueIssue = { key: string; code: string; message: string; tier?: LimitTier; consequence?: string };""")
rep("""/** Balance warnings: a value outside `safe` (never an error). */
export function balanceWarnings(p: ConfigParam, v: ConfigValue): ValueIssue[] {
  if (!p.safe || !numeric(p)) return [];
  const vals = p.type === "range" ? (v as number[]) : [v as number];
  const u = p.unit ? ` ${p.unit}` : "";
  const out: ValueIssue[] = [];
  const lo = p.safe.min, hi = p.safe.max;
  if (lo !== undefined && vals.some((x) => x < lo)) out.push({ key: p.key, code: "below_balanced", message: `${p.label} ${fmt(p, v)} is below the balanced range (${lo}${u} or more)${p.safe.note ? `: ${p.safe.note}` : ""}` });
  if (hi !== undefined && vals.some((x) => x > hi)) out.push({ key: p.key, code: "above_balanced", message: `${p.label} ${fmt(p, v)} is above the balanced range (${hi}${u} or less)${p.safe.note ? `: ${p.safe.note}` : ""}` });
  return out;
}
""","""const CODE: Record<"info" | "warn" | "danger", Record<"below" | "above", string>> = {
  info: { below: "below_balanced", above: "above_balanced" },
  warn: { below: "below_recommended", above: "above_recommended" },
  danger: { below: "far_below_recommended", above: "far_above_recommended" },
};

/**
 * Limit warnings for a value that passed the crash-safe check: at most one per side, the worst tier first. info =
 * outside the balanced band, warn = outside the recommended range, danger = past warnMin/warnMax (confirm first).
 */
export function rangeWarnings(p: ConfigParam, v: ConfigValue): ValueIssue[] {
  if (!numeric(p)) return [];
  const vals = p.type === "range" ? (v as number[]) : [v as number];
  if (!Array.isArray(vals) || vals.some((x) => typeof x !== "number")) return [];
  const r = softRangeOf(p);
  const impact = p.impact ?? inferImpact(p.key, p.label, p.unit ?? (p.type === "duration" ? "s" : ""));
  const u = p.type === "duration" ? (p.durationUnit === "ticks" ? "ticks" : p.durationUnit ?? "s") : p.unit;
  const best = new Map<"below" | "above", ValueIssue>();
  for (const x of vals) {
    const c = classify(x, r, { label: p.label, unit: u, impact, balancedNote: p.safe?.note });
    if (c.tier === "ok" || c.tier === "invalid" || !c.side) continue;
    const prev = best.get(c.side);
    if (prev && TIER_RANK[prev.tier!] >= TIER_RANK[c.tier]) continue;
