 */
public final class NxPerfCore {
  public static final String VERSION = "nxperf-1";""",""" * and the lag judge that decides when the plugin's heavy features must pause.
 *
 * nxperf-2 (2026-10-12, owner rule "warn, don't block"): every perf.* value is a configurable DEFAULT. clampAll() only
 * enforces crash-safe bounds (no zero or negative budgets, no overflow); values above the recommended maxima are kept
 * and reported by warnings(). Budgets are no longer all-or-nothing: a request bigger than the whole per-tick budget
 * runs on a fresh tick and the overdraft is paid back over the following ticks, and grant() hands out partial units.
 */
public final class NxPerfCore {
  public static final String VERSION = "nxperf-2";""")
rep("""  /** The perf.* config section, clamped to safe ranges (a config can tighten the limits, never remove them). */
  public static final class Settings {
    public boolean autoDisable = true;
    public double tpsFloor = 15.0;
    public int windowSeconds = 10;
    public int maxWorkPerTick = 64;
    public double maxMsPerTick = 25.0;
    public double share = 0.25;
    public double freezeMs = 2000.0;
    public int maxEntitiesPerSecond = 5;
    public int maxEntitiesPerChunk = 20;
    public int maxQueue = 2000;
    public int maxRadius = 48;
    /** Entities this plugin's own code may spawn per second (listeners, NxPerf timers/queues); above it spawns are cancelled. */
    public int maxSpawnsPerSecond = 50;
    public int statusLogSeconds = 300;

    public Settings clampAll() {
      tpsFloor = clamp(tpsFloor, 5.0, 19.5);
      windowSeconds = clampInt(windowSeconds, 3, 120);
      maxWorkPerTick = clampInt(maxWorkPerTick, 1, 256);
      maxMsPerTick = clamp(maxMsPerTick, 2.0, 45.0);
      share = clamp(share, 0.05, 0.9);
      freezeMs = clamp(freezeMs, 250.0, 10000.0);
      maxEntitiesPerSecond = clampInt(maxEntitiesPerSecond, 1, 50);
      maxEntitiesPerChunk = clampInt(maxEntitiesPerChunk, 1, 100);
      maxQueue = clampInt(maxQueue, 10, 20000);
      maxRadius = clampInt(maxRadius, 1, 64);
      maxSpawnsPerSecond = clampInt(maxSpawnsPerSecond, 1, 500);
      statusLogSeconds = clampInt(statusLogSeconds, 30, 3600);
      return this;
    }
  }""","""  /** Recommended maxima of the perf.* values: above them NxPerf warns (once) and still applies the value. */
  public static final int REC_WORK_PER_TICK = 256, REC_ENTITIES_PER_SECOND = 50, REC_ENTITIES_PER_CHUNK = 100, REC_QUEUE = 20000,
      REC_RADIUS = 64, REC_SPAWNS_PER_SECOND = 500;
  public static final double REC_MS_PER_TICK = 45.0, REC_TPS_FLOOR_MIN = 5.0, REC_SHARE_MAX = 0.9;

  /**
   * The perf.* config section. Every value is a DEFAULT the server owner may change; clampAll() keeps only the
   * crash-safe bounds (a budget of at least 1, a window the judge can hold, no overflow). warnings() lists the values
   * outside the recommended range with their likely consequence.
   */
  public static final class Settings {
    /** false = never pause automatically (the owner's choice; the warnings and perf status still report lag). */
    public boolean autoDisable = true;
    public double tpsFloor = 15.0;
    public int windowSeconds = 10;
    public int maxWorkPerTick = 64;
    public double maxMsPerTick = 25.0;
    public double share = 0.25;
    public double freezeMs = 2000.0;
    public int maxEntitiesPerSecond = 5;
    public int maxEntitiesPerChunk = 20;
    public int maxQueue = 2000;
    /** 0 = no cap (the plugin's own configured radius is used as saved); > 0 = this server's own cap in blocks. */
    public int maxRadius = 0;
    /** Entities this plugin's own code may spawn per second (listeners, NxPerf timers/queues); above it spawns are cancelled. */
    public int maxSpawnsPerSecond = 50;
    public int statusLogSeconds = 300;

    public Settings clampAll() {
      tpsFloor = clamp(tpsFloor, 0.0, 20.0);
      windowSeconds = clampInt(windowSeconds, 1, 120);
      maxWorkPerTick = clampInt(maxWorkPerTick, 1, 1_000_000);
      maxMsPerTick = clamp(maxMsPerTick, 0.5, 10_000.0);
      share = clamp(share, 0.0, 1.0);
      freezeMs = clamp(freezeMs, 50.0, 600_000.0);
      maxEntitiesPerSecond = clampInt(maxEntitiesPerSecond, 1, 1_000_000);
      maxEntitiesPerChunk = clampInt(maxEntitiesPerChunk, 1, 1_000_000);
      maxQueue = clampInt(maxQueue, 1, 10_000_000);
      maxRadius = clampInt(maxRadius, 0, 1_000_000);
      maxSpawnsPerSecond = clampInt(maxSpawnsPerSecond, 1, 1_000_000);
      statusLogSeconds = clampInt(statusLogSeconds, 10, 86_400);
      return this;
    }

    /** Values outside the recommended range, each with its likely consequence (applied anyway). */
    public java.util.List<String> warnings() {
      java.util.List<String> w = new java.util.ArrayList<>();
      if (!autoDisable) w.add("perf.auto-disable=false: this mod never pauses itself; if it lags the server, the lag stays until someone acts (perf status still reports it)");
      if (tpsFloor < REC_TPS_FLOOR_MIN) w.add("perf.tps-floor=" + fmt(tpsFloor) + " is below the recommended " + fmt(REC_TPS_FLOOR_MIN) + ": the safety net only reacts to a nearly frozen server");
      if (maxWorkPerTick > REC_WORK_PER_TICK) w.add("perf.max-work-per-tick=" + maxWorkPerTick + " is above the recommended " + REC_WORK_PER_TICK + ": more work every tick, expect lower TPS on busy servers");
      if (maxMsPerTick > REC_MS_PER_TICK) w.add("perf.max-ms-per-tick=" + fmt(maxMsPerTick) + " is above the recommended " + fmt(REC_MS_PER_TICK) + ": a tick has 50 ms for everything, so this mod may use all of it");
