      if (maxEntitiesPerChunk > REC_ENTITIES_PER_CHUNK) w.add("perf.max-entities-per-chunk=" + maxEntitiesPerChunk + " is above the recommended " + REC_ENTITIES_PER_CHUNK + ": crowded chunks lag players nearby");
