      if (maxSpawnsPerSecond > REC_SPAWNS_PER_SECOND) w.add("perf.max-spawns-per-second=" + maxSpawnsPerSecond + " is above the recommended " + REC_SPAWNS_PER_SECOND + ": a runaway spawner is only stopped much later");
      return w;
    }
  }""")
rep("""  /** Work units per server tick; resets when the tick number changes. */
  public static final class Budget {
    public final String name;
    private int perTick;
    private long tick = Long.MIN_VALUE;
    private int used;
    private long denied;
    private long total;

    public Budget(String name, int perTick) {
      this.name = name;
      this.perTick = Math.max(1, perTick);
    }

    public synchronized boolean take(long nowTick, int n) {
      if (nowTick != tick) {
        tick = nowTick;
        used = 0;
      }
      if (n <= 0) return true;
      if ((long) used + n > perTick) {
        denied++;
        return false;
      }
      used += n;
      total += n;
      return true;
