// Cyrus motion presets: typed, ranged parameters (the "few knobs" the AI or a human sets). Pure.
export type ParamDef =
  | { name: string; type: "number"; min: number; max: number; default: number; step?: number; label: string; unit?: string }
  | { name: string; type: "enum"; options: readonly string[]; default: string; label: string }
  | { name: string; type: "sound"; default: string; label: string };
export type ParamValues = Record<string, number | string>;
export type ParamIssue = { param: string; message: string };

const SOUND_RE = /^(sound:[a-z0-9][a-z0-9_.-]{1,79}|[a-z0-9_.-]+:[a-z0-9_.-]+(\/[a-z0-9_.-]+)*)$/;

/** Fill defaults and CLAMP every number into its range (never throws); report what was clamped or refused. */
export function resolveParams(defs: readonly ParamDef[], given: Record<string, unknown> = {}): { values: ParamValues; issues: ParamIssue[] } {
  const values: ParamValues = {};
  const issues: ParamIssue[] = [];
  for (const k of Object.keys(given)) if (!defs.some((d) => d.name === k)) issues.push({ param: k, message: `unknown parameter ${k}` });
  for (const d of defs) {
    const v = given[d.name];
    if (v === undefined) { values[d.name] = d.default; continue; }
    if (d.type === "number") {
      const n = typeof v === "number" && Number.isFinite(v) ? v : NaN;
      if (Number.isNaN(n)) { issues.push({ param: d.name, message: `${d.name} must be a number` }); values[d.name] = d.default; continue; }
      const c = Math.min(d.max, Math.max(d.min, n));
      if (c !== n) issues.push({ param: d.name, message: `${d.name} ${n} clamped to ${c} (range ${d.min}..${d.max})` });
      values[d.name] = d.step ? Math.round(c / d.step) * d.step : c;
    } else if (d.type === "enum") {
      if (typeof v !== "string" || !d.options.includes(v)) { issues.push({ param: d.name, message: `${d.name} must be one of ${d.options.join(", ")}` }); values[d.name] = d.default; }
      else values[d.name] = v;
    } else {
      if (typeof v !== "string" || !SOUND_RE.test(v)) { issues.push({ param: d.name, message: `${d.name} must be sound:<id> or a namespaced sound key` }); values[d.name] = d.default; }
      else values[d.name] = v;
    }
  }
  return { values, issues };
}
