import type { Param } from "../compile";
import { fileKind, type DesignFile, type FileKind } from "./edit";

export type StudioCtx = { version: string; namespace: string; pluginName: string; assets?: GpContext["assets"]; configVersion?: number };
export type FileReport = { id: string; kind: FileKind; ok: boolean; errors: GpIssue[]; warnings: GpIssue[] };
export type AbilityBudgetView = { item: string; ability: string; actions: number; entities: number; tasks: number; particles: number; projectiles: number; nodes: number; depth: number };
export type CheckRow = { id: string; status: "pass" | "warn" | "fail" | "not_run"; items: string[] };
export type CompileSummary =
  | { ok: true; hash: string; configVersion: number; files: number; java: number; command: string; mainClass: string; javacVerified: boolean; configYml: string }
  | { ok: false; errors: GpIssue[] };
export type DiffSummary = { configOnly: boolean; javaChanged: string[]; changed: { path: string; status: string }[]; unchanged: number; configVersion: { from: number; to: number }; readmeChanged: boolean };
export type Analysis = {
  ok: boolean;
  /** the validators could run the cross-file checks (namespace + version known) */
  ranCross: boolean;
  files: FileReport[];
  /** mod-level errors that name no file */
  modErrors: GpIssue[];
  budgets: AbilityBudgetView[];
  /** bosses: the static worst case per attack (the item BUDGET + summons) */
  bossBudgets: { boss: string; attack: string; actions: number; entities: number; tasks: number; particles: number; projectiles: number; summons: number; depth: number }[];
  /** motion designs: Minecraft fit (caps, what the lowering leaves out, the lowered program's size) */
  motions: { id: string; ok: boolean; stats: MotionStats | null; caps: MotionCaps; issues: MotionIssue[]; dropped: { path: string; reason: string }[]; program: { parts: number; clips: number; segments: number; cues: number; snaps: number } | null }[];
  /** the item validator's own check rows (DESIGN_CHECKS) per item id */
  itemChecks: Record<string, CheckRow[]>;
  /** gameplay check rows per kind: pass / warn / fail by validator code (codes listed in GAMEPLAY_ROWS) */
export function analyzeMod(files: readonly DesignFile[], ctx: StudioCtx, saved?: readonly DesignFile[]): Analysis {
  const v = validateGameplay([...files], { version: ctx.version, namespace: ctx.namespace, ...(ctx.assets ? { assets: ctx.assets } : {}) });
  const ranCross = !!v.features;
  const reports: FileReport[] = v.files.map((f, i) => ({ id: f.id, kind: fileKind(files[i]), ok: f.ok, errors: f.errors, warnings: f.warnings }));
  const itemIdx = files.map((f, i) => (fileKind(f) === "item" ? i : -1)).filter((i) => i >= 0);
  const itemChecks: Record<string, CheckRow[]> = {};
  v.itemResults.forEach((r, j) => { const id = files[itemIdx[j]]?.id; if (id) itemChecks[id] = r.checks.map((c: DzCheck) => ({ id: c.id, status: c.status, items: c.items })); });
  for (const i of itemIdx) if (!itemChecks[files[i].id]) itemChecks[files[i].id] = DESIGN_CHECKS.map((id) => ({ id, status: "not_run" as const, items: [] }));
  const items = files.filter((f) => fileKind(f) === "item") as ItemDesign[];
  const byKind = <T,>(k: FileKind) => files.filter((f) => fileKind(f) === k) as unknown as T[];
  const params = safe(() => modParams(items, byKind("menu"), byKind("quest"), byKind("boss"), byKind("encounter"), byKind("hud")), [] as Param[]);
  let compile: CompileSummary = { ok: false, errors: [] };
  let diff: DiffSummary | null = null;
  const base = saved ? compileOf(saved, ctx) : null;
  const work = compileOf(files, ctx, base && base.ok ? base.files.find((f) => f.path === CONFIG)?.content : undefined);
  if (work.ok) {
    compile = { ok: true, hash: work.hash, configVersion: work.configVersion, files: work.files.length, java: work.files.filter((f) => f.path.endsWith(".java")).length, command: work.command, mainClass: work.mainClass, javacVerified: work.javacVerified, configYml: work.files.find((f) => f.path === CONFIG)?.content ?? "" };
    if (base && base.ok) {
      const d = diffCompiled(base, work);
      diff = { configOnly: d.javaChanged.length === 0 && d.changed.every((c) => c.path === CONFIG || !c.path.endsWith(".java")) && !d.changed.some((c) => c.path.endsWith("plugin.yml")), javaChanged: d.javaChanged, changed: d.changed.map((c) => ({ path: c.path, status: c.status })), unchanged: d.unchanged, configVersion: { from: base.configVersion, to: work.configVersion }, readmeChanged: d.readmeChanged };
    }
  } else compile = { ok: false, errors: work.errors };
  return {
    ok: v.ok, ranCross, files: reports, modErrors: v.errors.filter((e) => !e.file), budgets: budgetsOf(files), bossBudgets: bossBudgets(files), motions: motionReports(files, ctx), itemChecks,
    gameplayChecks: { menu: rowsFor("menu", v, ranCross), quest: rowsFor("quest", v, ranCross), boss: rowsFor("boss", v, ranCross) },
    params, progressChars: v.progressChars, compile, diff,
  };
}

