type Hints = { min?: number; max?: number; options?: string[]; unit?: string; durationUnit?: "ticks" | "s" | "ms"; percent?: boolean };
/** Limits, options and units a comment states. */
export function commentHints(text: string): Hints {
  const h: Hints = {};
  const t = text.toLowerCase();
  const n = "(-?\\d+(?:\\.\\d+)?)";
  const range = new RegExp(`(?:between|from|range:?)\\s*${n}\\s*(?:and|to|-|–)\\s*${n}`).exec(t) ?? new RegExp(`\\(\\s*${n}\\s*(?:-|to|–|\\.\\.)\\s*${n}\\s*[a-z%]*\\s*\\)`).exec(t) ?? new RegExp(`(?:^|\\s)${n}\\s*(?:to|–|\\.\\.)\\s*${n}(?:\\s|$|[,.;])`).exec(t);
  if (range) { const a = Number(range[1]), b = Number(range[2]); if (a <= b) { h.min = a; h.max = b; } }
  const mn = new RegExp(`(?:min(?:imum)?|at least)\\s*[:=]?\\s*${n}`).exec(t);
  const mx = new RegExp(`(?:max(?:imum)?|at most|up to)\\s*[:=]?\\s*${n}`).exec(t);
  if (mn && h.min === undefined) h.min = Number(mn[1]);
  if (mx && h.max === undefined) h.max = Number(mx[1]);
  const opt = /(?:one of|options?|values?|can be|either)\s*[:=]?\s*([a-z0-9_\-|, ]+?(?:\s+or\s+[a-z0-9_-]+)?)(?:[.;)]|$)/i.exec(text) ?? /\(([a-z0-9_-]+(?:\s*\|\s*[a-z0-9_-]+)+)\)/i.exec(text);
  if (opt) {
    const list = opt[1].split(/\s*(?:\||,|\bor\b)\s*/i).map((x) => x.trim()).filter((x) => /^[A-Za-z0-9_-]{1,32}$/.test(x));
    if (list.length >= 2 && list.length <= CONFIG_LIMITS.options) h.options = [...new Set(list)];
  }
  if (/\bin ticks\b|\(ticks\b|\bticks\)|20 ticks|ticks?,/.test(t)) h.durationUnit = "ticks";
  else if (/\bin (milli ?seconds|ms)\b|\(ms\)/.test(t)) h.durationUnit = "ms";

