// Owner rule 2026-10-12 (D-56, "warn, don't block"): Cyrus never hard-caps what a user chooses. This suite covers the
// shared limits model (lib/cyrus/limits), the REAL trigger case (ChunkMirror: "Mirror radius 20 chunks is outside the
// allowed 1-8 chunks" was refused by the Config Studio and the generated plugin clamped it at load), the generated Java
// loader honouring a value beyond the old cap (javac + java on node-2 when a JDK is there: Test-Flight style, no
// server), and the NxPerf budget carry-over (the radius-4 = 80 units vs 64 per tick bug that never ran).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { existsSync, mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { classify, consequenceLine, dangerBounds, hardCaps, DANGER_FACTOR, INT32 } from "../lib/cyrus/limits/range";
import { inferImpact } from "../lib/cyrus/limits/consequence";
import { HARD_KEEP, LIMIT_POLICY } from "../lib/cyrus/limits/policy";
import { LIMIT_INVENTORY, inventoryByVerdict } from "../lib/cyrus/limits/inventory";
import { planWarnings, PLAN_WARNING_COPY } from "../lib/cyrus/limits/plan";
import { validateConfigSpec, type ConfigSpec, type ConfigSpecInput } from "../lib/cyrus/config/spec";
import { checkValue, checkValues } from "../lib/cyrus/config/values";
import { readValues, renderConfigYml, writeValues } from "../lib/cyrus/config/file";
import { javaSettingsClass } from "../lib/cyrus/config/exporters";

const ROOT = path.resolve(__dirname, "..");
const JDK = process.env.CYRUS_JDK ?? "/tank/nxeon-build/tmp/testflight/jdk/21";
const HAVE_JDK = existsSync(path.join(JDK, "bin", "javac"));

/** The ChunkMirror settings as the AI declared them (assets/config/schema.json), with the consequence it knows. */
const CHUNKMIRROR: ConfigSpecInput = {
  schemaVersion: 1, reload: { command: "/chunkmirror reload" },
  groups: [{ id: "mirror", label: "Mirroring" }],
  params: [
    {
      key: "chunk-mirror.mirror-radius", group: "mirror", type: "int", label: "Mirror radius", unit: "chunks", default: 4, min: 1, max: 8, applies: "reload",
      impact: { model: "square", factor: 4, unit: "mirrored changes per block", note: "expect lag on most servers; the TPS safety net can pause it" },
    },
    { key: "chunk-mirror.per-tick", group: "mirror", type: "int", label: "Changes per tick", default: 64, min: 1, max: 256, applies: "reload" },
    { key: "chunk-mirror.mobs", group: "mirror", type: "bool", label: "Mirror mobs", default: false, applies: "reload" },
  ],
};
const spec = (): ConfigSpec => { const r = validateConfigSpec(CHUNKMIRROR); assert.ok(r.ok, JSON.stringify(r)); return (r as { spec: ConfigSpec }).spec; };

describe("limits model (lib/cyrus/limits)", () => {
  it("tiers: ok / info (balanced band) / warn (outside recommended) / danger (past warn or 4x) / invalid (crash-safe)", () => {
    const r = { recommendedMin: 1, recommendedMax: 8, hardMin: 0, balancedMin: 2, balancedMax: 6 };
    assert.equal(classify(4, r).tier, "ok");
    assert.equal(classify(7, r).tier, "info");
    assert.equal(classify(20, r).tier, "warn");
    assert.equal(classify(8 * DANGER_FACTOR + 1, r).tier, "danger");
    assert.equal(classify(-1, r).tier, "invalid");
    assert.equal(classify(Number.NaN, r).tier, "invalid");
    assert.deepEqual(dangerBounds({ recommendedMax: 8, warnMax: 12 }), { min: undefined, max: 12 });
    assert.equal(classify(13, { recommendedMin: 1, recommendedMax: 8, warnMax: 12 }).tier, "danger");
    assert.equal(classify(0.5, { recommendedMin: 1, recommendedMax: 8, warnMin: 0.75 }).tier, "danger");
  });
  it("the consequence line counts the cost: 20 chunks = 1,600 mirrored changes per block", () => {
    assert.equal(consequenceLine(20, "chunks", { model: "square", factor: 4, unit: "mirrored changes per block", note: "expect lag on most servers; the TPS safety net can pause it" }),
      "20 chunks = 1,600 mirrored changes per block; expect lag on most servers; the TPS safety net can pause it");
    assert.match(consequenceLine(2, "ticks", inferImpact("ability.period_ticks", "Interval", "ticks"))!, /2 ticks = 10 runs per second/);
    assert.match(inferImpact("mirror.radius-chunks", "Radius", "chunks")!.note!, /square of the radius/);
    assert.equal(inferImpact("mob.name", "Name"), undefined);
  });
  it("hardCaps: soft caps widen to crash-safe bounds, kept caps stay exactly", () => {
    const h = hardCaps({ a: [0, 10], b: [1, 5], c: [-3, 3], d: [0, 1] } as const, { d: [0, 1] });
    assert.deepEqual(h, { a: [0, 1e9], b: [1, 1e9], c: [-1e9, 1e9], d: [0, 1] });
  });
  it("policy: the HARD-KEEP list names its six reasons and the policy text says warn, don't block", () => {
    assert.deepEqual(HARD_KEEP.map((h) => h.reason), ["security", "legal", "money", "crash", "api-ceiling", "service-capacity"]);
    assert.match(LIMIT_POLICY, /does not hard-cap what users choose/);
    assert.match(LIMIT_POLICY, /perf\.auto-disable: false/);
  });
  it("the inventory classifies every limit with a reason; soft rows say what they became", () => {
    assert.ok(LIMIT_INVENTORY.length >= 40, `${LIMIT_INVENTORY.length} rows`);
    for (const r of LIMIT_INVENTORY) {
      assert.ok(r.where && r.limit && r.reason, JSON.stringify(r));
      if (r.verdict === "hard-keep") assert.ok(HARD_KEEP.some((h) => h.reason === r.keep), `${r.where}: a HARD-KEEP row needs a HARD_KEEP reason`);
      if (r.verdict === "softened") assert.ok(r.now, `${r.where}: a softened row says what it is now`);
    }
    const by = inventoryByVerdict();
    assert.ok(by.softened.length > 0 && by["hard-keep"].length > 0);
    assert.ok(by.softened.some((r) => /ChunkMirror|Config Studio/.test(r.where + r.limit)));
  });
});

