// Cyrus limits: WARNINGS BEFORE YOU SPEND (owner rule 2026-10-12, D-56). The plan screen used to say "blocked" for
// things that are not hard boundaries (a lane that is only switched off, a request that implies heavy work). This
// module turns them into warnings with the likely consequence (lag / cost / time / what gets left out) and keeps the
// word "blocked" for the real boundaries only (plan tier = money, a game version where the API does not exist).
// Pure data + one function, so the plan sheet (components/cyrus/prompt/PlanSheet.tsx) and the Prompt Coach
// (feature/cyrus-prompt-coach) can both read it. Deterministic, no model, no I/O.
import { classifyPerfRisk } from "../safety/perf-risk";
import { fmtCount } from "./range";

export type PlanWarningKind = "lag" | "cost" | "time" | "unavailable" | "plan" | "version";
export type PlanWarning = {
  kind: PlanWarningKind;
  title: string;
  /** One plain line: what is likely to happen if the user goes ahead. */
  consequence: string;
  /** true only for real boundaries (plan tier, a version without the API): the plan screen shows them as not included. */
  hard: boolean;
  /** Where it came from (a perf-risk rule id, a lane id), for tests and analytics. */
  source: string;
};

/** A planner lane as the plan screen gets it (lib/cyrus/planner/decide.ts). */
export type PlanLaneInput = { id: string; label: string; state: string; cause?: string; warning?: string };

export const PLAN_WARNING_COPY = {
  heading: "Warnings before you spend",
  intro: "Nothing here stops the build. These are the likely consequences; Cyrus ships safe defaults you can raise later in the Config Studio.",
  hardHeading: "Not included in this build",
  continue: "Build with these warnings",
} as const;

const LANE_CONSEQUENCE: Record<string, string> = {
  flag: "this part is switched off in Cyrus right now, so the mod is built without it; you can add it in a later change when it is on",
  game: "this game cannot use that part yet, so the mod is built without it",
  version: "the chosen game version has no support for it (the game itself lacks the feature), so the mod is built without it; pick a newer version to include it",
  tier: "your plan does not include it, so the mod is built without it",
};

/** Heavy-work consequence for an explicit chunk radius in the request ("within 20 chunks"). */
function chunkRadiusLine(text: string): { r: number; line: string } | null {
  const m = /\b(?:within|radius(?: of)?|up to|around)\s+(\d{1,4})\s*chunks?\b|\b(\d{1,4})\s*chunks?\s+(?:radius|around|away)\b/i.exec(text);
  const r = m ? Number(m[1] ?? m[2]) : NaN;
  if (!Number.isFinite(r) || r <= 8) return null;
  return { r, line: `${r} chunks = ${fmtCount(4 * r * r)} chunks touched around each change; expect lag on most servers (the TPS safety net can pause it), and more build time to make it safe` };
}

/**
 * Warnings for a request + its planned lanes. Soft (hard: false) for everything that is a choice; hard only for the
 * plan tier and a version without the API. Never returns the word "blocked".
 */
export function planWarnings(input: { text: string; lanes: readonly PlanLaneInput[]; config?: Record<string, unknown> | null }): PlanWarning[] {
  const out: PlanWarning[] = [];
  const risk = classifyPerfRisk({ text: input.text, config: input.config ?? null });
  for (const f of risk.findings) {
    if (f.id === "lag-intent") { out.push({ kind: "lag", title: f.title, consequence: f.reason, hard: true, source: f.id }); continue; } // abuse intent stays a refusal
    out.push({ kind: "lag", title: f.title, consequence: `${f.reason} Cyrus builds a safe default (${f.safe.replace(/\.$/, "")}); you can raise it later or choose "Build anyway".`, hard: false, source: f.id });
  }
  const cr = chunkRadiusLine(input.text);
  if (cr) {
    const i = out.findIndex((w) => w.kind === "lag");
    if (i >= 0) out[i] = { ...out[i], consequence: `${cr.line}. ${out[i].consequence}` };
    else out.push({ kind: "lag", title: `Works over ${cr.r} chunks`, consequence: cr.line, hard: false, source: "chunk-radius" });
  }
  for (const l of input.lanes) {
    if (l.state !== "blocked") continue;
    const cause = l.cause ?? "flag";
    const hard = cause === "tier" || cause === "version";
    out.push({ kind: cause === "tier" ? "plan" : cause === "version" ? "version" : "unavailable", title: l.label, consequence: `${l.warning ? `${l.warning.replace(/\.$/, "")}: ` : ""}${LANE_CONSEQUENCE[cause] ?? LANE_CONSEQUENCE.flag}.`, hard, source: `lane:${l.id}` });
  }
  return out;
}

