// Cyrus limits INVENTORY (owner rule 2026-10-12, D-56 "warn, don't block"): every place a limit on a user's choice is
// enforced, classified HARD-KEEP (with a ./policy.ts reason) or SOFTEN, and what it is now. "soften-next" rows are soft
// by policy but still enforced as before in this branch (named honestly so nobody believes they are done). Docs:
// docs/cyrus/03-studios.md "Limits and warnings". Pure data.
import type { HardKeepReason } from "./policy";

export type LimitVerdict = "softened" | "hard-keep" | "soften-next";
export type LimitRow = {
  area: "config" | "designer" | "generated-java" | "perf" | "planner" | "datapack" | "worldgen" | "sound" | "texture" | "model" | "versions" | "service";
  where: string;
  limit: string;
  was: string;
  /** What it is after this branch (softened rows). */
  now?: string;
  verdict: LimitVerdict;
  keep?: HardKeepReason;
  reason: string;
};

const S = (area: LimitRow["area"], where: string, limit: string, was: string, now: string, reason: string): LimitRow => ({ area, where, limit, was, now, verdict: "softened", reason });
const K = (area: LimitRow["area"], where: string, limit: string, was: string, keep: HardKeepReason, reason: string): LimitRow => ({ area, where, limit, was, verdict: "hard-keep", keep, reason });
const N = (area: LimitRow["area"], where: string, limit: string, was: string, reason: string): LimitRow => ({ area, where, limit, was, verdict: "soften-next", reason });

export const LIMIT_INVENTORY: readonly LimitRow[] = [
  // ------------------------------------------------------------------ Config Studio
  S("config", "lib/cyrus/config/values.ts checkValue (Config Studio, ChunkMirror 'Mirror radius 20 chunks is outside the allowed 1-8')", "ConfigSpec min/max", "refused (strict) / clamped (loader)", "recommended range: warn tier (amber, applies), danger past warnMax or 4x max (one confirm); refused only past hardMin/hardMax", "a balance or performance choice the owner may make"),
  S("config", "lib/cyrus/config/spec.ts validateConfigSpec", "default / preset outside min/max", "error", "warning (default_outside_recommended / preset_outside_recommended); error only past the crash-safe bounds", "an AI-declared range is advice, not a boundary"),
  S("config", "lib/cyrus/config/spec.ts cellError + values.ts", "list item / table cell min/max", "refused / clamped", "warning; crash-safe bounds only", "same rule for cells"),
  S("config", "components/cyrus/studios/ConfigStudio.tsx", "slider + typed field + red 'outside the allowed' error", "Save disabled on an out-of-range value", "slider over the recommended range, any typed value; amber / red banner with the consequence line; danger needs one checkbox confirm", "warn, don't block"),
  S("config", "lib/cyrus/config/edit.ts planConfigEdit (the 'just type it' box)", "out-of-range value", "sent to the model", "applied, the summary says it is outside the recommended range", "no reason to spend tokens on a number"),
  K("config", "lib/cyrus/config/spec.ts softRangeOf", "derived crash-safe bounds", "-", "crash", "int settings stay inside Java int; a setting whose recommended range is not negative (counts, sizes, radii, durations) never goes below 0"),
  K("config", "lib/cyrus/config/templates.ts", "chance 0-1, armor 30, knockback resistance 0-1, scale 0.0625-16, weather chance 100%", "hard min/max", "api-ceiling", "the game's own attribute / probability limits"),
  K("config", "lib/cyrus/config/spec.ts CONFIG_LIMITS + key / id / file regexes", "400 params, 32 groups, text 1024, key format, file path", "zod", "service-capacity", "untrusted JSON size and path / injection safety"),
  // ------------------------------------------------------------------ generated Java (loaders)
  S("generated-java", "lib/cyrus/config/exporters.ts javaSettingsClass (CyrusSettings)", "num()/range() clamp to min/max", "clamped on load ('clamped k 20 -> 8')", "applied as saved; one warning per key and value; clamp only to crash-safe bounds", "generated plugins must honour saved values"),
  S("generated-java", "lib/cyrus/designer/components/java.ts DesignConfig.num/ticks/integer", "designer params clamp to CAPS", "clamped on /<mod> reload", "applied; one warning per key and value; clamp only to HARD_CAPS (5-argument loaders)", "same rule for designer mods"),
  S("generated-java", "lib/cyrus/designer/components/java.ts Budget", "per-activation budget 64 actions / 32 entities / 8 tasks / 512 particles / 3 projectiles", "final constants", "defaults read from config.yml general.budget.* (>= 1), warned above the default; still stops a firing when used up", "the runtime safety net stays, the number is the owner's"),
  S("generated-java", "lib/cyrus/designer/components/java.ts Tasks.timer", "repeating timer floor", "10 ticks (silent)", "1 tick (10 recommended; periodTicks below 10 warns)", "a silent clamp of a saved value"),
  S("generated-java", "lib/cyrus/designer/compile.ts + gameplay/compile.ts config.yml / README header", "'numbers are clamped to the range in their comment'", "-", "'recommended range; other values apply with a warning'", "honest copy"),
  K("generated-java", "lib/cyrus/designer/components/java.ts Effects", "velocity 4 blocks per tick", "clamp", "api-ceiling", "players are kicked for moving too fast above it"),
  K("generated-java", "lib/cyrus/designer/components/java.ts Marks.TOTAL / Tasks.LIVE; boss liveMinions / liveBosses / encounterMobs", "plugin-wide live totals", "constants", "crash", "unbounded live entities / tasks exhaust server memory; per-design counts above them are soft"),
  K("generated-java", "lib/cyrus/designer/gameplay/java.ts shop list clampInt / clampD", "list amount 1-64, item price 1-2304, money 0.01-1,000,000", "clamp", "money", "price floors protect the shop economy (free or negative purchases); the ceilings are soften-next below"),
  // ------------------------------------------------------------------ designers
  S("designer", "lib/cyrus/designer/spec.ts CAPS (39 caps) + zod capNum/capInt", "every numeric cap (cooldown, range, damage, particles, radius...)", "zod refuses outside CAPS", "CAPS = recommended (compile warning outside_recommended / far_outside_recommended); zod uses HARD_CAPS", "gameplay and balance choices"),
  S("designer", "lib/cyrus/designer/params.ts applyParameterEdits / gameplay/params.ts", "edit outside min-max", "error '<path>: v is outside lo-hi'", "applied with a warning; error only past the crash-safe bounds", "edit without regenerating must honour the value"),
  S("designer", "lib/cyrus/designer/spec.ts + boss/spec.ts static budget", "worst case over BUDGET per activation / attack", "error budget_*", "warning budget_* (the runtime Budget stops the firing; general.budget.* raises it)", "a static estimate, not a boundary"),
  S("designer", "lib/cyrus/designer/boss/spec.ts BOSS_CAPS", "arena radius, follow range, damage, waves, xp...", "zod refuses", "recommended; BOSS_HARD refuses", "boss tuning is the owner's"),
  S("designer", "lib/cyrus/designer/gameplay/spec.ts GAMEPLAY_CAPS", "objective counts, rewards, cooldowns, xp...", "zod refuses", "recommended; GAMEPLAY_HARD refuses", "quest / menu tuning is the owner's"),
  S("designer", "components/cyrus/designers/shared.tsx ParamField + ItemDesigner InlineField", "red field outside min-max", "error state", "amber (applies) outside the recommended range, red only past the crash-safe bound", "warn, don't block"),
  S("designer", "lib/cyrus/designer/simulate.ts value()", "simulator clamps like DesignConfig", "clamp to CAPS", "applies like DesignConfig, clamps to HARD_CAPS", "the simulator mirrors the loader"),
  K("designer", "lib/cyrus/designer/spec.ts HARD_CAPS keep list", "chance / health fraction / loot chance 0-1, time of day 0-23999, pitch 0.5-2, amplifier 0-255, give count 1-99, strength / vertical 0-4", "-", "api-ceiling", "the game's own limits"),
  K("designer", "lib/cyrus/designer/boss/spec.ts BOSS_HARD keep list", "health 1-1024, armor 30, attribute ceilings, summons 4, minions 16, encounter alive 24, drop count 99", "-", "api-ceiling", "vanilla attribute ranges; summon counts are tied to the plugin-wide live caps"),
  K("designer", "lib/cyrus/designer/gameplay/spec.ts GAMEPLAY_HARD keep list", "rows 1-6, slots 0-53, stacks 1-99, coordinates, click cooldown >= 2 ticks, economy price >= 0.01", "-", "api-ceiling", "inventory geometry, world border, click spam guard; price floor = money integrity"),
  K("designer", "lib/cyrus/designer/spec.ts DESIGN_LIMITS / boss & gameplay structure counts, nested query, projectile in loop, recursion", "array counts, spec bytes, unbounded fan-out shapes", "zod / errors", "service-capacity", "untrusted JSON size; nested fan-out has no static bound"),
  K("designer", "HUD_CAPS (hud/spec.ts)", "glyph height, ascent, space px, update ticks >= 10", "zod", "api-ceiling", "font renderer and resource-pack limits"),
  N("designer", "RUNTIME_CAPS text lengths (120 / 40 / 60 chars) + boss / gameplay Text(n)", "message / title lengths", "zod", "soft by policy (client wraps or cuts); widening needs the zod Text(...) helpers and DesignConfig.text together"),
  N("designer", "lib/cyrus/motion/presets/params.ts resolveParams + motion/java.ts instances 1-16, viewRange 0.1-2", "motion preset knobs", "clamped with a param_clamped warning", "soft by policy; the lowered MotionSpec must still pass its own checks, so each preset needs crash-safe bounds first"),
  N("designer", "gameplay/java.ts shop list ceilings, max_active_quests 1-5", "price ceiling 2304 items / 1,000,000 money, active quests 5", "clamp", "ceilings are soft by policy (floors stay); needs the shop simulator twin updated"),
  // ------------------------------------------------------------------ perf layer
  S("perf", "services/modbuilder/perf/src/NxPerfCore.java Settings.clampAll", "max-radius 64, max-work-per-tick 256, max-entities-per-second 50, max-queue 20000, max-spawns-per-second 500, tps-floor 5-19.5, max-ms 45", "clamped (a config could only tighten)", "configurable defaults; above the recommended maxima applied and logged once ([NxPerf] WARN ...); only crash-safe bounds clamp", "the server owner decides"),
  S("perf", "NxPerfCore.Budget.take", "per-tick budget all-or-nothing (radius 4 = 80 units vs 64 never ran)", "refused every tick", "a job bigger than the budget runs while budget is left and the overdraft is carried as debt; grant() hands out partial units", "a big radius must degrade, not silently never run"),
  S("perf", "NxPerf.radius()", "clamped to 1..max-radius (48)", "silent clamp", "the configured value as saved (>= 1); perf.max-radius 0 = no cap (default), > 0 = this server's own cap; warned above 64", "honour the saved value"),
