const PLAN_NAME: Record<string, string> = { saka: "Saka", all: "All models", katara: "Katara" };

export function decidePlan(i: DecideInput): ModPlan {
  const lanes: PlannedLane[] = LANES.map((lane) => {
    const n = i.needs.find((x) => x.lane === lane) ?? { lane, need: false, why: "", confidence: 0.5 };
    const t = i.toggles?.[lane];
    const wanted = t === undefined ? n.need : t;
    const capability = resolveLane(i.catalogue, lane, i.ctx);
    const meta = LANE_META[lane];
    const base = { ...n, need: wanted, label: meta.label, creates: meta.creates, capability, ...(t !== undefined && t !== n.need ? { toggled: true } : {}) };
    if (!wanted) return { ...base, state: "skip" as const, warning: null, blockedBy: null };
    if (capability.availability === "unavailable") {
      const by = capability.cause === "ok" ? "game" : capability.cause;
      return { ...base, state: "blocked" as const, blockedBy: by, warning: laneWarning(capability, meta.label, i.ctx) };
    }
    const kind = LANE_GATE[lane];
    if (kind) {
      const g = canAsset(i.plan, kind, i.change ? "edit" : "create");
      if (!g.ok) {
        const sub = capability.substitute ? ` Cyrus will build ${capability.substitute} instead.` : "";
        return { ...base, state: "blocked" as const, blockedBy: "plan" as const, ...(g.needs ? { needsPlan: g.needs } : {}), warning: `${meta.label}: ${g.reason.replace(/\.$/, "")}.${sub}${g.needs ? ` Unlock the ${PLAN_NAME[g.needs] ?? g.needs} plan to get them.` : ""}` };
      }
    }
    return { ...base, state: "build" as const, warning: capability.availability === "limited" ? `${meta.label} are limited on ${i.ctx.gameName} ${i.ctx.version}: ${capability.reason}.` : null, blockedBy: null };
  });
  const warnings = lanes.filter((l) => l.state === "blocked" && l.warning).map((l) => l.warning!);
  return {
    game: i.ctx.game, version: i.ctx.version, source: i.source, lanes,
    creates: lanes.filter((l) => l.state === "build").map((l) => `${l.label}${l.why ? `: ${l.why}` : ""}`),
    warnings,
    mustConfirm: warnings.length > 0,
  };
}

export const builtLanes = (p: Pick<ModPlan, "lanes">): Lane[] => p.lanes.filter((l) => l.state === "build").map((l) => l.lane);

/**
 * The approved plan as the build's explicit `assets` request (lib/cyrus/assets/request.ts reads it). `plan: 1` marks a
 * PLANNED request: the server uses exactly these lanes instead of keyword matching (and still re-checks plan, version
 * and switches). Only lanes in state "build" are requested: a blocked lane never reaches the build.
// Cyrus mod planner: the PRE-BUILD gate (pure). A plan with a lane the prompt needs but this game/version/plan cannot
// produce must be confirmed ("Continue anyway") BEFORE any tokens are held: lib/modbuilder/create.ts calls this before
// gateBuild (the hold), so a refused request never creates a reservation. API callers that cannot show a plan screen
// (API v1, the plain builds route) pass `requireAck: false` and get the same warnings back as asset notices instead.
import type { ModPlan } from "./decide";

export type PreBuildCheck = { ok: true } | { ok: false; status: 409; json: { error: string; code: "plan_confirm"; warnings: string[] } };

export function preBuildCheck(plan: Pick<ModPlan, "mustConfirm" | "warnings">, opts: { requireAck: boolean; ack: unknown }): PreBuildCheck {
  if (!opts.requireAck || !plan.mustConfirm || opts.ack === true) return { ok: true };
  return { ok: false, status: 409, json: { code: "plan_confirm", warnings: plan.warnings, error: `Before you spend anything: ${plan.warnings[0]}${plan.warnings.length > 1 ? ` (and ${plan.warnings.length - 1} more)` : ""} Press "Continue anyway" to build without it.` } };
}
const fill = (s: string, ctx: CapabilityContext) => s.replaceAll("{version}", ctx.version).replaceAll("{game}", ctx.gameName);

export function resolveLane(c: CapabilityCatalogue | null | undefined, lane: Lane, ctx: CapabilityContext): LaneCapability {
  const rule = c?.lanes[lane];
  if (!rule) return { lane, availability: "unavailable", reason: `${ctx.gameName} has no capability entry for this yet, so Cyrus does not offer it.`, substitute: null, minVersion: null, cause: "game" };
  const base = { lane, substitute: rule.substitute ? fill(rule.substitute, ctx) : null, minVersion: rule.minVersion ?? null };
  if (rule.base === "unavailable") return { ...base, availability: "unavailable", reason: fill(rule.reason, ctx), cause: "game" };
  if (rule.requires && !ctx.hasCapability(rule.requires.capability)) {
    const fb = rule.requires.fallback;
    if (fb && ctx.hasCapability(fb.capability)) return { ...base, availability: "limited", reason: fill(fb.reason, ctx), cause: "version" };
    return { ...base, availability: "unavailable", reason: fill(rule.requires.reason, ctx), cause: "version" };
  }
  if (rule.flag && !ctx.flags?.[rule.flag]) return { ...base, availability: "unavailable", reason: `${fill(rule.reason, ctx).replace(/\.$/, "")}, but it is not switched on in Cyrus yet${rule.soon ? ` (${rule.soon})` : ""}.`, cause: "flag" };
  return { ...base, availability: rule.base, reason: fill(rule.reason, ctx), cause: "ok" };
}

/** The whole "what this version supports" panel, in lane order. */
export function resolveCapabilities(c: CapabilityCatalogue | null | undefined, ctx: CapabilityContext): LaneCapability[] {
  return LANES.map((l) => resolveLane(c, l, ctx));
}

